import{C as e,L as t,V as n,_ as r,b as i,x as a}from"./vue-DJZSiPbu.js";import{r as o}from"./app-a38lz1Y_.js";var s=JSON.parse(`{"path":"/read/extra/E4.html","title":"4 逢赌必输的赌城风云 | 阅读","lang":"zh-CN","frontmatter":{"title":"4 逢赌必输的赌城风云","description":"「哈！你在说什么啊？本大爷才不会因为赌博就吓得落荒而逃呢！」 达斯特接下爱丽丝的随扈蕾茵的委托，负责跟踪及监视和真一行人，前往以赌博大国闻名的邻国埃尔罗得。 看到挚友在赌场大获全胜，达斯特也挪用了委托的订金，尽享赌博之乐，却一步步被拉上无法回头的舞台——！ 「等等，达斯特先生！！！真、真的没问题吗？」 赢了就能重获自由，输了就万事休矣。「幸运值最低」的...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"4 逢赌必输的赌城风云\\",\\"image\\":[\\"\\"],\\"dateModified\\":null,\\"author\\":[]}"],["meta",{"property":"og:url","content":"https://ajtn123.github.io/konosuba/read/extra/E4.html"}],["meta",{"property":"og:site_name","content":"素晴"}],["meta",{"property":"og:title","content":"4 逢赌必输的赌城风云"}],["meta",{"property":"og:description","content":"「哈！你在说什么啊？本大爷才不会因为赌博就吓得落荒而逃呢！」 达斯特接下爱丽丝的随扈蕾茵的委托，负责跟踪及监视和真一行人，前往以赌博大国闻名的邻国埃尔罗得。 看到挚友在赌场大获全胜，达斯特也挪用了委托的订金，尽享赌博之乐，却一步步被拉上无法回头的舞台——！ 「等等，达斯特先生！！！真、真的没问题吗？」 赢了就能重获自由，输了就万事休矣。「幸运值最低」的..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}]]},"readingTime":{"minutes":223.35,"words":67005},"git":{"createdTime":1784183213000},"autoDesc":true,"filePathRelative":"read/extra/E4.md","headers":[]}`),c={name:`E4.md`};function l(o,s,c,l,u,d){let f=n(`ImageView`);return t(),i(`div`,null,[s[0]||=r(`p`,null,`「哈！你在说什么啊？本大爷才不会因为赌博就吓得落荒而逃呢！」`,-1),s[1]||=r(`p`,null,`达斯特接下爱丽丝的随扈蕾茵的委托，负责跟踪及监视和真一行人，前往以赌博大国闻名的邻国埃尔罗得。`,-1),s[2]||=r(`p`,null,`看到挚友在赌场大获全胜，达斯特也挪用了委托的订金，尽享赌博之乐，却一步步被拉上无法回头的舞台——！`,-1),s[3]||=r(`p`,null,`「等等，达斯特先生！！！真、真的没问题吗？」`,-1),s[4]||=r(`p`,null,`赢了就能重获自由，输了就万事休矣。「幸运值最低」的人渣，今晚将挑战命运二择一的赌局。`,-1),s[5]||=r(`p`,null,`赌上志气、尊严和萝莉梦魔贞操（？）的终极对决，即将揭幕！`,-1),e(f,{src:`/images/E4/00.avif`,alt:`封面`,width:`850`,height:`1257`}),e(f,{src:`/images/E4/15.avif`,alt:`扉页`,collapsed:``,width:`850`,height:`1257`}),s[6]||=r(`h2`,{id:`彩页`,tabindex:`-1`},[r(`a`,{class:`header-anchor`,href:`#彩页`},[r(`span`,null,`彩页`)])],-1),e(f,{src:`/images/E4/08.avif`,alt:`彩页插图 1`,width:`850`,height:`1591`}),e(f,{src:`/images/E4/12.avif`,alt:`彩页插图 2`,width:`850`,height:`1591`}),e(f,{src:`/images/E4/05.avif`,alt:`角色介绍`,width:`850`,height:`1257`}),e(f,{src:`/images/E4/11.avif`,alt:`目录`,width:`850`,height:`1257`}),s[7]||=a(`<h2 id="序章" tabindex="-1"><a class="header-anchor" href="#序章"><span>序章</span></a></h2><p>我跟小鬼在像是设置于地底下的赌场内相对而坐。</p><p>一旁放满了各式各样的赌博道具。</p><p>小鬼身后站了一排全副武装，实力坚强的护卫。只要稍有闪失，应该马上就会被他们制伏在地吧。</p><p>我似乎也有点紧张，一直下意识地抚摸我的爱剑。</p><p>穿着一条内裤坐在墙角的泰勒乖乖待在那里不动，但另一个只穿内裤的男人奇斯却在闹别扭。</p><p>琳恩想尽办法要掩盖自己那身跟内衣没两样的打扮，躲在萝莉梦魔身后，视线却紧盯着我不放。</p><p>待会儿我必须跟眼前那个小鬼进行一场终极对决。</p><p>虽然只要取胜就没事，但要是输了……</p><p>我简单说明规则之后，小鬼似乎接受了我的提案。</p><p>「好。抽一张就行了吧。」</p><p>那个嚣张至极又爱装大人的屁孩选了一张牌。</p><p>他丝毫不认为自己会输。对赌博似乎充满自信。</p><p>我也伸手准备取牌，却在那之前产生了犹豫。</p><p>周遭忽然变得鸦雀无声，于是我有些在意地往旁边一看，只见萝莉梦魔紧闭双眼，做出了祈祷动作。</p><p>我也想学她向神祈祷看看，但这么做不是我的作风。</p><p>「都见过本人了，向祂祈祷说不定有效……但还是算了。」</p><p>我仔细盯着排在眼前的十二张牌。</p><p>锁定其中一张牌后，我伸出了手。</p><p>老实说，我心中满是忐忑，但也只能相信我的狗屎运了——</p><p>「我选这张！」</p><p>我也决定卡牌后，王子轻轻地点了点头。</p><p>「就由我先翻牌吧。行吗？」</p><p>「你先请。」</p><p>我虽然马上给出答案，但放在卡牌上的手心却沁出了汗。</p><p>看来事到如今，我还是相当紧张。</p><p>为了稍微滋润干渴的喉咙，我嚥了嚥口水。</p><p>没问题，没问题。</p><p>我只能对自己如此喊话，并仔细看着眼前那张被对手翻开的牌。</p><p>对手缓缓翻过的牌面数字是——</p><h2 id="第一章-木头人也迎来了春天" tabindex="-1"><a class="header-anchor" href="#第一章-木头人也迎来了春天"><span>第一章 木头人也迎来了春天</span></a></h2><h3 id="_1" tabindex="-1"><a class="header-anchor" href="#_1"><span>1</span></a></h3><p>看到在冒险者公会里直盯着女人屁股的奇斯，以及又在啃蔬菜棒的琳恩后，我便加快脚步走近。</p><p>我今天又感受不到钱包的重量了，所以想叫这两个人请我吃午餐。</p><p>「嗨～～奇斯，你今天看起来比平常更帅气呢。哇～～受欢迎的男人气场就是不一样，借点钱来花花吧。」</p><p>「……你的拍马屁技术还要再多练练才行。」</p><p>奇斯托着腮帮子，一脸傻眼的模样。</p><p>看样子作战失败了。应该是我用错字眼了吧。这种露骨的谎言跟现实相差太过悬殊，才会被一眼看穿。</p><p>算了。还有另一头肥羊。</p><p>这次就用符合现实的赞美吧。</p><p>「哦！琳恩今天心情好像不错喔，皮肤也超级弹润呢。是不是大出来了？你最近好像有便秘的困扰——」</p><p>「『Lightning』！」</p><p>「唔喔喔喔！」</p><p>好险……我在千钧一发之际，闪过了琳恩代替回答的那道电击。</p><p>闪电没打中我，窜出敞开的窗户飞向天际了。</p><p>「混帐，不要忽然击发魔法啦！」</p><p>「是你的问题吧。干嘛对正在吃东西的女孩子说那种话。」</p><p>「不好意思，麻烦不要在公会里使用魔法好吗？」</p><p>我和琳恩互瞪着彼此。这时小心翼翼地开口打断我们的人，正是在冒险者公会的柜台小姐中最受欢迎的露娜。她那对丰硕无比的巨乳，今天也晃个不停。</p><p>「哦，再继续说啊！既然是巨乳大人的箴言，她说不定会听进去喔！快说吧！区区一个平胸女，不准反抗巨乳大人！」</p><p>「这家伙……下次我一定会打中你。不好意思，我在击发之前，有先估算过不会对公会造成损害。」</p><p>闪电之所以会从窗户飞出去，不是单纯的巧合，而是如她所料吗？</p><p>「那就好。」</p><p>「好个屁！不要接纳她的说词啦！要是我刚刚被打中了，搞不好会让一个值得信赖的冒险者终身瘫痪喔！这对公会来说是一大损失吧！」</p><p>「咦？达斯特先生的武力确实很高强，但跟你引起的祸端相抵的话……我还觉得互相抵消已经很划算了呢。」</p><p>她不以为然地说出惊人之语。</p><p>「而且打中我的话，周围的桌椅都会坏掉耶。琳恩，到时候你就得付赔偿金喽。」</p><p>「因为我相信达斯特会躲开呀。」</p><p>不要看着我摆出双手合十祈祷的姿势。</p><p>「你根本不这么想吧……」</p><p>「总而言之，两位要吵架的话，麻烦请移驾到室外。」</p><p>说完，露娜就回去工作了。</p><p>……既然是冒险者公会职员，应该要出手制止吧。</p><p>「所以，你们要借我钱还是请我吃饭？选一个吧。」</p><p>「在这种情况下，你还觉得我们会请你吃饭吗……」</p><p>「你跩什么啊？」</p><p>「哼！爽快地请我这个队长吃顿饭，你们就能确保小队中的立场啊。如果够诚恳，我还可以任命你们当副队长喔。」</p><p>听我一脸帅气地说完，两人同时叹了口气。</p><p>这是什么反应？</p><p>「你现在没喝酒也会耍酒疯了吗？之前就决定队长是泰勒了吧。你忘了吗？」</p><p>「达斯特是队长的话，我们老早就解散了。」</p><p>「……咦？这话是认真的吗？我达斯特大人才是这个小队里真正的可靠队长吧！」</p><p>这番意想不到的说词，让我不禁哑口无言。</p><p>接受委托和领取报酬这些事，确实是由泰勒负责，但他只是帮我处理各种琐事而已吧？</p><p>因为很方便，我就让他暂代队长一职，把杂事全丢给他做。</p><p>「才没这回事。让你当上队长，就跟自杀志愿者没两样。」</p><p>「你只能在监狱里称王吧。」</p><p>「说得太狠了吧！哈，那我们那位可靠的队长大人是跑去哪里了啊！居然在重要的会议中做出如此失职的事！」</p><p>我用力拍响桌面，环顾着四周大吼出声。</p><p>「这种无聊的对话，算哪门子会议啊。」</p><p>泰勒平常都会第一个到公会确认委托，偏偏今天却不见踪影。我用双眼搜遍了公会的每一个角落，却没看见他的身影。</p><p>「对了，泰勒最近是不是很忙啊？感觉很少待在公会里。」</p><p>「……经你这么说才发现，我虽然常常遇到奇斯和琳恩，却好几天没看到泰勒了……」</p><p>在奇斯开口之前，我都没发现这件事。最后一次见到那家伙是几天前的事了？</p><p>前几天好像有看到他跟某个人在一起，又好像没有。当时我喝得酩酊大醉，记忆很模煳。</p><p>「泰勒很忙啦，跟你们不一样。」</p><p>琳恩看着我们，露出一抹坏心的笑容。刚刚那句耐人寻味的发言是怎么回事？</p><p>「什么意思？琳恩，你知道泰勒为什么这么忙吗？」</p><p>「你们果然没发现啊。」</p><p>「喂喂，什么事啊？不要私藏秘密，告诉我们嘛。」</p><p>「就是嘛。伙伴之间不能有秘密。」</p><p>听到奇斯说的话，我的肩膀震了一下。</p><p>我还以为他在说我，身体忍不住起了反应。未来的某一天，或许就得将我的秘密告诉他们才行。</p><p>……不过这是两码子事！我无论如何都要问出泰勒的秘密。</p><p>「他最近好像跟一个冒险者走得很近。是女孩子。」</p><p>闻言，我默默地和奇斯互看一眼。</p><p>只见他皱紧眉头，一脸不悦。我大概也是同样的表情吧。</p><p>「嗯～～得把耳朵清干净才行了。居然听见了奇怪的幻听。」</p><p>「达斯特也是吗？可能有颗大耳屎堵住耳朵了呢。」</p><p>我们不约而同地挖了挖耳朵，并重新看向琳恩。</p><p>「麻烦你再说一次。」</p><p>「他好像跟可爱的后辈女冒险者走得很近。」</p><p>「「……啥啊啊啊啊啊啊！」」</p><p>这句不可置信的话语，让我发出了惊叫声。</p><p>那个木头人泰勒，居然有女人了！</p><p>「开什么玩笑！他可是以拘谨还有对女人无感著称的泰勒耶！如果是奇斯有女人，那还说得过去！」</p><p>「我可不记得泰勒有那种称号。」</p><p>「不不不，给我等一下。太奇怪了吧！要是连泰勒都有桃花，那我怎么办！达斯特也时不时会跟女人扯上关系，难道只剩下我了吗！」</p><p>我和奇斯都抱头惊声尖叫，琳恩却冷冷地看着我们。</p><p>其中一个伙伴可能要背叛我们了耶！她会不会太冷静了？</p><p>「琳恩，你怎么可以满不在乎啊？单身同盟说不定要分裂了耶。」</p><p>「我不记得自己有加入那种同盟，但我觉得很好啊。要是有人愿意跟你们交往，我可能会觉得对方脑子有问题，但如果是泰勒就能理解。」</p><p>「最好是能理解啦！那家伙严肃又不讨喜，如果要从我跟他之间做选择，大部分的女人应该都会选我！」</p><p>奇斯说得口沫横飞，我决定帮他多说几句。</p><p>「就是说啊！不管怎么想，我们都比泰勒受欢迎吧！你们说对不对！」</p><p>我知道附近的冒险者们都看着这里偷听我们讲话，就转过头去质问他们。</p><p>「哪有。不管怎么想，都是泰勒比较优质吧。」</p><p>「少来了。如果要跟奇斯或达斯特交往，我不如加入阿克西斯教。」</p><p>「嗯嗯。连哥布林都比你们诚实。」</p><p>这、这些人还真敢说……</p><p>原先保持沉默的人，也都趁势对我们发出批判和埋怨。</p><p>在后方听见这番话的公会职员们更是频频点头。</p><p>「你们这些家伙！刚刚说要加入阿克西斯教是吧？我会把这件事转告宴会祭司，给我走着瞧！奇斯，不要不讲话，你也骂几句回去啊！」</p><p>「我们的评价居然差到这种地步……」</p><p>啊，奇斯跌坐在地，真的灰心丧志了。</p><p>我也觉得很受伤，但受到的打击没有奇斯那么严重。</p><p>可能是最近被悠悠和萝莉梦魔痛骂的机会变多了，我也培养出耐受力……真让人高兴不起来。</p><p>不过，这些家伙真敢大放厥词啊。好，我就假藉袒护奇斯的名义，威胁他们狂敲一笔。</p><p>「你们看，奇斯都哭哭了！你们这些人还有良心吗！一群可恶的坏蛋！要是觉得愧疚就借我钱，或是请我吃饭！」</p><p>我紧拥着可怜兮兮的奇斯，如此吼道。</p><p>我原本想唤起众人的良心，没想到大家竟然同时——</p><p>「「「「哈！」」」」</p><p>对我嗤之以鼻。</p><p>「借钱不还就算了，还想借更多的家伙才是坏蛋吧。」</p><p>「而且逼你还钱，居然还会恼羞成怒。快点还我！」</p><p>「之前你冒用我的名义骗了警察对吧！」</p><p>可恶，叫骂声越演越烈。</p><p>这下情势对我不利。不把话题支开的话，过往的恶行会接二连三被翻出来。</p><p>「别、别说这些了。有人知道跟泰勒走得很近的那个女人是谁吗！」</p><p>我用足以压过辱骂声的音量大吼一声后，大家暂时都静了下来。</p><p>有些头绪的人们，开始嘀咕着「喔喔，是她啊」、「之前有见过」之类的话。</p><p>「虽然不太清楚，但泰勒最近确实带着一个新手冒险者，还会传授她一些冒险者的心得。毕竟那家伙很会照顾人，又是个好好先生嘛。」</p><p>在这个公会资历颇深的一名冒险者，摸着下巴这么说道。</p><p>可能是受到这句话的启发，其他人也陆续说出目击过泰勒和女冒险者在一起的证言。</p><p>「真的假的……该死，他也太见外了吧。既然是伙伴，就该先跟我们说一声啊。对吧，奇斯？」</p><p>我将话题丢给奇斯，结果他维持抱膝而坐的姿势，就这么往一旁倒去。</p><p>「我已经无所谓了……」</p><p>不行，他受到的创伤比想像中还要严重。暂时派不上用场了。</p><p>「算了啦。既然如此，你就别插手了。」</p><p>「王八蛋！我们家的宝贝队长可能有女人了耶。身为同伴……得献上祝福才行嘛。嘻嘻嘻嘻。」</p><p>「不要露出那种邪恶的表情啦。我真是对不起泰勒。」</p><p>我要好好评估一下，对女人一窍不通的泰勒眼光有没有问题。得蒐集一些情报，看看对方配不配得上我们队长大人。</p><p>既然是新手冒险者，向公会职员打听应该比较快，但我不认为他们会向我透露个资。这样一来，只要问问熟知公会谣言和情报的人就行了。</p><p>我心里已经有人选了。那家伙待在公会里的时间，应该是继职员之后最长的。</p><h3 id="_2" tabindex="-1"><a class="header-anchor" href="#_2"><span>2</span></a></h3><p>「嗨，悠悠。有些事想问问你这位孤傲之巅。」</p><p>刚才悠悠难得不在公会里，这时才在除了我之外无人察觉的状况下走进冒险者公会。于是我上前向她搭话。</p><p>「身为红魔族，虽然对这有点帅气的称号略为心动，但我不会上你的当。就算你下跪乞求，我也不会借钱——」</p><p>「我今天不是要借钱。如果你愿意借，我也随时欢迎啦。不说这些了。关于泰勒的传言，你知道些什么吗？」</p><p>「啊，泰勒先生吗！难道是指最近跟他走得很近的那个冒险者？」</p><p>悠悠的声音听来很雀跃，因为她很喜欢恋爱话题。明明自己没有异性缘，却对别人的爱情故事一头热。</p><p>「没错。毕竟那家伙没有恋爱经验，我担心他会被奇怪的女人所骗。如果你知道些什么，希望你能告诉我。再琐碎的小事都没关系……琳恩是这么说的。」</p><p>「琳恩小姐吗？」</p><p>她对我可能会起疑心，但只要搬出琳恩，那就另当别论。</p><p>琳恩最近常跟她接触，聊天的机会也增加不少。如果是她的要求，渴望朋友的悠悠应该比较容易松口。</p><p>「是啊。站在伙伴和朋友的立场，琳恩很担心泰勒会掉进坏女人的圈套，小到不行的胸口都隐隐作痛呢。若你能提供任何宝贵的情报，她一定会感恩在心～～」</p><p>「尽管问吧！我会知无不答！」</p><p>悠悠喘着粗气凑上前来。幸亏这家伙很好操控。</p><p>「听说是个女的新手冒险者，这是怎么回事？」</p><p>「我想想，约莫是两周前吧。在那之前，我从来没在公会里见过那个人。之后她就常常过来看委托，同时观察公会的内部情况。」</p><p>「观察？」</p><p>「嗯。如果是新手冒险者，说不定能跟她交个朋友，所以我一直盯着她看，肯定不会有错。她好像很紧张，总是用热切的眼光看着每个冒险者。」</p><p>新手冒险者能意气风发地踏进公会当然很好，但大部分都会表现出担心犹疑的模样。</p><p>光是想像悠悠一直在观察担心受怕的新人，就觉得有点恶心。但我还是别说得好。</p><p>「大概是一周前左右吧，泰勒先生和那位新人一起回到公会。我坐在附近，就听见他们的谈话……啊！我没有偷听的意思喔！我不会做出那种失礼的举动！」</p><p>「那种事无所谓啦。重要的是谈话内容。他们应该没有卿卿我我地聊下流的话题吧？」</p><p>「他又不像达斯特先生。嗯～～好像是那位新人独自打怪的时候，被泰勒先生出手相救，他就趁这个机会，传授新人一些冒险者的心得。泰勒先生好温柔呀。」</p><p>原来如此。毕竟那家伙很热心嘛。</p><p>他应该没办法放着新人不管吧。</p><p>这么一来，感觉只是单纯的师兄妹而已。看来是我贸然对他心生妒忌了。</p><p>「是前后辈关系啊。也不至于到不可饶恕的地步啦。只要之后介绍给我认识就行。」</p><p>「你为什么摆出高高在上的态度啊？不过，我看那位新人的眼神，好像完全迷上泰勒先生了呢。那是坠入爱河的少女的眼神！」</p><p>「……不是对前辈冒险者的仰慕之情而已吗？」</p><p>「嗯～～我觉得没这么单纯……」</p><p>爱上泰勒的少女啊。</p><p>不、可、饶、恕。</p><p>那位新人大概不晓得公会里还有像我这种更加优质的冒险者，才会一时鬼迷心窍，误以为偶然出手相助的泰勒是个好男人吧。一定是这样！</p><p>「你怎么啦？干嘛咬着嘴唇？」</p><p>「顺带一提，那个新人的长相如何？」</p><p>「是有着一头亮丽黑长发的大美女喔。而且明明很纤瘦，却有前凸后翘的好身材！」</p><p>「我要杀了他！」</p><p>「怎、怎么突然说这种话！」</p><p>不小心说出真心话了。</p><p>该死的家伙，竟敢独占前凸后翘的美女大姊姊。我身边尽是些胸前贫嵴的女人，唯一发育良好的，却是个边缘人小鬼头。</p><p>「你在看哪里啊。我要告你性骚扰喔！」</p><p>悠悠用手遮住胸前，我不以为然地冷哼了一声。</p><p>既然如此，我就要直接跟那个女人见面，灌输一些有的没的，扯泰勒的后腿。</p><p>「好，开始调查吧！悠悠你也一起来。反正你一整天都自己玩，应该很闲吧。」</p><p>「才、才没有很闲呢。但我很在意这件事，就陪你一起去吧。」</p><p>要不要找琳恩一起去呢？虽然瞬间闪过这个想法，但那家伙应该会出手妨碍，于是我打消了这个念头。至于奇斯……他已经瘫死在地，我看还是别管他了。</p><h3 id="_3" tabindex="-1"><a class="header-anchor" href="#_3"><span>3</span></a></h3><p>我们立刻就查出了泰勒跟新人的行踪。因为悠悠一问，露娜马上就告诉她了。我问的时候明明什么也不肯说……</p><p>他们似乎接了简单的怪物讨伐委托，地点离阿克塞尔城外不远。两人感情这么好，还出远门了。</p><p>「因为冒险而萌芽的爱情，真是美好呀。」</p><p>「你在说什么？怎么可能会有那种事呢？讨伐怪物可是要赌上性命的，岂能用那种轻浮的心情迎战！要是稍有不慎，可能会赔上小命啊！」</p><p>「……真心话是什么？」</p><p>「我也想手把手地教导美女大姊姊！这样一来，就算趁手碰到胸部时轻轻揉个几下，她也不会生气吧？」</p><p>我忍不住老实回答。只见悠悠半眯着眼，冷冷地凝视着我。</p><p>唔，不小心中了诱导询问的陷阱了。</p><p>「达斯特先生，你真——————的无药可救了……啊，他们在那里！」</p><p>「可恶，还真的是个超级大美女。」</p><p>我把大声嚷嚷的悠悠拉到大树旁的阴影处。</p><p>我们从树干旁探出头来，偷窥那两人的一举一动。</p><p>泰勒似乎没有发现。只见他站在新人面前，一边与怪物对峙，一边热心地说了些什么。</p><p>那个女孩的外貌就像先前打听到的那样，有着一头黑色长发，胸臀也丰满到极点。</p><p>听说她是新手冒险者，我还以为年纪会更轻一点，但她看起来几乎跟泰勒同年。</p><p>敌人只是一只哥布林，我们应该不必出手帮忙。再往他们靠近一点好了。</p><p>我缓缓穿过林荫之间，与两人拉近距离。</p><p>「在这边应该就听得见声音吧。」</p><p>「如果正在进行爱的告白怎么办！」</p><p>不要陷入妄想，兴奋地狂打我的背好吗？被他们听见的话怎么办？</p><p>照这样看来，泰勒似乎很认真地在指导新人如何打败怪物。</p><p>「如果像十字骑士一样防御力很高的话，就能像这样负责引开敌人。但你跟达斯特一样是个战士，还是将心思放在提高速度上，闪避敌人攻击比较好。」</p><p>「好的，我明白了，泰勒师父！」</p><p>喂喂，居然叫他师父啊。</p><p>虽然泰勒不可一世地点了点头，表情看起来也是挺高兴的嘛。</p><p>「怪了，只是在认真打斗而已耶。」</p><p>「毕竟是木头人泰勒嘛，跟男女情爱这种事扯不上边啦。我始终坚信他们只是在认真打怪。」</p><p>「……刚刚不是还说要杀了他？」</p><p>「你的边缘指数是不是又恶化了？居然会出现这种自我感觉良好的幻听。」</p><p>「这、这个人真是……」</p><p>悠悠似乎想出言辩解，但我没理她，继续观察那两人的动静。但泰勒只是在传授打倒怪物的方法，以及冒险者的心得而已，一点意思也没有。</p><p>原先在一旁投以热切目光的悠悠，似乎也觉得不如预期。一看就知道她越来越没兴趣。</p><p>「辛苦了。休息一下吧。」</p><p>「好！」</p><p>对泰勒百依百顺的新人，从背包中取出一张埝子铺上地面后，两人便在上头并肩而坐。</p><p>光看两人和乐融融地品茶的画面，感觉只是感情要好的朋友。</p><p>「往后应该不需要我继续指导了。去找个同等级的伙伴比较好。」</p><p>「咦？好……说得也是。再这样下去，也会给泰勒先生添麻烦。」</p><p>「没、没这回事啦。」</p><p>看到新人悲伤地低下头，泰勒连忙打圆场。</p><p>这股几乎要蔓延至此的酸甜气氛……真让人不爽。</p><p>「他们果然对彼此有意思！看看那个寂寞的侧脸！……你、你干嘛突然脱衣服！」</p><p>「我要全裸冲出去，破坏那股令人作呕的甜蜜气氛！」</p><p>「快住手！老老实实地祝福伙伴的爱情吧！」</p><p>「我拒绝！别人的幸福只会让我火大！跟女人扯上关系更火大！」</p><p>「太、太差劲了！我不会让你妨碍他们的爱情！如果你非要这么做，就先打倒我再说！」</p><p>悠悠张开双手阻挡在我面前，一副随时要发动魔法的模样。</p><p>明明不关她的事，这家伙却能马上感同身受。如果善加运用这种性格，确实很容易操控，但在这种状况下只是个烫手山芋。</p><p>「哈！很遗憾的，你早就掉进我的圈套了。」</p><p>「我才不会被那种虚张声势的发言所骗。这次我也没在跟你开玩笑！」</p><p>「太天真了。你觉得这样大声嚷嚷，他们不会听见吗？」</p><p>「啊！」</p><p>事到如今，她才慌张地用手捂上嘴巴，但已经太迟了。</p><p>我们讲得这么大声，无论如何都会被他们发现。</p><p>我被转过头的悠悠挡住看不见后面，因此我把她推到一旁，窥看泰勒他们的模样。</p><p>结果该处早已没了人影。</p><p>「居然趁我跟悠悠斗嘴的时候转移阵地！可恶，他们跑去哪里了？」</p><p>「啊，等一下！不准妨碍他们！」</p><p>我用尽全力往前冲，甩掉拼命想跟过来的悠悠，同时在附近四处搜查，结果完全找不到那两人的踪影。</p><p>他们应该回去阿克塞尔了吧？</p><p>「该死！既然如此，我就照原定计划，直接跟那个女人狂说泰勒的坏话！」</p><p>虽然悠悠从远处往这里跑来，但还是装作没看见，直接回去阿克塞尔吧。</p><h3 id="_4" tabindex="-1"><a class="header-anchor" href="#_4"><span>4</span></a></h3><p>回到阿克塞尔后，我先来到冒险者公会。往里面一看，却没看见泰勒跟新人的踪影。</p><p>奇斯还趴在桌上一动也不动，琳恩隔着桌子坐在另一头。既然泰勒没跟他们坐在一起，就表示他们还没回来公会。</p><p>好了，接下来该怎么做呢？假设他们去吃饭，应该就会经过那条大街。那就去跟大叔打听看看吧。</p><p>「不、不要把我丢在后头好吗！」</p><p>悠悠上气不接下气地抓住我的肩膀。</p><p>被她追上了。</p><p>「没办法，我们就去杂货店一趟吧。」</p><p>要甩开她也挺麻烦的，不如带着她一起去。</p><p>「事情就是这样，你有看见泰勒吗？」</p><p>「他今天没有过来。小姐，你怎么还跟他混在一起啊？这家伙是个彻头彻尾的人渣，我劝你还是不要再跟他有往来比较好。」</p><p>「说得也是……」</p><p>不要一脸认真地烦恼这种事啊。</p><p>来到设立于大街上的杂货店后，我问大叔有没有看见泰勒，但他毫无头绪。</p><p>「喂喂，你是不是没在工作，在后面打混摸鱼啊？」</p><p>「那又怎样，这是我的店，你没资格批评我。不过，在他身边的是个黑色长发的大美女吧？」</p><p>「对啊。胸部跟屁股都超级丰满的大美女。你有印象吗？」</p><p>「前几天有个没见过的客人，来这里出售贵重金属跟装备。本来以为只是巧合而已，但跟你说的特征满吻合的。」</p><p>大叔歪着头，说了些奇怪的话。</p><p>「能不能说详细一点？」</p><p>「大概是四天前吧。有个客人拿了价值不斐的戒指、装饰品，以及尺寸不一的男性铠甲和长剑过来。虽然很多人会拿单品来卖，但我第一次遇到带了这么多不成套的道具来卖的客人。而且还是这附近从没见过的大美女，所以有点印象。」</p><p>……来卖东西？</p><p>很多冒险者不会在这间店购买新品，而是二手货。毕竟新人没什么钱，收购二手武器防具还算情有可原。</p><p>但她却拿来出售。感觉越来越可疑了。</p><p>「当时有没有哪里怪怪的？」</p><p>「毕竟我也不想收购赃货，所以就请她提供身分证明文件，结果她出示了冒险者卡片。因为没什么可疑之处，我就跟她收购了。」</p><p>「怎么回事……难道她是为了得到可以证明身分的文件，才会成为冒险者……」</p><p>「呃，请问，这件事是不是有点蹊跷？」</p><p>悠悠也发现那个新人很可疑了。</p><p>「喂，怎么了？难得看你这么认真沉思。是想到新的诈骗方式了吗？」</p><p>「什么跟什么啦！哎哟，没时间跟臭老头继续瞎扯了。再会。」</p><p>「喂、喂！居然说走就走……」</p><p>「抱歉，打扰你了！等等我嘛～～」</p><p>悠悠似乎在我背后说了些什么，但我没理她，直接走上大街。</p><p>看来这件事值得一查。</p><p>我一点都不担心泰勒。但如果那女人是个罪犯，逮住她再交给警察的话，说不定能拿到一笔奖金。</p><p>虽然不清楚她是从哪里拿到贵重金属和装饰品，但卖掉赚了一笔钱之后，就一定会去那些地方。</p><p>不是赌博、酗酒，就是玩女……不对，她也是女人，应该不会去玩女人才对。既然如此，应该是去购物吧。</p><p>先到我常去的赌场看看好了。</p><h3 id="_5" tabindex="-1"><a class="header-anchor" href="#_5"><span>5</span></a></h3><p>久违来到赌场后，我就被入口处那名凶神恶煞的围事拦住了。</p><p>「喂，没看到这行字吗？」</p><p>我循着他那大得离谱的手指看去，发现该处贴了一张纸——</p><p>『本店谢绝会滋生事端的没钱顾客。严禁达斯特入店。』</p><p>上面写着这行字。</p><p>「你这次又闯了什么祸？」</p><p>「哪有啊。怎么回事？你知道我在这里砸了多少钱吗？我是贵客吧！」</p><p>「话是没错，你的赌博技术奇差无比，从来没赢过。但你不要输光后就找赢钱的客人蹭饭！也不要搭讪我们的女荷官！」</p><p>「大赚一笔的人出钱请客，金钱才能公平又顺利地流通啊。这就是经济好吗！而且，看到美女就上前搭讪，是一种礼貌吧！」</p><p>「之前你偶然赌赢一次，不是一个人独占奖金，还马上就冲出去了吗？我们家荷官也抱怨过『拜托处理一下那个拼命倒贴的恶心小混混』。」</p><p>这是什么烂店啊。我再也不会光顾了！</p><p>赌到一半的时候，那个荷官还用娇媚的声音说「达斯特先生一定能获胜」这种话，逼我砸下重金豪赌一把耶。</p><p>「而且最近有个家伙跑来大闹赌场，我们都快忙不过来了，根本没空理你。」</p><p>「什么意思？」</p><p>「有个女人在阿克塞尔的赌场到处捞钱，我们也遭殃了。好几个客人都赔上了钜款和装备呢。」</p><p>「……能不能把那个女人的事情说得详细一点？」</p><p>「干嘛跟你说啊……算了，我就告诉你吧。如果看到她就跟我说一声。最近出现一个赌艺高强的女人。因为她从没输过，感觉像是在耍老千，但却搞不懂她的手法为何。不过看她的手法不像外行人，我们怀疑她可能是同业。」</p><p>听完那个女人的手段，以及更详细的情报后，我们离开了赌场。</p><p>随后，我们又去了好几间赌场，进行大同小异的对话，收集到各种情报。还顺便从认识的冒险者口中问出了一些端倪。</p><p>「啊～～朋友的朋友好像被扒得一点也不剩，还献上了为数不多的所有存款。她的话术超强，还动用女人的武器，光是回想起来就让我火冒三丈……你说朋友的朋友就是我自己？说、说什么傻话！这、这怎么可能啊，咕哈哈哈哈哈……唉……」</p><p>「那个女人啊……明明是她主动凑过来的，居然还跑去跟别的男人搭话。我逼问她之后，她却对我说『跟我赌一场吧。谁赢了，我就跟谁交往。如果我输了，可以对我为所欲为，当作我的赔礼。』这种求之不得的好事，只要是男人就会上钩吧！呐，你懂我的心情吗？是男人就会跟她赌一把吧！」</p><p>「听到她泪流满面地说妹妹为病所苦，多多少少会想帮她筹钱吧？不、不过，我确实起了一点色心，以为可以借机跟她培养感情……」</p><p>集结这些受骗上当的蠢货所提供的情报后，我终于知道传说中那个大闹赌场的女人是谁了。肯定就是把泰勒尊为师父的那个新手冒险者。</p><p>看样子，除了泰勒以外，她还跟好几个冒险者走得很近，让他们掏出大把金钱和贵重金属。还会依据对象不同改变作案手法，行径非常恶劣。</p><p>有人被她那丰盈欲滴的身材和性感所迷惑，也有人被家人陷入不幸的苦肉计所骗。</p><p>上当的那些人的确很蠢，但她的所作所为就是诈欺的勾当。</p><p>再用诈骗得手的钱财，狂买高价的服饰和宝石。</p><p>「那个新人是个超级坏女人呢。」</p><p>「不会吧……她看起来非常老实耶。」</p><p>「不能单凭外表判断一个女人。酒店的大姊姊就会尽其所能地让客人掏钱，把他们的钱包榨干之后，就扔到一边去喔。不过，这个情势发展真是出乎我的预期。好了，这下子要怎么办呢？」</p><p>原本只是想随便干扰一下他们的恋情，没想到女方却大有问题。</p><p>只要向泰勒揭发新人的秘密，事情就能落幕了。可是……</p><p>「该怎么做呢？还是告诉泰勒先生比较好吧？说不定他会跟其他人一样被诈财。」</p><p>「说了又能怎样？中了那种女人的圈套，是他自己不好。就算泰勒被敲诈一笔，也是自作自受。」</p><p>「怎么这样说……你们不是伙伴吗……」</p><p>「不过，把得意忘形的家伙翘得老高的鼻梁骨狠狠打断，感觉很有趣呢。你不这么认为吗？」</p><p>这么做绝对不是为了泰勒。那个女人从一群笨蛋手中骗走一大笔钱，还为此沾沾自喜。如果反过来将她一军，感觉也不赖。</p><p>既然要拐骗坏女人，就不必手下留情了。</p><h3 id="_6" tabindex="-1"><a class="header-anchor" href="#_6"><span>6</span></a></h3><p>「小姐，请留步。没错，这位有着亮丽黑发，以及让人想狠狠拥入怀中的惹火身材的小姐，就是你。」</p><p>「啥？在说我吗？」</p><p>懒洋洋地这么回话的女人，就是那位新手冒险者。</p><p>这种爱理不理的态度，跟和泰勒在一起时判若两人。</p><p>「正是。你似乎深受幸运之神的眷顾，让老夫有些在意，忍不住就开口喊住你了。」</p><p>之所以用这种老人的口气说话，是有原因的。</p><p>现在我贴上了白色假胡子，戴着一副圆眼镜。</p><p>还打扮成占卜师的模样，守在女人经常出入的服饰店旁的道路上。</p><p>「哦？幸运之神啊。这么说也对，你很有眼光嘛。好啊，我身上有钱，就给你占卜一下吧。」</p><p>「非常感谢你。来，请坐。」</p><p>女子在覆盖白布的桌子另一头坐了下来。</p><p>就近一看，这女人确实性感到想让人狠狠拥入怀中啊。</p><p>跟泰勒在一起的时候，明明一副天真开朗，个性直率的新手样。女人真是太可怕了。</p><p>「请注视这颗水晶球。如此一来，老夫便能透视你的过去与未来。唔唔唔，看见了！你是个冒险者对吧？」</p><p>「看我这身打扮，谁会不晓得啊。」</p><p>确实如此。身穿皮革铠甲，还带着一把剑。如果不是冒险者的话，就只是个危险分子，不然就是武器狂。</p><p>她的反应有些差强人意，但接下来就让她见识见识我的占卜实力吧。</p><p>「今天早上，你想起昨晚没卸妆就睡了。连忙卸妆后，还洗了个澡吧。你会从脚趾开始慢慢往上洗，胸部会洗得特别仔细……真的假的？老大，这部分请说得详细一点。」</p><p>「咦！你怎么知道！」</p><p>「呵呵呵。因为老夫是个优秀的占卜师，一切都逃不过老夫的法眼。接着说说你现在穿的内衣颜色吧……好啦，干嘛这么小气，快告诉我啊。有什么关系，老大你也看到了吧？」</p><p>「喂。你从刚刚就低着头在碎念什么啊？有人在里面吗？」</p><p>女子向我投来怀疑的眼神。</p><p>不表现得自然一点，就要露出马脚了。得小心行事才行。</p><p>「你在说什么啊？哪有人躲在桌子底下呢？别说这些了，继续占卜吧。小姐，接下来你会陷入不幸的深渊。」</p><p>「不幸？哈，你在开玩笑吧。来到这个镇上之后，我钓到一大堆好骗的肥羊，简直爽翻天了。每天都能挥霍无度呢。」</p><p>因为欲望而扭曲的笑容，让那张难得的美貌顿时化为泡影。</p><p>在泰勒面前表现出来的样貌果然是假的，这才是她的本性。</p><p>「命运是轮回之物。获得无比幸运之人，往后必定会迎来命运的反噬。而且……如果是透过欺瞒，让人深陷不幸夺取而来的幸运，反噬现象会更严重。」</p><p>「听你的语气，就像从头到尾都看在眼里似的……」</p><p>她忽然面无表情地向我投来冷漠的视线。</p><p>「哈！我知道了。看来你朋友不是在赌桌上输我一大笔钱，就是对我献殷勤的蠢货吧？很遗憾，我没这么嫩，不会被这种话影响。想骗我，还早个一百年呢。重新投胎再来吧。」</p><p>说完，女子便转身准备离去。我往她的背影喊了一声。</p><p>「当大地为之撼动，便是灾祸降临之时。这不幸的预兆，唯独小姐方能体会。莫忘老夫的这番话啊。」</p><p>「好好好，下次说谎前先打篇草稿吧。」</p><p>女子背对着我挥挥手后，便消失在巷弄之中。</p><p>照理来说果然不会相信吧。但应该会让她起点疑心。</p><p>我脱下这身占卜师的伪装，大大地伸了个懒腰。</p><p>虽然现阶段她还在盘算如何欺骗泰勒，尚未造成实际损害。但要是放任不管，近期之内，泰勒一定也会沦为那群上钩的肥羊之一。</p><p>「老大，多亏有你帮忙。」</p><p>我将覆盖桌面的白布掀开，对抱膝坐在桌底下的巴尼尔老大道谢。</p><p>刚刚的占卜，全都仰赖老大的千里眼之力。他只是将看到的结果如实传达给我罢了。</p><p>巴尼尔老大钻出桌底下，站起身子后，勾起一抹邪佞的笑容。</p>`,384),e(f,{src:`/images/E4/16.avif`,alt:`插图`,width:`850`,height:`1260`}),s[8]||=a(`<p>「呼哈哈哈哈！只有歪脑筋动得特别快的小混混啊，无须在意。吾就喜欢这种恶作剧！欺瞒人类，正是获得负面情感的大好机会。汝可别忘了那件事喔。」</p><p>「那当然。好，接下来才是重头戏。」</p><p>「什么不幸啊，笑死人了。居然会跑出这种货色，是不是我行事太招摇了？差不多该离开这座城市回家去了吧。」</p><p>我跟在那个女人后头，但她毫无反省之意，还咒骂个不停。</p><p>不过，虽然嘴上抱怨，但她似乎对占卜的内容耿耿于怀。只要稍有声响，她就会慌张地转头察看，还会特别留意脚边和四周的状况。</p><p>「再说，『大地为之撼动』又是什么意思啊？这里又没有火山……咦！」</p><p>这时忽然爆出一阵巨响，地面剧烈摇晃。发生的时间点非常凑巧，仿佛要否定女子的说词一般。</p><p>「怎、怎么回事！是地震吗？」</p><p>女子惊慌失措地跌坐在地，附近的行人却毫不在意地继续走着。</p><p>「咦？不会吧……？为什么大家都这么平静？好像感受不到刚才的摇晃跟声音似的……难道只有我觉得刚刚地面很晃吗？」</p><p>此时，她似乎想起了占卜的内容，脸色顿时变得铁青。</p><p>她一脸恐惧，拼命地张望着四周。</p><p>这时，我轻轻举起手，大量的液体便从女子头上倾泻而下，将她淋成落汤鸡。</p><p>「好、好冰……这是什么！怎么黏煳煳的！跑进衣服里面了！好恶心！还、还流进奇怪的地方了！」</p><p>倒在她身上的，是之前悠悠从阿克西斯教徒那里拿了一大堆结果无处可用，就硬塞给我的琼脂史莱姆……感觉有点猥亵。</p><p>女子慌张地抬起头，却看见万里无云的晴朗蓝天。</p><p>连风雨欲来的感觉都没有……对此感到惧怕的她，紧紧抱着湿濡的身子颤抖起来。</p><p>「怎、怎么回事……难道那个占卜所言不假？」</p><p>她面色铁青，恐惧至极，接着立刻冲了出去。</p><p>情况非常顺利。</p><p>「成功了吗？」</p><p>奇斯从附近的建筑屋顶探出头来。</p><p>手上还拿着刚刚装了琼脂史莱姆的水桶。</p><p>「嗯，时间抓得刚刚好。」</p><p>「用特产的爆裂魔法当作暗号，所以很好懂。」</p><p>方才的巨响和震动，就是脑袋有问题的爆裂女孩每天都会施放的那个魔法。</p><p>阿克塞尔的居民都司空见惯了，事到如今谁也不会被吓到。不过和真一行人到昨天为止都不知道跑去哪里了，所以最近挺安静的。</p><p>那个女人才来这里没几天，自然不知道这个阿克塞尔的经典场面。这样一切就能照我的剧本走了……但还是小心为妙。</p><p>我盯着女人离去的方向，同时追了上去。</p><p>在大街上发现她的背影后，我缩短了彼此的距离，但她没发现我跟在后头。</p><p>她看似一脸泰然地走在街上，脑袋却忙碌地转个不停，仿佛对周遭十分警戒。</p><p>「好，接下来的布局点是……」</p><p>我事前调查过那名女子会出入的各个场所，并暗中采取了措施。</p><p>她走进常去的高级餐厅了。很好，正如我所料。</p><p>我从后门潜入店内，并对在厨房忙碌的厨师和店员使了个眼色。</p><p>他们随即勾起了不怀好意的扭曲笑容。打扮成厨师和店员的人，其实都是被那名女子诈财的冒险者。</p><p>这里的店长以前也是冒险者。我送他一张梦魔店的全年半价通行券后，他就爽快地把整间店借给我使用。</p><p>「兄弟们，复仇的机会来了。都准备好了吧！」</p><p>「包在我身上。我会让她尽情享用男人的手作料理。」</p><p>假扮成厨师的冒险者自信满满地说着，并将盛盘的餐点端给乔装成服务生的奇斯。</p><p>奇斯表示，这次的整人计划他会全程协助到底。虽然理由是「为了泰勒不惜两肋插刀」，其实只是闲得没事做吧。</p><p>我也很好奇情况会如何发展，便从厨房偷偷窥视着店内。</p><p>「让您久等了。为您送上主厨的创意料理。」</p><p>「呵呵，今天会吃到什么样的料理呢……这啥啊？」</p><p>女子愁眉苦脸地指着那盘餐点。那是淋上半透明液体的干煎肉排。</p><p>「是的。上头淋的是『主厨发挥创意乱搞的酱汁』。」</p><p>「咦？是这种『创意』吗？呃，这酱汁是用什么做的？」</p><p>「这个嘛……因为是随便乱做的，我对其中的食材也一无所知。应该不会有问题吧。」</p><p>「居然说『应该』……算、算了。主厨手艺一流，虽然卖相不佳，但说不定很美味。」</p><p>勉强说服自己后，她便请服务生离开。</p><p>奇斯向她鞠躬致意，接着将同样的餐点端给别桌的客人。</p><p>确认别桌客人也吃下那盘诡异料理后，她松了一口气，并将餐点送入口中。</p><p>「嗯咕！吃起来怎么像坨黏煳煳的液体！肉也煎过头了，不仅硬梆梆的，还散发出可怕的苦臭味！服务生——」</p><p>她把手上的叉子摔在桌上，准备站起身的同时，有个洪亮的嗓音响彻了店内。</p><p>「唔～～～～！这道新推出的餐点真是太棒了。虽然残留一丝焦苦味，但这创新的酱汁将其全数包覆，成功达到了中和的效果，应该说是融为一体了！……呜噁！」</p><p>「若非挑剔的美食老饕，哪能尝出这般纤细的风味呢？如果有人开口抱怨，就表示他的味蕾不够高贵，是个味觉白痴！……呜噗！」</p><p>听到其他客人赞不绝口，站起身的女子又默默地坐了下来。</p><p>虽然赞美后又捂起嘴的动作有些可疑，但演技不算太差。</p><p>女子一边观察吃得津津有味的其他客人，同时耐着性子将食物送进嘴里。每吃一口，眉间的皱纹就凿得更深。</p><p>「对了，那道料理是怎么做的？」</p><p>我向扮演厨师的冒险者这么问，结果他环起双臂，自豪地笑了起来。</p><p>「我把没有经过放血处理的怪物肉排随便烤了一下，再把你之前拿给我的琼脂史莱姆拌入砂糖，淋了一堆上去。就这样。」</p><p>简而言之，就是在又硬又臭的肉排淋上一坨甜到爆的液体啊。难怪她会露出那种表情。</p><p>但或许是自尊心使然，女子勉强将餐点吃完后，面色铁青地丢下一句「谢、谢谢招待……」就离开餐厅了。</p><p>她前脚一踏出去，那几个假扮顾客的冒险者便同时起身，连忙往厕所冲去。</p><p>「呜呕呕呕呕呕呕呕呕！难吃也该有个限度吧，你想杀了我吗！」</p><p>「干嘛让我们吃一样的东西啊！改变一下调味不行吗！你也给我吃一口看看！」</p><p>「谁要吃那种难吃到爆的东西啊！」</p><p>「开什么玩笑，王八蛋！」</p><p>扮演顾客跟厨师的冒险者开始互殴。我跟奇斯无视他们，走出餐厅。</p><p>随后我们又继续整她。把商品价钱哄抬到平常的好几倍，或是把调味料的内容物掉包等等。最后她疲惫不堪地回到了高级饭店。</p><p>「跟我偶尔会住的旅店真是天壤之别。居然拿骗来的钱过这种奢华的生活。」</p><p>「你有时候还会住在马厩，或是喝得烂醉睡在路边呢。」</p><p>在我身旁一起抬头看着饭店的人不是奇斯，而是萝莉梦魔。</p><p>因为接下来就轮到她大显身手了。</p><p>「这次是特别帮你喔。我是听说能为巴尼尔大人贡献一己之力，才会帮你这个忙。不要会错意了。」</p><p>「好，我知道了。进展得顺利的话，老大也会很开心，搞不好会给你摸摸头喔。」</p><p>「真的吗！唔嘿嘿嘿。他会狂摸我的头吗？」</p><p>她的脸都笑歪了。</p><p>「呐，你之前还说『以为女生喜欢被摸头只是处男的幻想』，但这反应也太矛盾了吧？」</p><p>「这很正常呀。如果被喜欢的人摸摸头，当然会很开心嘛。要是被达斯特先生摸头，我会告你性骚扰，但巴尼尔大人就另当别论了。应该说，我还希望他尽情抚摸重要的部位！」</p><p>「这、这家伙……」</p><p>「啊，我想到一个好主意！」</p><p>她拍了一下掌心，不停点头，不知道脑海中闪过什么点子。</p><p>「虽然很想抱怨差别待遇太过明显，但你今天帮我有恩，我就忍一时海阔天空吧。准备好了吧？」</p><p>「交给我吧。梦境内容也万无一失！」</p><p>为了让那个女人作恶梦，我才会请这家伙来帮忙。</p><p>毕竟她今天诸事不顺，应该会早早就寝。我就送她一个无比美妙的恶梦吧。</p><h3 id="_7" tabindex="-1"><a class="header-anchor" href="#_7"><span>7</span></a></h3><p>翌日。</p><p>我再次乔装成占卜师，坐在之前那个位置时，眼前有道黑影笼罩而下。似乎有人坐在我的面前。</p><p>我扬起视线，看到一脸憔悴的新人女冒险者坐在那里。</p><p>「哎呀，小姐看起来很疲惫啊。是不是昨天玩得太开心了？」</p><p>「哈，简直糟透了。不仅被黏煳煳的东西从头淋得满身都是，买东西还被店家敲竹杠，早早入睡却作了可怕的恶梦。我梦到自己被一群黯淡金发的变态男子追着跑……现在回想起来，我还会浑身发冷。」</p><p>「那可真惨呀……」</p><p>恶梦的效果出奇地好。</p><p>不过……梦境内容让我有点在意，待会儿再问问萝莉梦魔吧。</p><p>新手冒险者用手抚额，重重地叹了一口气。仔细一看，她的眼下出现了黑眼圈。</p><p>「对了，小姐。今天怎么会找上老夫呢？」</p><p>「虽然很不爽，但我想相信你的占卜了。我觉得先前的种种遭遇就像被恶整一样。」</p><p>很好，上钩了。情势发展完全如我所料，我几乎要笑出来了。</p><p>接下来才是关键。</p><p>「这样啊。你希望老夫占卜什么呢？今天的内衣是什么颜色吗？老夫特别开放胸部占卜，要不要试试看？」</p><p>「你的手势跟眼神都很可疑，我就心领了。可以用一般的方式帮我占卜吗？我想知道能变幸运的方法。」</p><p>「哼嗯，幸运是吧？呼～～哈～～哟咿呀～～！」</p><p>我用手覆盖水晶球，做出怪异的举止，还发出奇怪的叫声。</p><p>那个新人吓得浑身一震，眼神却无比真挚，跟昨天大不相同。</p><p>「哦～～出现了。前面那间魔道具店贩售的推荐商品，就是你的幸运小物。」</p><p>「魔道具店？」</p><p>「唔嗯。那里有个没什么福分的漂亮老板，以及戴着面具的店员。面具店员推荐的商品，就是掌握幸福的关键！」</p><p>「戴、戴面具的店员？感觉好可疑，但还是值得一试。谢谢，这是占卜费。」</p><p>她支付的金额比想像中还要多，但我还是默默收下。</p><p>占卜师是不是比冒险者还有赚头啊？</p><p>「诱导成功了。」</p><p>巴尼尔老大跟昨天一样，从桌子底下现身。</p><p>请老大帮我占卜的条件，就是要把店里的商品强行推销给那个女人。</p><p>「这样就可以清掉老大店里的库存了。那个女人好像超级有钱，就狠狠赚她一笔吧。」</p><p>「是啊。再这样下去，这个月一定会因为无能老板陷入财政赤字，那可不行。吾还是赶紧回去吧。感谢汝出手相助。」</p><p>「我跟老大是挚友嘛。我随时都能帮忙喔。」</p><p>老大从桌底下飞奔而出，转眼间就变得像米粒一样小。我朝他的背影用力地挥挥手。</p><p>这样就对老大献完殷勤了，来瞧瞧那个女人会有什么下场吧。</p><p>我把占卜用的小道具全数收进袋子，并带在身上跟在老大后头。</p><p>老大跑得很快，我当然追不上他。当我抵达魔道具店时，老大已经穿上围裙在接待她了。</p><p>「以人类基准来说算是国色天香的这位小姐，欢迎光临！」</p><p>「啊，呃，我被称赞了吗？」</p><p>我从窗户偷偷往内看，却没看见老板维兹的身影。</p><p>她也没有像平常一样倒在地板上，可能是出门了吧。</p><p>我这么心想，空气中却飘来一股微微的香气。</p><p>「是在庭院那里吗？」</p><p>因为有些在意，我便循着气味的源头，沿着墙壁移动。结果看到烧成焦黑的维兹被丢在店铺旁边。</p><p>啊，因为碍手碍脚的，所以被丢出来了吗？我看她八成又乱买东西，被老大惩罚了吧。</p><p>虽然是自作自受，但我还是轻轻将双手合十为她祈祷。</p><p>「这、这就是你推荐的商品吗？」</p><p>因为店里传来女子困惑的嗓音，我急忙回到窗边继续窥视。</p><p>老大抓紧机会，强迫推销那些卖不完的商品。</p><p>他手上拿着一具脸蛋莫名逼真的娃娃。那个娃娃身穿贵族风的洋装，像个小孩子。</p><p>「这可是传说中的娃娃，附近的太太们都口耳相传，说是能提升运气呢。娃娃的头发有自动生长的机制，因此能随心所欲地为它变换发型。虽然它偶尔会擅自离开原本放置的场所，但这点小事无须在意。」</p><p>「我很在意啊！这不就是诅咒人偶吗……」</p><p>「这是什么话呀，不要故意找碴好吗？这娃娃还附带了其他优秀的机能。举例来说，只要告诉娃娃汝想要几点起床，它就会在汝期望的时间点将汝唤醒。要不要试试看？」</p><p>老大在那个娃娃耳边低喃了几句。</p><p>接着便把娃娃放在桌上，并环起双臂。</p><p>女子跟我都好奇地凝视着那个娃娃，只见原本低着头的娃娃忽然抬起头，紧闭的小嘴勐然大张。</p><p>「呜嘿嘿嘿嘿嘿嘿嘿嘿嘿嘿！」</p><p>娃娃口中爆出了超级洪亮的鬼祟笑声。</p><p>「好恐怖！这是怎样！」</p><p>「呼哈哈哈哈哈哈哈！有这个闹钟机能，再会赖床的瞌睡虫也能马上起床。怎么样，是不是很棒啊？对了，它还具备了淘气小妖怪的机能喔！如果置之不理，娃娃就会拔出藏在怀里的短剑杀过来！」</p><p>「这样在醒来之前就会陷入永眠了吧！我不想听这些说明，要怎样才能让它停下来！」</p><p>女子指着现在还咯咯发笑的娃娃，用跟笑声不相上下的大嗓门破口大骂。</p><p>光是在外面听就觉得快要疯掉了，里面的人应该觉得无比煎熬吧。</p><p>……老大似乎毫不在意就是。</p><p>「唔嗯，停止的方法啊。要用尽全力堵住娃娃的嘴，才会停下来。」</p><p>「早说嘛……喂，这个娃娃在拼命挣扎耶！等一下，这个画面是不是有点危险！」</p><p>女子压制着拼命挣扎的娃娃。远看就像要诱拐幼童的罪犯似的。</p><p>「起床后做点适度的运动，也会觉得神清气爽吧？」</p><p>「啊，嗯，随便啦……还有其他推荐商品吗？」</p><p>「不满意啊？要不要参考这个超级热卖，会在深夜尖笑的巴尼尔娃娃？另外也有附带驱怪效果的宝石项链啦。」</p><p>老大从后面的货架中，拿出一条款式满不错的项链。</p><p>「刚才那个就免了，怎么会推荐那种会笑的娃娃啊？还有项链啊，我就买这个吧，设计也满好看的。所谓的驱怪效果是到什么程度？」</p><p>「哥布林那种等级的怪物没办法靠近。」</p><p>「哎呀，不错嘛。」</p><p>单纯只是如此的话，这条项链确实不差，应该还会在商人或共乘马车的车夫之间掀起热卖风潮吧。但这间魔道具店的商品可没这么简单。</p><p>「缺点是宝石会散发出甜美的香气，但只会引来一些怪物而已，这一点也无须在意。」</p><p>「喂，这样不就抵销掉驱怪的效果了吗？还真是致命的缺陷……」</p><p>女子虽然不太想买帐，但因为店里没有任何正常的商品，她就买了刚刚那条项链，还买了另外几样商品。</p><p>「唉，钱都花光了。这个城市也没得捞了吧，还是回去埃尔罗得好了。」</p><p>因为大部分都是高额商品，这阵子出手阔绰的女子，似乎也耗尽了所有财产。</p><p>女子走出魔道具店后，仰望着天空如此埋怨道。</p><p>「埃尔罗得不是赌博王国吗？这女人还没学乖啊。」</p><p>既然她要离开这里，那就没什么事了。但为了以防万一，我还是趁夜摸进她的房里，在她枕边放上那个闹钟娃娃吧。</p><h3 id="_8" tabindex="-1"><a class="header-anchor" href="#_8"><span>8</span></a></h3><p>三天后，我把那个女人给的占卜费全花光了，于是到公会走了一遭。只见琳恩、奇斯，还有……泰勒也坐在位子上。</p><p>看来是解脱了吧。虽然不知道是怎么道别的，但还是调侃他几句吧。</p><p>「嗨～～哦，泰勒师父，好久不见。」</p><p>「别叫得这么恶心。」</p><p>「你最近好像在跟女孩子谈情说爱嘛。带来介绍一下啊。」</p><p>我语带轻佻地说完，琳恩和奇斯便用手指抵着嘴发出「嘘！」的一声，叫我闭上嘴巴。</p><p>他们是怎样？这个反应……哎，看来是被女方甩掉啊。</p><p>「哦，怎么？你被狠狠甩掉了吗？」</p><p>「我们本来就没有在交往。只是指导她一些冒险者的心得而已。」</p><p>「那真是辛苦你了。那个女人现在在干嘛？」</p><p>「回故乡去了。好像是母亲忽然生了重病，她才放弃冒险者的工作，回去照顾母亲。」</p><p>编了这种理由啊。真了不起，竟然能将纯真女冒险者的假象贯彻到底。毕竟只要受骗的人没发现，就会变成单纯的美好回忆。</p><p>既然她已经离开阿克塞尔，剩下的就无所谓了。</p><p>隔天我去确认情况时，发现她被恶梦和闹钟娃娃害得连两天睡眠不足，还露出一副累到心死的表情。她应该对这个城市充满厌恶了吧。</p><p>「毕竟事出突然，维修冒险者装备又让她花光了积蓄，治疗费用也是笔不小的数目，所以我二话不说就把身上现有的钱全部给她了。但愿能帮上一点小忙。」</p><p>「…………」</p><p>那个臭婆娘！最后的最后还是被她摆了一道……泰勒也完全上当了。</p><p>「事情就是这样。抱歉，我已经没钱了。等等我想接点委托，你们能跟我一起去吗？」</p><p>「反正我一天到晚都没钱，没差啦。」</p><p>说完，奇斯和琳恩也点点头。</p><p>这些混帐，我没钱的时候就对我不理不睬，泰勒没钱就愿意挺身而出喔。</p><p>……虽然很想开口抱怨，但今天就对这位好好先生队长温柔一点吧。</p><h2 id="第二章-跟踪那群闹哄哄的家伙" tabindex="-1"><a class="header-anchor" href="#第二章-跟踪那群闹哄哄的家伙"><span>第二章 跟踪那群闹哄哄的家伙</span></a></h2><h3 id="_1-1" tabindex="-1"><a class="header-anchor" href="#_1-1"><span>1</span></a></h3><p>「我不会把可爱的妹妹交到来路不明的男人手上！要用惠惠的爆裂魔法炸飞整座城吗？不，等一下。也可以骗骗阿库娅，让她教唆阿克西斯教徒啊。不论要用什么手段，我一定要阻止……」</p><p>和真一个人在酒吧里喝得烂醉，还说着这种唯恐天下不乱的事情。</p><p>我也醉得一塌煳涂，有一半以上的内容都没听清楚，但知道他现在火冒三丈。</p><p>「嗨～～和真，一个人喝酒很寂寞吧。好吧，我是你的麻吉，就陪你一块儿喝！别跟我客气！把酒全都拿过来！今天就特别让我的好兄弟买单吧！」</p><p>「每次都我买单吧！醉汉达斯特不要缠着我啦！我现在没时间跟你胡闹。你自己付酒钱，我才不要请你。」</p><p>「干嘛这么小气～～我跟你是挚友吧。」</p><p>「什么挚友，我们只是互相认识而已吧？」</p><p>「喂喂，别害羞嘛～～你这个小坏蛋～～」</p><p>和真嚷嚷着这番无心之言，而我用手指勐戳他的脸颊。</p><p>「住手啦，我现在很认真在烦恼耶。可爱的妹妹正在哀求哥哥出手救援，现在肯定都泪洒枕头了！」</p><p>和真冷冷地看着我，还把我的手挥开。看样子现在不适合调侃他。</p><p>不过，和真有妹妹吗？啊，我知道了。好像有某位公主殿下把和真当成哥哥仰慕呢。</p><p>……是指爱丽丝吗？</p><p>嗯～～难道是攸关国家的大事件？</p><p>「抱歉啦。你在烦什么？我一定会帮到底，有任何烦恼，就跟达斯特大爷诉苦吧。可以免费跟你洽谈喔！」</p><p>「找达斯特商量，不如找阿库娅那些人……但惠惠感觉会嫉妒。虽然达克妮丝是那副德性，好歹也是个贵族。至于阿库娅还是免谈吧。达斯特喔，要跟达斯特商量啊～～我身边就没一个正常人吗？唉～～反正我非得开口，否则你不会放过我吧？」</p><p>和真大大地叹了口气，摇头晃脑地说。</p><p>他很了解我嘛。</p><p>「唉……如果妹妹……非常重要的人跟别人订下婚约，自己却毫不知情，达斯特，你会怎么做？」</p><p>「……唔。」</p><p>和真这句话，让我顿时酒意全消。</p><p>重要的人另有婚约……而且那位妹妹还是公主殿下。这么说来，爱丽丝之前也抱怨过自己有未婚夫这件事。</p><p>「喂喂，怎样啦？难得看你一脸严肃。」</p><p>「嗯、嗯？忽然听你说这种意想不到的事，我吓了一跳啦。你说的是爆裂女孩吗？达克妮丝？还是宴会祭司……不可能吧。」</p><p>「才不是。就算那些家伙有未婚夫，我也不用管啊。对方一定会受不了她们啦。」</p><p>「说得也是。」</p><p>每天都要击发一次爆裂魔法的红魔族。</p><p>本性超级变态的贵族。</p><p>沉迷于美酒和宴会才艺，完全不在意会给人添麻烦的阿克西斯教祭司。</p><p>「我倒想鼓励那些人，能跟她们交往的话就试试看啊。我反而很想见识一下呢。」</p><p>「是不是？而且那些家伙哪会这么……别管她们了。达斯特，如果是你会怎么做？之前琳恩那件事，你因为误会闹得天翻地覆吧？」</p><p>「别提了……我实在不愿回想起那件事。」</p><p>和真说的是前阵子发生的事。当时听说有个好像是贵族的男人想追琳恩，我接获情报之后，就请和真帮忙，一起去恶整那家伙。</p><p>结果却是个天大的误会。那家伙看上的不是琳恩，而是我……</p><p>光是回想起来，我就浑身颤抖。</p><p>「呐，结果你……后来被硬上了吗？」</p><p>「才没有！我的屁屁保住了贞操！真、真的啦！不要用看着可悲之人的眼神看我！」</p><p>和真将手放上我的肩，点点头，仿佛在说「无须多言，我懂」。</p><p>……他一定误会了。</p><p>「回归正题吧。如果那个重要的人是遥不可及的大人物，还是退一步祝对方幸福……比较好吧。」</p><p>我抚上佩在腰间的长剑，给出这种跟我本性不合的回答。</p><p>「真不像达斯特会说的答案耶。我以为你至少会说『那就打爆对方抢过来啊！』。不过，要是那个对象很讨人厌，你会怎么做？」</p><p>「那就打爆那家伙抢过来啊。之后再把他整得惨兮兮。」</p><p>至少要让重要的人得到幸福吧。</p><p>既然知道她会陷入不幸，当然可以动用强硬手段。</p><p>「对吧！达斯特果然懂我。好，这摊算我的，尽量喝吧！不过你要帮我出主意喔。你很会耍小手段吧？」</p><p>「哦！真的可以吗？好啊，包在我身上！我就教你几招游走在法律边缘，但不会被警方逮捕的诈欺和闹事手法吧！」</p><p>我一杯接一杯喝个不停，跟和真瞎闹了一整晚。</p><h3 id="_2-1" tabindex="-1"><a class="header-anchor" href="#_2-1"><span>2</span></a></h3><p>「头好痛……」</p><p>得意忘形喝太多了。宿醉的感觉有够差。</p><p>我睁开眼，发现太阳高挂在正上方。</p><p>「没有屋顶啊。这是哪里？」</p><p>虽然地面又硬又冷，有些不太对劲，但我应该是喝得烂醉，直接睡倒在路边了吧。</p><p>「我好像跟和真讲了一些事情，但内容是什么啊……」</p><p>只记得跟女人有关，却连一丁点细节都想不起来。</p><p>「算了，应该不重要。找伙伴们请我喝一杯起床后的美酒吧。」</p><p>伸伸懒腰，舒缓紧绷的关节后，我立刻前往冒险者公会。</p><p>我走进公会大门并往内看去，发现琳恩他们坐在老位子上……这就算了，有个人却坐在他们对面。</p><p>是接了什么委托，正在跟委托人直接洽谈吗？</p><p>虽然只看了背影，但那人一身魔法师的装扮。</p><p>「啊，达斯特。过来这边。」</p><p>由于琳恩要我过去，我便坐在她身旁，正面看向委托人。</p><p>原来是有过一面之缘的贵族千金——蕾茵。</p><p>这家伙怎么会出现在冒险者公会？难道又是跟爱丽丝有关的麻烦事吗？</p><p>她是本国公主爱丽丝的护卫兼教育专员，之前跟我和琳恩一起冒险过。</p><p>「哦，这不是贫穷又没存在感的贵族吗？我最近开始做一笔好赚的生意，要不要算你一份？」</p><p>「之前碰面的时候，我虽然说过可以别太拘谨地和我相处，但我好歹也是一名贵族，请你留意一下用字遣词吧……待会儿再跟你请教那个好赚的生意。」</p><p>蕾茵脸颊抽搐地露出干笑，不知是对「贫穷」、「没存在感」，还是两种形容都不满意。</p><p>「现在是什么情况？要借钱的话，我会拒绝喔。」</p><p>「对一名贵族来说，跟你这种家伙要钱，还不如干脆去死。蕾茵小姐不是要借钱，是想直接指名我们帮忙喔。而且给出的委托金额还挺高的。」</p><p>「达斯特先生、琳恩小姐，前阵子受两位关照了。」</p><p>蕾茵语气恭敬地低下头说道。</p><p>蕾茵对平民没有偏见，跟我熟知的贵族大不相同。爱丽丝身边还有另一个教育专员，那家伙的思维就非常贵族，我实在拿她没辙。</p><p>「达斯特、琳恩，你们什么时候跟贵族认识啦？难不成有扯上不法情事？」</p><p>「喂，她还挺漂亮的嘛。不过该怎么说呢，总觉得好没存在感，一点也不亮眼。无论如何，美女就是美女。待会儿给我好好解释一下。」</p><p>泰勒和奇斯也都掩不住好奇心，不停质问我。</p><p>我轻轻挥挥手，丢出一句「等等再说」。</p><p>蕾茵已经先报上贵族的名号了？</p><p>「委托啊。也罢，有钱就好办事。委托的内容是什么？」</p><p>「是的。其实不能将详情告诉你们，但我希望各位能帮忙警戒依丽丝大人的护卫们。」</p><p>「警戒护卫？是指警备跟护卫吗？」</p><p>泰勒觉得她应该只是单纯口误，便有些在意地加以确认。</p><p>原以为可以随便听听就好，不过……</p><p>「不，你没听错。我希望你们能帮忙警戒那些护卫，别让他们惹出无谓的麻烦。」</p><p>「……难道是护卫中潜藏了叛徒这种可怕的事情？」</p><p>既然不是口误，就只能这样解读了。</p><p>跟爱丽丝扯上关系的话，就算发生权位斗争或有魔族手下潜入等情事都不足为奇。话虽如此，我们只是一介冒险者，她怎么会把攸关国家的大事交付给我们呢？</p><p>这么做应该事出有因。要是有个万一，她就会封住我们的口风。既然是贵族，而且还跟王族息息相关，就很有可能做出这种事。</p><p>「啊，不，没这回事。应该说，希望你们能监督依丽丝大人和那些护卫不要做出什么愚……惊人……呃，不要做出什么奇怪的事。」</p><p>她刚刚差点对臣子和王女用上「愚蠢」二字吧？虽然她连忙更改说词，但我可是听得一清二楚。顺带一提，「依丽丝」就是爱丽丝的假名。</p><p>「嗯～～还是摸不着头绪耶。虽然知道依丽丝是地位崇高的贵族千金，但既然有护卫随行，代表她要前往某个地方吧？」</p><p>「这个嘛。依丽丝大人有个未婚夫，所以她准备前往埃尔罗得，和那位大人见面。」</p><p>未婚夫。奇怪？最近好像听过类似的话题？</p><p>是和真在喝酒的时候说的吧。我记得是最近的事情……以后还是不要喝到会失忆的程度好了。</p>`,289),e(f,{src:`/images/E4/13.avif`,alt:`插图`,width:`850`,height:`1257`}),s[9]||=a(`<p>「她才几岁而已，没必要担心自己嫁不出去吧。反正对方应该也是多金的贵族大少爷。真想说给柜台小姐露娜听听啊。她应该会泪眼汪汪地深感羡慕吧？」</p><p>「达斯特，快住口！要是被露娜小姐听见，她就会把一些天杀的委托硬塞给我们耶！在露娜小姐面前，不能提这种婚嫁的话题！」</p><p>公会柜台小姐露娜虽然人气超旺，胸部也很大，但她已经过了适婚年龄，最近好像想婚想疯了。如果用这件事调侃她，她就会笑咪咪地把超困难的委托硬塞过来，得小心点才行。</p><p>「她还这么年轻，就有未婚夫了啊。我还以为贵族都过着悠哉的生活，没想到也挺辛苦的。不过，既然已经有对象，就不用担心嫁不出去了。这一点让我有点羡慕。」</p><p>「你还不到急着想婚的年纪吧？而且琳恩根本不需要担心结婚的问题，因为这里就有个超级完美的对象嘛！」</p><p>我竖起大拇指指向自己，并咧嘴一笑。</p><p>「哈！对你来说，这玩笑还算有趣。」琳恩看了我一眼后，立刻变得面无表情，失笑了一声。</p><p>「爱……依丽丝大人很了不起。不仅思想贤明，也充分理解自己的角色定位……过去的她确实如此，最近却深受某个人荼毒，有时会做出太过调皮的举动。她每天都会从城……从家里逃出去一次。」</p><p>「某个人」指的就是和真吧。</p><p>这么说来，克莱儿之前也抱怨过很多次。爱丽丝学会耍小聪明，逃家的技术还变得日益精妙。</p><p>「那些护卫，难不成……是和真小队吗？」</p><p>我向蕾茵这么提问，而伙伴们同时看向了我。</p><p>他们不知道事情经过，才不明白我为何会在此时提到和真小队吧。</p><p>「答对了。依丽丝大人将和真先生当作兄长大人那般仰慕亲近，所以情况变得很棘手。我姑且有和达斯堤尼斯大人谈过这件事，希望他们能拒绝护卫的委托，但不知道那个人会不会先下手为强……」</p><p>看来和真才是蕾茵烦恼的根源。</p><p>「而且克莱儿小姐也反对依丽丝大人这门婚事，还想动歪脑筋加以破坏。由于两人利害关系一致，她就跟和真先生结盟了……若不想办法制止，后果可能不堪设想……」</p><p>咦？下属可以破坏王女的婚事吗？</p><p>克莱儿就是和蕾茵一同担任爱丽丝的护卫兼教育专员的另一名贵族。</p><p>先前碰到她的时候，她都紧紧跟在爱丽丝身边。当时我就觉得她很不妙了，没想到比起国家安危，她宁愿选择公主啊。</p><p>至于未婚夫所在的埃尔罗得，就是为贝尔泽格王国提供巨额金援的国家。</p><p>我想起来了。前阵子因为巴尼尔老大的面具，我和爱丽丝的精神状态曾经合为一体。当时她为了要提升金援额度这一点忧烦不已。</p><p>扯上公主的婚事啊……事态一定会变得麻烦透顶，我实在不太想蹚这滩浑水。但想起那一晚的事情，我又无法置身事外。</p><p>「虽然觉得问题不大，但就怕依丽丝大人有个万一。如果各位能帮忙逼退和真先生他们无法顾及的威胁，就帮了我一个大忙。我希望能小心再小心。」</p><p>公主前往他国，自然需要护卫随行。慎重行事也是刚好而已。</p><p>更何况护卫还是和真那群人。即使他们各个都是卓越超凡的人才，却毫无安定性可言。</p><p>如果有人问我「他们适不适合担任护卫」……虽然我是和真的麻吉，还是无法给出肯定的答案。</p><p>「那个，虽然很感谢你找我们帮忙，但你不该雇用冒险者，而是正规的护卫吧？」</p><p>「我也跟琳恩持相同意见。既然要确保生命安全，还是找护卫比较妥当。」</p><p>「你又不像万年穷鬼达斯特，不会对金钱斤斤计较吧？」</p><p>我也同意伙伴们所说的话，却无法插嘴。</p><p>应该有无论如何都需要我们帮忙的理由。</p><p>「话是没错，但因为这次是隐密行事，无法带上一大票随扈。人数必须尽可能减少，不能太过显眼才行。为了不让敌方靠近，也会使用特殊的龙车。再说，依丽丝大人本身的实力就很坚强了。」</p><p>「那孩子外表这么可爱，实力却很高强啊。不过能坐龙车也不错。负责拉车的不是马，而是奔跑蜥蜴，行驶速度可是马车无法比拟的呢。」</p><p>琳恩见过爱丽丝，因此不敢相信她拥有高强的实力。</p><p>爱丽丝之所以会那么强，应该是因为常吃高价的怪物肉来提升等级吧。贵族常用这种方式升级。</p><p>既然她是王族，饮食方面一定比贵族更加奢华。</p><p>而且听说贝尔泽格王国的王族还流着勇者的血脉，富有与生俱来的才能。不过，毕竟蕾茵是她的下属，说词可能有些偏颇。</p><p>「也就是说，我们要监视和真他们会不会带坏依丽丝，顺便保护她的安全。还要戒备和真他们会不会对未婚夫做出多余的事。没错吧？」</p><p>「没错，正是如此。不过，抵达埃尔罗得后，你们只需留意和真先生一行人的动向即可。如果他们闯了祸，请你们详实地记录下来。毕竟也有可能产生损害赔偿。另外，呃，由于依丽丝大人的父亲在该国也是『有名望的』贵族，因此也会造访王城一趟，届时就请各位留在城门外静候！」</p><p>蕾茵说得飞快，还特地强调「有名望的贵族」一事。</p><p>因为不能暴露爱丽丝的王女身分嘛。</p><p>委托费高得吓人，住宿费也由对方买单，甚至还准备了龙车给我们搭乘。这份委托还真是无微不至。</p><p>这种求之不得的好事，哪有拒绝的道理呢？因此我们爽快地接下了委托。</p><p>其实我很不想跟王族扯上关系，但这次的目的地是以赌场闻名的埃尔罗得，那就另当别论了。</p><p>订金也拿了不少，可以赌个痛快。</p><p>蕾茵离开公会后，奇斯跟泰勒便上前逼问我跟她是什么关系。</p><p>当我说出先前和琳恩、悠悠以及那两人一起去冒险的事，奇斯果然百般羡慕地死缠着我不放，我就用酒把他灌得烂醉。</p><p>「为什么……只有达斯特这么有女人缘啊！」</p><p>奇斯趴在桌上说梦话。就先别理他了。</p><p>「依丽丝就是那两位所侍奉的贵族千金，她跟和真感情不错，才会请他们当护卫吧。」</p><p>「和真小队虽然实力超群，但专精的项目太过单一，所以不适合担任护卫嘛。」</p><p>「毕竟爆裂女孩击发一次魔法就没戏唱了。达克妮丝还会丢下护卫对象不管，自己冲进敌人的怀抱。蕾茵就是担心这一点，才会请我们偷偷戒备吧？我们只要提供援助就好，感觉是满轻松的差事。」</p><p>「是啊。虽然不能掉以轻心，却是一份不错的工作。我去采购旅行所需的道具，大家先好好休息吧。」</p><p>旅行的准备交给泰勒就没问题了吧。</p><p>琳恩似乎想继续留在这里发呆，于是我独自离开了公会。</p><p>「我也没事可做，去巴尼尔老大店里玩玩吧。」</p><p>最近我常去老大的魔道具店打发时间……正确来说，应该是穷鬼美女老板维兹的店面，但负责实际营运的应该是老大才对。</p><p>「老大，我过来玩了～～」</p><p>我打开门扔出这句话后，正在扫地的老大便歪了歪嘴角。</p><p>「汝怎么又来了。吾跟小混混不一样，忙得不可开交。没事的话就快走吧。」</p><p>「就是说嘛。不要来干扰巴尼尔大人。」</p><p>「吾刚刚也跟汝这淫魔说过同样的话。」</p><p>贴近在老大身边的人正是萝莉梦魔。</p><p>这家伙是不是比我还要常来啊？</p><p>「喂，萝莉梦魔。你怎么大白天就游手好闲啊，工作呢？」</p><p>「我的工作时间是从晚上开始。达斯特先生……你还真好意思质疑其他人的工作啊。我把镜子拿过来给你照照吧？」</p><p>「明天开始我就有长期的工作了。」</p><p>「此话似乎不假啊。吾就用特别优惠价，替汝占卜未来吧。」</p><p>老大似乎是能洞悉未来的恶魔，可以十足精准地预测未来。</p><p>先前惩治那个坏女人时也借用了这个能力，所以我明白实力有多厉害。</p><p>「谢谢你的好意，但还是算了吧。老大说的并不是占卜，根本就是预言。而且之前都没什么好下场。」</p><p>温泉旅行时，老大的预言确实成真了，他却故意含煳带过最关键的部分，以我的苦痛为乐。</p><p>毕竟老大的粮食就是人类的负面情感。若完全信任他的预言，后果通常是不堪设想。</p><p>「那不是吾的错，是汝平时素行不良所致吧。」</p><p>「就是说啊，巴尼尔大人没有错！请你重新审视自己吧！」</p><p>这、这家伙……只要牵扯到巴尼尔老大，她就变得超级啰嗦。</p><p>干嘛比当事人还要生气啊？</p><p>「吵死了。你是我妈喔。」</p><p>「我一点都不想生出达斯特先生这种小孩。」</p><p>「小时候的我说不定很可爱啊！」</p><p>「小时了了，长大也是变成这副德性。」</p><p>萝莉梦魔一脸嫌弃地看着我。</p><p>「不准说『这副德性』！不要用手指着我！」</p><p>「烦死了！要讲相声就到外面去讲。搞不好还能招揽几个客人。」</p><p>「跟她讲相声很无聊耶。就算在吐槽时不着痕迹地偷摸她的胸部也是乏善可陈，一点意思也没有。」</p><p>我看着萝莉梦魔的胸部，耸耸肩说道。她也半眯着眼瞪了过来。</p><p>「居然如此嘲弄女性的胸部，达斯特先生真的很失礼。你的小弟弟也是乏善可陈啊。」</p><p>她瞄了我的下腹部一眼，并勾起意味深长的笑容。</p><p>「喂喂喂，你又没看过我的巨剑，还敢胡说八道。」</p><p>「泡温泉的时候有看过啊。印象中只是一把短剑吧。啊，我记错了，应该是小刀才对。噗！」</p><p>「好啊，都说到这份上了，我现在就让你重新确认一次！给我睁大眼睛看好……痛！」</p><p>我刚握住皮带，后脑勺就被人重重一击。</p><p>我回过头去，发现是老大挥出了制裁的铁拳。</p><p>「不想被吾提告妨碍营业，就立刻住手！胸部跟下半身都小得可怜的家伙！」</p><p>「我、我还在发育中！应该用美乳来称呼才对！请您用眼睛和手掌确认看看！」</p><p>「要是我发威起来，可不只这样而已！」</p><p>为了提出证明，萝莉梦魔准备褪下上衣，我也正想拉下裤子。结果又被老大揍了一顿。</p><p>「不要在店里露出奇怪的东西！客人就已经够少了，还要让他们更不敢靠近吗？真没办法，吾会免费替汝占卜，算完就快点磙蛋。」</p><p>「呃，占卜就免了……」</p><p>老大丝毫不顾我的意见，直盯着我看。</p><p>「哦哦哦哦，天啊天啊。不正经的蠢蛋啊。吾看见汝在奢华的赌场中孤注一掷的身影了！哼哼，汝似乎注定会在关键胜负中抽到最弱的手牌！呼哈哈哈哈哈哈哈哈！」</p><p>「真的假的，早知道就不要听了。能不能替我占卜一下，让我有办法在赌场取胜？」</p><p>「再来就要收钱了。想知道后续结果就拿钱过来。听那个小鬼说，这种方法似乎叫作『课金制度』。」</p><p>「真是卑鄙……我现在没钱，只能放弃了。」</p><p>我真的很想知道详情，但巧妇难为无米之炊。</p><p>前往埃尔罗得之前，居然得知了这种额外的情报。不过，老大的占卜偶尔也会失准吧。</p><p>「请问一下，阿克塞尔有正规赌场吗？」</p><p>「这个城镇没有那种大规模的设施。之后我们要去以赌场闻名的埃尔罗得。应该是指我会在那里大赢一场吧。」</p><p>「你要去埃尔罗得吗！」</p><p>「喔，对啊，是这样没错。」</p><p>萝莉梦魔睁大双眼盯着我瞧。</p><p>有必要这么惊讶吗？</p><p>「请带我一起去！」</p><p>「你对赌场有兴趣啊？好，那我今天就带你去附近的赌场晃晃。只要无限提供经费给我，我就会帮你翻倍赚回来。」</p><p>我还以为她只对春梦跟巴尼尔老大有兴趣，没想到对赌博也很好奇啊。我就以前辈的身分，好好对她灌输博弈的乐趣吧。</p><p>「我才不在乎赌博。」</p><p>她居然一口回绝了。</p><p>「那你为什么想跟过来……啊，原来如此。不好意思，没察觉到你的心意。但是很抱歉，小屁孩不在我的狩猎范围内。」</p><p>「不仅擅自会错意，还把我给甩了，真令人火大。我不是小屁孩好吗！别看我这样，我的年纪比你还大！」</p><p>「好啦好啦，你好棒棒喔～～等胸部变大之后再来说吧～～」</p><p>我无视萝莉梦魔的蠢话，并摸摸她的头，结果她气得不停跺脚。</p><p>「气死我了！巴尼尔大人！达斯特先生真是让我打从心底感到火大！」</p><p>「那个小混混只有惹怒他人的技术可谓天下一绝，别跟他一般见识。对了，说说汝想去埃尔罗得的真正原因吧。」</p><p>「这个嘛，我们计划要在埃尔罗得设立梦魔店分店，目前在讨论是否要就近去场勘一番。所以我才想顺水推舟。」</p><p>原来如此。应该说，埃尔罗得没有梦魔店这件事更让我意外。可恶，这样就少了一个乐趣。</p><p>「在赌博王国开设梦魔店啊，这主意不错。钱包被填满后，就会想填满其他的欲望。人类的情欲真是无穷无尽啊。」</p><p>「听到恣情纵欲的汝这么说，真是莫名有说服力。」</p><p>「对啊。」</p><p>两人同时点点头说道，但我装作没听见。</p><p>萝莉梦魔啊……只是带她过去的话，应该不会有问题。</p><p>我们小队里只有琳恩一个女生。虽然她什么也没说，但一个女孩子跟一群男人出远门，可能也会有些不安。</p><p>「没差，你就一起来吧。是你的话，其他人应该不会有意见。」</p><p>「非常感谢你！我会送你店里的折价券当作谢礼，要分给大家用喔。」</p><p>「好啊。不好意思耶，还让你这么费心。」</p><p>哦，有十张啊。我会妥善运用所有折价券的。</p><p>再说，要不是我出面，就不会有这种好康啦！</p><p>正当我打开魔道具店的大门，准备离开之际——</p><p>「过来。吾给汝一道建言吧。」</p><p>「什、什么？难道是爱的告白……」</p><p>我听见巴尼尔老大将萝莉梦魔叫到身边。转头一看，发现老大正在她耳边细语。但从那家伙一脸嫌弃的表情来看，应该不是爱的告白。</p><h3 id="_3-1" tabindex="-1"><a class="header-anchor" href="#_3-1"><span>3</span></a></h3><p>我们配合和真小队出发的日程，来到了贝尔泽格王国首都。</p><p>成员有我、泰勒、奇斯和琳恩，再加上萝莉梦魔随行。</p><p>「这次又要麻烦各位了。这是一点小心意，请慢用。」</p><p>「欢迎你，请多多指教。不用这么多礼啦。」</p><p>萝莉梦魔不停地低头鞠躬，并送上伴手礼，琳恩他们也笑容满面地接待她。</p><p>过去跟她一起行动好几次，大家已经习惯了吧。</p><p>为了确保旅途中的安危，我本来也想找悠悠一起来。但她发挥边缘人的能力，让我找不到人，所以就没管她了。</p><p>「这就是龙车啊。真的是奔跑蜥蜴在拉车耶，比我想像中还要朴素。」</p><p>「因为是贵族大人的交通工具，我还期待会更豪华呢。还是我们干脆把车子装饰得华丽一点好了？」</p><p>「奇斯，别说这种失礼的话。我们的工作是要在不被对方察觉的情况下进行护卫。引人注目也毫无意义，才会进行伪装，不是吗？」</p><p>奇斯明显表现出遗憾的模样，结果被泰勒训了一顿。</p><p>「是的。无论如何都希望各位能隐密行事，所以才准备了一般样式的外装。但车体内部不受影响，坐起来十分舒适。虽然没有车轮，但只要……」</p><p>蕾茵独自前来将龙车交付给我们。她将手放在车上，口中呢喃几句后，车体便悬浮于半空中。</p><p>这是借由减轻重量，提升行驶速度的构造吧。</p><p>「哦哦，从地面上飘起来了！这是什么构造啊？」</p><p>「我第一次见到这种款式呢。」</p><p>「真不愧是贵族大人。」</p><p>我看着伙伴们深感钦佩的模样。这时，萝莉梦魔从旁拉了拉我的衣袖。</p><p>「达斯特先生没什么反应呢。不觉得很稀奇吗？」</p><p>「哦。我之前有看过啊。」</p><p>贵族持有龙车是很稀奇没错，但王族就不需要大惊小怪了。</p><p>没存在感又爱操心的蕾茵正在跟伙伴们说明各种注意事项。这种事只要交给泰勒就好。</p><p>所有事项似乎已经说明完毕，蕾茵说了声「之后就麻烦各位了」，便往和真一行人的方向走去。</p><p>在这个距离之下，和真等人的身影看起来只有黑点般大小，但我们早有对策。</p><p>「奇斯，看得到另一头的状况吗？」</p><p>「可以，非常清楚。因为我有『千里眼』技能嘛。」</p><p>奇斯是弓手，所以具备「千里眼」。只要有这个技能，就能清楚看见远处的动静，因此能在远距离外进行护卫。</p><p>「但和真不是也有『千里眼』技能吗？」</p><p>「「「啊。」」」</p><p>琳恩的疑问被我们的声音盖了过去。</p><p>这么说来，他之前好像有说过……</p><p>「可、可是，既然拿到地图，也知道对方的动线，或许就……不会有问题？」</p><p>「距离这么远，一定没问题吧。」</p><p>「我的『千里眼』比较优秀，只要维持在勉强看得见的距离，应该行得通吧？」</p><p>所有人都语带含煳地提出质疑，让人有些不安，但船到桥头自然直。大概啦。</p><p>「在这里干着急也没用。他们也差不多要出发喽。好，我们也启程吧。我来驾车。」</p><p>「这样啊，麻烦了。不知为何，奔跑蜥蜴也跟达斯特很亲呢。那就拜托你了。」</p><p>「明明被人类女孩子当成垃圾，却深受动物和魔物喜爱。」</p><p>「可能是身上会分泌出特殊成分吧。」</p><p>「你们这些家伙……不要废话了，快点上车！」</p><p>催促大放厥词的伙伴们上车后，我将手抚上奔跑蜥蜴的背嵴。</p><p>「万事拜托了。」</p><p>我摸了摸奔跑蜥蜴蹭上来的脸颊，然后坐上驾驶座。</p><p>「达、达斯特！这个速度太奇怪了吧！」</p><p>「好快、好恐怖、好快啊啊啊啊！」</p><p>「不、不能减速一下吗！这样很危险吧！」</p><p>身后传来伙伴们的惨叫声，真是吵死了。</p><p>他们好像被出乎意料的速度吓了一跳。</p><p>「别担心，相信我的技术吧。」</p><p>「「「办不到！」」」</p><p>居然在这种时候才异口同声。这点程度的车速只是小意思吧。骑乘在龙背上翱翔时可没这么慢。</p><p>我发现只有萝莉梦魔没吭声，于是转头一看。只见她身子朝外，兴致勃勃地眺望着车窗外。</p><p>「比自己飞轻松多了～～」</p><p>她可以靠自己的力量飞在空中，所以比起那些伙伴，对于速度的恐惧感没这么深。</p><p>「蕾茵不是说这辆龙车附有强力的结界，就算遭逢事故也安全无虞吗？而且一旦减速，就会追丢和真他们喔。因为他们前进的速度快得离谱。」</p><p>和真一行人所搭乘的龙车远远跑在前方，我好不容易才追上。只要稍稍减速，距离就会一口气被拉开。</p><p>不过那边是谁在驾驶啊？即使是资深老司机，也要具备相当的勇气才能开这么快。</p><p>「喂，奇斯。你知道那边的驾驶是谁吗？帮我看一下。」</p><p>我抓着心惊胆战的奇斯的脖子，把他拉到驾驶座。</p><p>「风、风压都打在脸上了！你、你这家伙！现在速度这么快，不要回头啦！看前面！」</p><p>「就说没关系了。那边是谁在驾驭龙车？」</p><p>奇斯胆怯地探出脸来，眯起双眼瞪向前方。</p><p>他似乎看见了难以置信的光景，勐然瞪大双眼，接着一脸愕然地张大嘴巴。</p><p>「先不管在驾驶座上哭哭啼啼的蓝发女孩……唔、喂，我看到达克妮丝在驾驶座上笑得合不拢嘴耶。那家伙是不是脑子烧坏啦！」</p><p>「你现在才发现啊……难怪他们会以这么快的速度暴冲！」</p><p>只能祈祷不要出事了。虽然达克妮丝比较喜欢强力的碰撞就是。</p><p>总之我双手合十，为和真一行人祈求平安。</p><p>「达斯特————！不要闭上眼！不要放掉缰绳啊！」</p><p>「少啰嗦。就说这种龙车我闭着眼也能开。你看，你看你看～～」</p><p>看到我故意摆动双手嘲弄，奇斯的脸上顿时血色尽失。</p><p>他可能浑身无力了，便一头栽回龙车里。</p><p>「呐！奇斯倒过来了耶，发生什么事了！」</p><p>「喂，奇斯失去意识了！」</p><p>身后传来琳恩和泰勒的惊叫，但我挥挥手，丢下一句「死不了人啦」。</p><p>没想到这家伙的胆子这么小。</p><p>那两人可能无法接受我的回答，便从驾驶座后方探出头来，张开嘴准备念我几句。但或许是被飞逝而过的景色吓到，又默默地钻回龙车里。</p><p>因为骚动逐渐平息，于是我边哼歌边驾车。这时，在前方賓士的龙车减速停了下来。</p><p>行踪应该没有曝光，所以我在隔了一段距离的街道旁停车。</p><p>「是不是发生什么事了？奇斯，别瘫在那里，帮我看看那边的状况。」</p><p>我抓着奇斯的衣领强迫他站起身，并将他的脸转向前方。</p><p>「终、终于停下来了。不会晃动的地面真棒，我已经可以跟地面谈恋爱了……前面怎么了？啊～～哦哦！有一大群怪物！和真他们下了车……被保护的大小姐怎么冲出去了？」</p><p>听了奇斯的解说，我顿时涌起兴趣。但不管我再怎么仔细凝视，还是看不出和真他们在做什么。</p><p>我也好想要「千里眼」喔。只要学会这个技能，就可以从远远的地方尽情偷窥了……</p><p>「啊？喂喂，挺身护卫的大小姐举起了剑耶——」</p><p>这个瞬间，和真一行人所在之处传来了光芒。</p><p>我完全不知道发生了什么事，但奇斯却在一旁张大了嘴。这反应让我有些在意。</p><p>「喂喂，怎么了？别愣着一张脸，快告诉我。」</p><p>「我、我也不太清楚。那个大小姐挥剑之后，就飞出一道强光，把牛型怪物一分为二……这样根本不需要护卫吧。」</p><p>我还以为爱丽丝很强这件事是蕾茵吹捧过头了，没想到是真的。可见勇者的血脉不是浪得虚名。</p><p>「这样也不错啊。不必担心她会被怪物袭击，应该能乐得轻松。」</p><p>接下来，我的发言便化为现实。每当有怪物出现，爱丽丝就会迅速击退，不停重复着这样的流程。</p><p>……这位公主也太招摇了。要骗人也该有个限度嘛。</p><p>我们毫发无伤地顺利前进，一回神才发现周遭已经暗下来了。</p><p>和真他们停下龙车，开始进行扎营的准备，于是我们也走下龙车。今天的跟踪行动便画下句点。</p><p>「再来只要从远处保护他们就行了吧。依丽丝应该不能熬夜，那接下来就该轮到我们上场了。」</p><p>我重振松懈的心情，装模作样地这么说完，背后就发出了剧烈的光芒。</p><p>我急忙转过头察看，发现和真等人的所在位置……筑起了一栋略小的宅邸。</p><p>「那里原本没有房子吧？」</p><p>「对、对啊。我才想说怎么发光了，结果忽然就蹦出一栋宅邸！」</p><p>「这、这是什么原理啊？」</p><p>琳恩他们也一脸困惑，不知道发生了什么事。</p><p>萝莉梦魔虽然也吓了一跳，但跟其他三人相比，感觉相对冷静。</p><p>「那是一种最高级的魔道具吧。我记得是附带驱怪结界的可携式宅邸。」</p><p>「啊～～是巴尼尔大人很想陈列上架的魔道具之一呢。我就觉得好像在哪里见过！达斯特先生也听巴尼尔大人说过吧？」</p><p>「哦，对啊，有听说过。」</p><p>其实我有亲眼见识过，但没必要说出口。</p><p>「呐，有那种魔道具的话，就不需要我们了吧？真的有必要护卫吗……」</p><p>「我也这么认为，但可以轻松不少，所以就不必抱怨了。爽爽出游，还能拿到一大笔钱，这样还有怨言的话，会遭天谴喔。」</p><p>这样晚上也不用把风了。任务似乎变得比想像中还要简单许多。</p><p>因为无须担心爱丽丝的安危，我们也开始准备扎营。</p><p>「和真他们在温暖的大宅中安全地吃晚餐，我们却在野外围着营火吃晚餐……」</p><p>「达斯特，别碎念了，这很稀松平常吧。」</p><p>「大家一起在外面吃饭也很有趣啊。」</p><p>琳恩跟萝莉梦魔都很乐观。</p><p>泰勒不发一语地默默烤着肉。奇斯应该跟我一样心怀不满，此刻他却表现得异常安静。</p><p>他只是一直死盯着宅邸的方向看。</p><p>「怎么回事，你居然这么安分？」</p><p>「太没道理了……」</p><p>他口中似乎念念有词，但我没听清楚。</p><p>一靠近奇斯，我就闻到一股酒臭味。这家伙竟然拿着酒瓶擅自开喝了。仔细一看，他整张脸也涨得通红。</p><p>奇斯一直在低声咕哝，于是我凑近他的脸，想听听他到底在说什么。</p><p>「可恶啊啊啊啊啊啊！太奇怪了吧啊啊啊啊啊！」</p><p>「唔喔喔喔喔！耳朵好痛！不要突然大吼啦！」</p><p>「奇斯，你怎么了！」</p><p>「是不是在晚餐前偷吃了什么怪东西？这样很没家教喔。」</p><p>「怎么了吗？请你先冷静下来。」</p><p>奇斯忽然莫名其妙地起身大吼，让众人吓了一跳。但要是让他继续乱叫，搞不好会被和真发现，还会引来怪物袭击。</p><p>我们连忙压制，奇斯却依旧闹个没完。</p><p>「冷静点，你怎么了！」</p><p>「太没道理了吧！和真在宅邸中被女人簇拥，我却在屋外饥寒交迫地扎营！」</p><p>看样子，深埋在奇斯心中的怨怼爆发而出了。</p><p>「这里也有女人啊！」</p><p>「哈！她们都是达斯特的陪睡女仆吧！」</p><p>这家伙居然说出这么可怕的话。</p><p>「不要危言耸听，我才不会让他对我出手！」</p><p>「就是说啊。虽然受过达斯特先生帮忙，但我们从头到尾都只是生意上的伙伴而已！只是事务上的关系！我只对巴尼尔大人有兴趣！」</p><p>我们确实不是那种关系，但被她们全力否认，还是有点火大。</p><p>「泰勒最近也有处得不错的女人吧！就我身边没有对象！为什么啊，混帐王八——！」</p><p>愤恨不满地大吼一声后，或许是因此满足了，奇斯就这么往后方一倒……睡着了。</p><p>单纯只是在发酒疯而已。虽然可以放着不管，但感觉有点可悲。</p><p>琳恩和泰勒合力将醉倒的奇斯扶起，把他带回帐篷之中。</p><p>我向萝莉梦魔招招手，在她耳边低语：</p><p>「不好意思，待会儿可以让那家伙作个好梦吗？费用我来出，拜托你了。」</p><p>「他已经醉到不省人事了，不确定有没有办法作梦，但我会试试看……原来你也有温柔的一面啊。」</p><p>「至少让他在梦里得到一点安慰吧……」</p><p>这不是温柔，而是怜悯。而且继续放着奇斯不管，一直惹他生气，跟踪任务也会受到影响。毕竟我们必须仰赖他的「千里眼」技能。</p><p>「既然奇斯倒下去了，就先由我和泰勒负责把风，你们去龙车里睡一觉吧。如果寂寞难耐，我也可以陪你们睡觉，一起做深夜的上下运动喔？」</p><p>「免了。」</p><p>「如果你不想看到明天的太阳，我是无所谓。」</p><p>她们用冷漠的眼神狠狠拒绝了我。琳恩，不要故意亮出匕首好吗？我的胯下都吓得发抖了。我身边怎么尽是这种女人啊？</p><p>奇斯是不是疯了，居然会羡慕我的处境。</p><p>「哼，这群孤苦寂寞的女人，真是不懂男人的体贴。」</p><p>「你哪里体贴了……」</p><p>「「「是下流才对。」」」</p><p>「不要异口同声！快点睡觉，半夜再起来换班！」</p><p>琳恩和萝莉梦魔对我吐舌后，便走进龙车之中。</p><p>只剩我跟泰勒围在营火边。</p><p>「怎么剩两个臭男人啊。」</p><p>「那是我要说的吧。不过，你不觉得这次的委托有点怪吗？无论是这辆龙车，还是那个魔道具，都不是一般贵族能持有的物品。她真的只是普通的贵族吗？」</p><p>他果然察觉到了。</p><p>泰勒常常代表我们听取委托的说明，因此比小队里的任何一个人都来得慎重又严谨，当然会起疑心。</p><p>「都说是『有名望的贵族』嘛。我猜她的地位应该很崇高吧，所以才要隐密行事。」</p><p>「也是……既然如此，为了自身安全，还是不要继续深究吧。被贵族盯上也很麻烦。」</p><p>「俗话也说多一事不如少什么的。我们只要暗中保护他们，拿钱了事就行。别说这些了。泰勒，你跟那个女人真的没什么吗？别一个人独享喔。你、你该不会已经背叛我们，越过那道防线了吧？呐，你说话啊？」</p><p>泰勒不会说谎，只要看他的反应就能立刻明白。</p><p>他愁眉苦脸地摆出环起双臂深思的动作，随即大大地叹了口气。</p><p>「我不知道你在妄想什么，但我之前就说过了吧。单纯只是传授她一些冒险者的心得而已。虽然进展很顺利，但既然母亲生病也无可奈何。如果能和她平安再相逢就好了。」</p><p>「……这样啊。」</p><p>她是个坏女人，你只是上当受骗了——说出这种话虽然会轻松许多，但我做不出这么卑鄙的事。</p><p>虽然觉得稍稍透露事实会很有趣，但我还是作罢了。</p><p>既然他们完全没做过色色的事，那就不要打破砂锅问到底了。</p><p>「别说我了，你呢？虽然跟琳恩没什么进展，但你和那个名叫萝莉莎的少女还有悠悠感情很好嘛。」</p><p>「哈！琳恩就算了，另外两个还是小鬼头耶。我又不是萝莉控，对她们一点兴趣也没有。如果有露娜那种发育良好的大胸部，我应该会乐于出手就是。」</p><p>「那是永远无法实现的美梦……哎呀，说熘嘴了。这是我们之间的秘密，绝对不能跟琳恩她们说喔。咳咳。无论如何也该适可而止。」</p><p>泰勒似乎对自己多嘴的举动深感反省，只见他别开视线，用木棒搅了搅营火。</p><p>我很少跟泰勒聊这种事。可见那个女人让他开窍了吧。</p><p>能和美艳的大姊姊共度一夜当然再好不过，但今天就用男人之间的蠢话来妥协吧。</p><h3 id="_4-1" tabindex="-1"><a class="header-anchor" href="#_4-1"><span>4</span></a></h3><p>隔天。</p><p>我们继续跟踪和真一行人。</p><p>虽然碰到敌人很多次，但爱丽丝似乎都直接秒杀了。</p><p>只有奇斯看得到那些人的状况，所以我们只能远远地眯起双眼观看。刚看见有道闪光，战斗就结束了。</p><p>虽然有点怀疑是不是真的发生过战斗，但途经爱丽丝战斗过的地方，就会看见无数被一分为二的怪物尸横遍野。所以奇斯似乎不是在瞎扯。</p><p>随着龙车晃了好几天，旅途都很顺遂，到现在都没有陷入危机。</p><p>中途爆裂女孩引领众人在河里抓螯虾时，我跟伙伴们实在搞不懂那有什么意义，还为此烦恼了一番。但也只有这点小问题而已。</p><p>唯一让我耿耿于怀的……就是一直消沉地碎念，提不起劲的奇斯所散发出的郁闷气息。</p><p>一直远远地看着被女人簇拥的和真，似乎让他对于自己毫无异性缘这件事无比绝望。我能理解他的心情啦。</p><p>「啊，看得到埃尔罗得了。」</p><p>「哇～～比贝尔泽格王国首都还要壮观呢。」</p><p>琳恩和萝莉梦魔已经习惯龙车的速度了，两人将身体探出驾驶座，指着前方这么说道。</p>`,331),e(f,{src:`/images/E4/09.avif`,alt:`插图`,width:`850`,height:`1257`}),s[10]||=a(`<p>我被两人包夹，她们的胸部也碰到我身上——</p><p>「如果可以再大一点，我会很高兴的……」</p><p>「你说啥？」</p><p>「你刚刚说了什么？」</p><p>「我什么也没说。」</p><p>我被她们用冰冷的视线夹击。</p><p>居然道出心声了，得小心点才行。</p><p>我佯装无事地看向前方，便看见比阿克塞尔更加壮观的外墙和城门。</p><p>追在和真一行人后头，穿过城门后，热闹的街景便窜入我的眼中。</p><p>「哦～～密密麻麻都是人耶！而且有好多精心打扮的人，跟阿克塞尔大不相同。既然有这么多人，搭讪应该也会成功吧？对不对，奇斯？」</p><p>「……没错！既然身边没女人，那在这里找一个就行啦！埃尔罗得有很多好女人吧！」</p><p>我抓着奇斯的肩膀，故意兴致高昂地这么说，他也跟着嗨了起来。</p><p>我偷偷看向伙伴们，用唇语示意「你们也给我嗨一点啊」。</p><p>「就、就是说啊。至少会有一个喜欢奇斯的怪胎吧！」</p><p>「嗯嗯，只要不开口说话就好了。为了不曝露出本性，就一直用笔谈来对话吧，这样或许会搭讪成功喔！」</p><p>「是啊。只要别浑身散发出处男的气息，就万无一失了！」</p><p>「…………反正我就是这样啦。」</p><p>听完伙伴们的发言后，奇斯在龙车的角落缩成一团，还用手指在地板上转圈圈。</p><p>他们本来想尽其所能地称赞奇斯，但刚刚那样只是在酸他吧。</p><p>「怎么让他更消沉了啊！」</p><p>「我原本是想鼓励他啊。」</p><p>「因为他跟达斯特一样没什么优点，我才找不到其他说法嘛。」</p><p>「虽然可能性近乎于零，万一他搭讪成功，我们店里的营业额会下降耶。」</p><p>啊，奇斯抱着膝盖直接倒在一旁了。最近他陷入消沉的时候常常这样。虽然睁着眼，瞳孔却黯然无光。</p><p>「你们的用词要再温柔一点！一直强调他很废，当然会伤害他啊！奇斯的确是个无药可救的人渣，但他也是个努力不懈的男人。为了随时迎接被女孩子倒追的机会，他每天早上都会在镜子前面花费大把时间整理头发，不断练习帅气的台词！不仅如此，为了在搭讪成功后能马上磙床单，他还会浪费时间，勤劳地更换内裤呢。你们知不知道啊！」</p><p>听到我为奇斯辩护的这番话，琳恩和萝莉梦魔都吓得退避三舍。泰勒则用温暖的眼神盯着奇斯，并将手轻放在他的肩膀上。</p><p>「泰勒，不要这么体贴！达斯特，你不要一直乱讲话！可恶，等着瞧吧。我一定会在这个城市找到女朋友，过得比你们还要幸福！」</p><p>哦，他上钩啦。稍微打起精神了吧。</p><p>旅途期间，他始终沮丧地认为只有自己没有女朋友，让人很难接近，这样总算正常一点了。</p><p>重振雄风的奇斯监视着和真一行人，发现他们走进一间光看就很高级的旅店里，于是我们也住进隔了一段距离的旅店。</p><p>「似乎可以寄放龙车和奔跑蜥蜴。那我们继续执行任务吧。」</p><p>跟旅店店员交涉完毕后，泰勒回到房里。</p><p>男女分别住进不同的房间，而我们现在聚集在男生房间里。</p><p>「可是，那个叫依丽丝的大小姐是什么来头啊？我从来没看过这么强的人。实在不需要我们，也不需要和真他们护卫吧。」</p><p>「是谁都不重要吧。好了，去看看他们的状况吧。」</p><p>奇斯似乎也觉得事有蹊跷，但继续深究只会变得更麻烦，所以我硬是打断了这个话题。</p><p>我们从看得见旅店的小巷子监视旅店入口时，和真他们就走了出来。</p><p>「他们好像要去什么地方，但依丽丝不在呢。呃，他们是护卫吧，可以丢着她不管吗？难道这些家伙想摸鱼，跑去赌场玩吗！」</p><p>「他们又不像你。我猜是那孩子有所顾虑，才要他们出门观光吧。」</p><p>「大小姐还在窗边跟他们挥手，看来应该不是他们吵着要出门。或许真的就像琳恩所说的吧。」</p><p>奇斯将手放在额头上，窥视着旅店。</p><p>「千里眼」真的很方便耶。就算我再怎么努力细看，也只能勉强看到窗户上隐约有个人影。如果有这个技能，不用离这么远也能看得一清二楚……</p><p>「喂，奇斯，教我『千里眼』。」</p><p>「战士学不来吧。像和真那种最弱职业的冒险者还学得来。」</p><p>该死！如果学会「千里眼」，就能尽情偷窥了。难道和真跟奇斯都密藏了绝佳的偷窥景点，每天晚上都偷偷地暗爽，却只有我被蒙在鼓里吗！</p><p>「你这叛徒！」</p><p>「干嘛突然揍我啊！」</p><p>「你们两个，现在是打闹的时候吗？真没想到他们会丢着护卫对象不管，各自分头行动。两边的行踪都不能忽视啊。」</p><p>「嗯～～该怎么办呢？总不能所有人都跟在和真他们后头吧。得留一个人保护依丽丝才行。」</p><p>「那我留下来好了。我的身型太过壮硕，不适合跟踪。」</p><p>因为泰勒毛遂自荐，我就把照顾爱丽丝的差事交给他了。</p><p>来到大街上的和真等人，深感惊奇地张望着四周。</p><p>如果只是单纯观光完就结束了，跟踪在后的我们也能乐得轻松。</p><p>「也是。哎呀，好像有人靠近他们了。是三个男人。」</p><p>听到奇斯警戒的嗓音，我们的表情都为之紧绷。</p><p>为了随时应对突发状况，我们始终保持着不会被和真等人察觉的距离。</p><p>他们的注意力似乎都在那三个男人身上。即使我们跟得这么紧，也完全没人发现。</p><p>「看起来像是一群轻浮男。是有钱的小少爷吗？」</p><p>「应该吧。哦，安静点。在这里应该竖起耳朵就能听见他们的声音。」</p><p>所有人将手放在耳边，窃听和真一行人的对话。</p><p>「哦？几位冒险者还真是漂亮呢。呐，前面那位金发美女的大姊姊，别管那种不起眼的男人了，要不要和我们一起在这个城镇逛逛啊？」</p><p>听到轻浮男的发言，我们面面相觑。</p><p>每个人都皱起眉头，流露出纳闷的神情，我也不例外。大家似乎都无法理解那个男人在说什么。</p><p>「那个轻浮男，该不会……是在搭讪那三个人吧？」</p><p>「喂喂，奇斯，这笑话很难笑喔。怎么会有这么不知死活的人啊？」</p><p>「在阿克塞尔，谁也不会做这种事。」</p><p>我正想将奇斯这般鬼扯的预想一笑带过，刚刚一个人默不作声的萝莉梦魔却插嘴道：</p><p>「等一下。那些人跟阿克塞尔居民不同，应该不知道那三位是什么样的人。所以光凭外表评断的话，她们都是大美女啊。」</p><p>听了萝莉梦魔的见解，我才恍然大悟。</p><p>「原来如此。因为我们知道那群人的本性，所以绝对不可能鲁莽地上前搭讪，但那些男人一无所知。只要没发现她们的本性，看起来就只是三个美女……」</p><p>我们虽然也很惊讶，但当事人似乎也没能掌握目前的情况。只见她们三人慌忙地张望着四周。</p><p>谁也不知道自己是被搭讪了……在阿克塞尔被众人避之唯恐不及，从来没被称赞过美貌，所以还搞不清楚眼前的状况啊。</p><p>「总觉得，她们这样有点可怜耶……」</p><p>「达斯特也这么认为吗？既然外貌这么出众，当然会被人搭讪啊……」</p><p>「我也要留意自己平时的所作所为了，嗯……」</p><p>「我也有同感……」</p><p>看到三人被搭讪的场景，在场的所有人都深感同情。平日的言行举止非常重要呢。</p><p>只要不开口说话，她们的确都美得不可方物，但在阿克塞尔所做的种种怪行为，让一切都化为泡影。</p><p>这时，三人终于发现自己被搭讪了，便急急忙忙地打理仪容。看到这个画面，我们偷偷地擦了擦眼角。</p><p>起初她们有些手足无措，但宴会祭司得意忘形地说了几句，那三个男人明显稍稍提高了警戒。</p><p>爆裂女孩不顾开始起疑的轻浮男子，往前踏出了一步。</p><p>「也就是说，为了和我这个超级美少女以及这两位美女约会，你们三个已经有不惜散尽钱财，付出性命的觉悟。所以希望我们能和你们约会。你们是想这么说吧？」</p><p>「「「我们可没说到那个份上。」」」</p><p>三名男子立刻回答了爆裂女孩的问题。</p><p>哎呀，轻浮男也察觉到那三人的危险性了。只见他们转过身，聚在一起低声地谈论。</p><p>「这么快就露出马脚啦。搭讪失败了。」</p><p>「再说，和真应该不会让那种事发生吧。看到伙伴被搭讪，他不可能默不吭声。」</p><p>话是没错啦。即使和真老是被她们捅娄子，有点像是监护人的立场，但这种时候他应该会一口回绝吧。</p><p>「请便请便。」</p><p>「「「「咦！」」」」</p><p>听到和真这句意想不到的回答，我们和她们都不约而同地惊呼出声。</p><p>「不会吧？啊，和真用尽全力冲出去了！」</p><p>「他抛弃伙伴了耶！」</p><p>「咦？喂，怎么办？再这样下去会跟丢和真的行踪……没办法，我去追我的好麻吉吧！你们帮忙监视那群家伙！」</p><p>「喂，等一下，达斯特！不要把烫手山芋硬塞给我们！」</p><p>奇斯开口挽留，但我装作没听见，从全力奔逃的和真身后追了上去。</p><p>和真的行为固然令人惊讶，但只要冷静思考就能理解。带着那三个拖油瓶，根本无法在埃尔罗得尽情放纵。</p><p>都来到这里了，他也不想继续当保母吧。那三个女生肯定会闯出大祸。</p><p>我趁乱追在和真后头，就能借此摆脱负责监视那些麻烦家伙的义务。等等就随便盯一下和真的行踪，顺便观光就行了。</p><p>就让我好好享受埃尔罗得吧。</p><h3 id="_5-1" tabindex="-1"><a class="header-anchor" href="#_5-1"><span>5</span></a></h3><p>「「「「「「「「喔喔喔喔喔喔喔喔喔喔喔！」」」」」」」」</p><p>会场充斥着惊叹声。</p><p>和真似乎想到了什么，临时跑去参加卡牌游戏大赛，展开了势如破竹的进击。</p><p>我没有在阿克塞尔看过这种卡牌游戏，但和真好像知道游戏规则，以惊人的攻势屡战屡胜，赢到对战选手哭着拼命道歉。</p><p>……和真的事先摆在一边吧。我现在没那个闲工夫。</p><p>「喂，我怎么会输啊！这次你暂停一回合，让我攻击吧！否则我会让你的手再也拿不住卡牌喔！」</p><p>我弹响手指，向对战选手下马威，结果被店员团团包围。</p><p>「这位客人，这里禁止暴力！客人，不可以！就说不可以了！喂，所有人过来压制这个小混混！」</p><p>「正合我意！我要对你们的脸发动直接攻击！一辈子都轮不到你们的回合！给我堂堂正正，一个一个放马过来！」</p><p>「开什么玩笑！还想耍嘴皮子啊！大家一起上，扁他！」</p><p>我丢出卡牌，朝着惊恐的店员扑了过去，但还是寡不敌众，转眼间就被压制在地，被众人狂踹。</p><p>接着，我直接被擒抱而起，塞进了某个东西里面。</p><p>「唔喔！好臭啊啊啊啊！呸呸！可恶，居然把我塞进垃圾桶。」</p><p>我想尽办法爬出垃圾桶，发现自己来到了会场后方。正打定主意回去念他们几句时，就看见和真走出店外，于是我急忙躲进巷弄之中。</p><p>和真顶着心旷神怡的表情，离开比赛会场往其他地方去了。</p><p>「虽然觉得可以丢着他不管，但又没办法。」</p><p>我隐去声息不让他发现，并追在他后头，结果他没做什么引人注目的事。只是到餐厅吃个饭，在街上逛逛，又走进一间卖首饰的店。</p><p>跟着走进店里应该会暴露行踪，于是我在外面待命。这时我听见一阵熟悉的爆破声响，地面随即剧烈晃动起来。</p><p>「是爆裂女孩放的吧。」</p><p>看吧，还是闯祸了。跟着和真过来果然是正确的选择。</p><p>我对现在应该筋疲力竭的伙伴们敬了个礼。</p><p>和真一路愉快地观光到傍晚时分，我跟在他后头，回到早上与伙伴们分开的地点时，发现那群轻浮男已经在那里了。不过少了一个人，只剩两个。</p><p>至于和真的伙伴……达克妮丝莫名容光焕发地背着那名爆裂女孩。宴会祭司像在闹脾气似的坐在地上。</p><p>「……她们闯祸了吧。」</p><p>「你想知道吗？」</p><p>「唔喔喔喔，别吓我啦。」</p><p>我躲在建筑物阴影中时，有人从我身后喊了一声。</p><p>将手放在我肩上，叹了口大气的人正是奇斯。神情疲惫的琳恩和萝莉梦魔站在他身后。</p><p>「呐，你真的想知道吗？呐、呐、呐？」</p><p>很可怕耶，干嘛用死气沉沉的眼睛逼问我啊。</p><p>「呃，不，其实也还好。我大概猜得到啦。」</p><p>「我想也是。只能说非常惨烈。连我都一反常态，忍不住对轻浮男表示同情了……如今我对负责照顾她们的和真肃然起敬。」</p><p>「嗯。和真每次都要制住那三个人啊。」</p><p>「下次他来店里光顾时，我要好好招待他才行！」</p><p>琳恩他们好像目睹了非常惨烈的画面，每个人都以手扶额，长叹了一口气。</p><p>和真那伙人似乎跟轻浮男子起了争执，却突然间逃了出去。</p><p>「只赔一半也好啊啊啊啊啊啊啊！」</p><p>我把放声尖叫的轻浮男抛在后头，追在和真一行人身后。确认他们冲进旅店之后，我们也回到旅店。</p><p>他们今天应该不会再捣乱了吧。明天一大早又要开始监视，于是我们便早早休息。</p><h3 id="_6-1" tabindex="-1"><a class="header-anchor" href="#_6-1"><span>6</span></a></h3><p>「好，睡得很沉。」</p><p>确认同房的奇斯和泰勒都熟睡后，我偷偷地从床上起身。</p><p>都来到以赌场闻名的埃尔罗得，天一黑就直接上床睡觉实在太浪费了，我才不会做这种事。而且今天还有别的事要办。</p><p>我蹑手蹑脚地离开房间，和几乎同时走出女生房的萝莉梦魔四目相交。</p><p>向彼此点点头后，我们一同离开旅店。</p><p>「好，夜晚才正要开始，我要去赌场大玩——」</p><p>「没这回事。你说好今天要陪我了。」</p><p>她硬是开口盖过了我的声音。</p><p>虽然忘得差不多了，但待会儿我得陪萝莉梦魔去办事才行。</p><p>「要去场勘梦魔分店对吧。可是，既然还没决定候补地点，现在不是应该先去赌场蒐集情报，看看是哪些客人会来消费吗？」</p><p>「话是没错，但今天不能赌博喔。如果你不帮我，我不会给你优惠券。」</p><p>「好好好，交给我吧。我可是一诺千金的男人！」</p><p>我竖起大拇指，眨眨眼，摆出了帅气姿势。</p><p>萝莉梦魔冷冷地看着我。</p><p>「那就快点把赊欠的款项还——」</p><p>「好，要去哪里呢！」</p><p>再让她继续说下去，可就大事不妙，因此我抓住萝莉梦魔的肩膀，奔向夜晚的大街上。</p><p>「你为什么马上就毁约了！脑袋里到底装了什么啊！难道你把脑浆贱价卖给借钱给你的人了吗！」</p><p>「少啰嗦。要先以顾客身分熟悉环境，才能问出情报嘛。」</p><p>一走进附近的赌场，我就把蕾茵给的订金换成筹码坐了下来。</p><p>萝莉梦魔在背后碎念了几句，但认真就输了。</p><p>坐在我对面的人，是个脑满肥肠的老头子。</p><p>脖子、手腕和手指戴满了贵重金属，感觉挺富裕的。完全就是多金纵欲色老头的写照。</p><p>藏在肥滋滋眼皮下的眼眸直盯的目标并不是我，而是在我身后忧心忡忡的萝莉梦魔。</p><p>这家伙也跟最近莫名有缘的萝莉控三人组是同类，喜欢这一味吗？</p><p>「哎呀～～今天真走运。呜呼呼呼呼。小姐，怎么样，别管那个男人了，待会儿跟我去用餐如何？抛下那个一看就很没用的男人吧。」</p><p>「啊，呃，我不要。」</p><p>面对宛如来回舔舐般的执着视线，萝莉梦魔吓得躲在我的身后。</p><p>「你是梦魔，对这种事应该得心应手吧。干嘛吓成这样？直接亮出你的小胸部或内裤，他就会乖乖闭嘴了吧。」</p><p>我对萝莉梦魔低声说道，她就摆出一张苦瓜脸。</p><p>「总有生理上无法接受的人吧。身为一个梦魔，我当然很喜欢色眯眯的人，但被无法接受的人直接投射欲望，那个，该怎么说……我觉得很恶心。呃，举例来说，作者写情色小说取悦读者，跟作者本身变成性幻想对象取悦读者，两者是不一样的吧？就是这种感觉。」</p><p>「啊——好像能理解这种差别。」</p><p>毕竟从头到尾都只是让男人作春梦而已。不用执导，也无须登场演出。在店里穿的衣服明明跟内衣裤没两样，这样不是很矛盾吗？</p><p>「哎呀哎呀，我被拒绝了呢。那就继续赌吧……哦，你已经没有筹码了？」</p><p>「唔！」</p><p>我的手边确实一个筹码也不剩。</p><p>蕾茵给的订金几乎全花光了。但我不会就此结束！</p><p>「我还要追加筹码！」</p><p>「咦？你已经没钱了吧。我也没带钱出来，没办法借你喔？」</p><p>「我已经设想过这种情况，所以中午在冒险者公会先换好钱了。」</p><p>我掏出一大笔钱，跟荷官换了筹码。</p><p>「怎么会有这么多钱？难不成……你在这里也犯罪了吗！」</p><p>「「「在这里『也』？」」」</p><p>听到萝莉梦魔的发言，对战选手和观众们都骚动起来。</p><p>「喂，不要偷偷叫警卫过来！不是啦，我把倒在路上的怪物拿去换钱了。虽然高价的部位已经被连根拔除，却留下很多还能卖钱的部位。」</p><p>「这不就是抢走了和真他们的猎物……」</p><p>「说什么傻话，我只是代为处理他们留下的魔物罢了。他们应该感谢我，没道理责骂我吧！」</p><p>和真他们似乎对打倒的怪物没兴趣，几乎都会碰也不碰地直接扔掉，我只是有效运用而已。</p><p>「既然你还有钱，我就不追究了。好，我们再来玩一场吧。」</p><p>「好啊。要是被我扒了一层皮，可不要哭哭啼啼的喔。」</p><p>「太蠢了吧！喂，你太蠢了吧！」</p><p>萝莉梦魔一直在我耳边大呼小叫。</p><p>在那之后又过了几分钟，我已经只剩一条内裤和一把剑了。</p><p>「可恶，怎么会全盘皆输呢？太奇怪了吧！」</p><p>「我也十分惊讶。你居然一次都没赢……你还是戒赌比较好吧，听我的准没错。」</p><p>我怎么会被对战选手同情和说教啊？</p><p>原本我还怀疑他可能是诈欺师，但从他的反应来看，应该并非如此。</p><p>可是，我真的都没有赢耶。难道我被好运放生了吗？</p><p>运气啊……在冒险者公会制作卡片时，我也曾被自己低得离谱的幸运值吓得不轻。但最近好像有某位祭司的幸运值比我还要低就是了。</p><p>或许是幸运值太低的关系，我确实很少在赌桌上取胜。</p><p>和真似乎跟我相反，幸运值很高。到目前为止，我跟他比了数十次，却从来没赢过。我无论如何都想赢过和真，因此尝试过各种方法，却还是直冲全盘皆输的结局。</p><p>「堂堂男子汉怎么能退缩呢！下次我一定会克服败北的难关，夺下胜利！情况肯定会如此发展！」</p><p>「废人才会有这种想法！你刚刚也说过这句话，但还是输了啊！」</p><p>「你的勇气确实可嘉，但你已经没有筹码了吧。既然已经散尽财产，也无计可施了。」</p><p>老头子说得没错。我的钱包已经空空如也，连能够抵押的物品也没有。</p><p>这么一来，我就只剩下这把剑了。但这可不是能够用来当成赌注的东西。</p><p>「是啊，只能放弃了。」</p><p>「要是你无论如何都想继续赌，就听听我的要求吧。看你想要多少筹码，我会全数提供。」</p><p>这个色老头想把难题硬塞给我啊。看他那个邪笑的表情，我马上就识破他的意图了。</p><p>但他锁定的目标是萝莉梦魔，所以——</p><p>「好，成交！」</p><p>我立刻回答。</p><p>「我、我都还没说明呢，真的可以吗？我会给你筹码，相对地……能不能把你带来的那位可爱女孩借给我一晚？哎呀，我也知道这样是强人所难，所以，要是你赢了下一场赌局，筹码的价钱就一笔勾销，我也会收回刚刚的要求。如何？」</p><p>「好啊。」</p><p>「「咦？」」</p><p>见我立刻允诺，老头子和萝莉梦魔都哑然无语。</p><p>他们没听见我说的话吗？</p><p>「我说无所谓。」</p><p>「等等，给我等一下——！你凭什么擅自决定啊？我绝不同意！」</p><p>萝莉梦魔在后面疯狂摇晃我的身体，但我依旧泰然地紧盯着对手。</p><p>「啊，那个……要不要再稍微考虑一下呢？呃，那孩子似乎很不情愿呢。而且她的外表如此稚嫩，在法律上没问题吗？我只是偶尔想跟年轻女孩小酌一番而已，绝对没有性方面的企图。即使如此，两位可以就这件事好好讨论一番，再下决定也不迟嘛。」</p><p>老头子像机关枪般丢出一堆宛如借口的说词。</p><p>提议的人不要吓成这样啦。</p><p>刚刚那个色老头的嘴脸跑哪去了？难道他只是单纯言行怪异，实际上是个好爷爷吗？</p><p>「也就是说，只要把她借给你一晚，让你有个美梦就行了吧？」</p><p>「是、是啊，正是如此。这说法有点……而且你这样重新强调，让我有些罪恶感……」</p><p>老头子都几岁了，不要忸忸怩怩地玩手指啦，真是恶心。</p><p>「光明正大地面对这种事啊！凡事都这么战战兢兢就输了。你要时常对自己说『这样是正确的』，活得嚣张一点嘛。好了，不要低垂着头，挺起胸膛吧！再跩一点，傲慢一点！」</p><p>「是、是吗？我知道了。唔哈哈哈哈哈哈哈！穷鬼们，想要钱的话，就来对我献殷勤吧！要不要跪下来舔舔我的鞋底啊？啊～～哈哈哈！」</p><p>老头子张大嘴疯狂地笑了笑，接着偷偷瞄了我一眼。</p><p>喂喂，太贪心了吧，还想知道我会打几分吗？</p><p>我举起双手比出一个圈并点点头，老头子才笑逐颜开。</p><p>「你们不要心有灵犀好吗！我的立场呢？呐！」</p><p>「有什么关系。只是喝酒而已，又不会少块肉。那家伙感觉很有钱，如果好好煽动他，说不定他会送你一块分店的土地呢。而且用煽情的打扮博得好感之后，在这里展店时，就能比其他梦魔更早取得优势了，不是吗？」</p><p>「啊，原来如此。说得也是……我会拼命展现自己的魅力，替你加油喔！」</p><p>萝莉梦魔马上把身上的衣服脱下，变成在梦魔店工作时的打扮。</p><p>这家伙非常渴望以梦魔的身分得到认同，所以只要稍加刺激，立刻就会上钩了。</p><p>「「「「唔喔喔喔喔喔喔！」」」」</p><p>其他客人本来都用饱受干扰的眼神看着吵个不停的我们，一看见这身跟内衣裤没两样的打扮，所有人都为之沸腾。</p><p>萝莉梦魔似乎对众人的反应很满意，笑嘻嘻地摆出撒娇的动作，回应四面八方的吆喝声。虽然露出了蝙蝠般的翅膀，但大家都以为只是角色扮演。</p><p>「你刚刚不是说，自己变成性幻想对象，感觉就不一样吗？」</p><p>「我说过那种话吗？」</p><p>「这、这个臭丫头……」</p><p>不要一脸无辜地歪着头瞒混过去啦。</p><p>算了。跟我对战的那个老头已经开始喘着粗气，应该失去冷静判断的能力了吧。这样就可以轻松取胜喽？</p><p>来吧，接下来才是重头戏！</p><p>「太奇怪了吧！怎么会每一场都输啊！这样是诈欺吧！」</p><p>「呃，不，应该只是你的运气太差了。」</p><p>坐在对面的老头子明明一路狂赢，脸上却直冒冷汗。</p><p>萝莉梦魔在老头子旁边笑盈盈地为他斟酒。</p><p>「放弃吧，达斯特先生。我会跟这位先生去吃豪华大餐，你自己先回去吧。」</p><p>「这、这家伙……！」</p><p>在赌局中发现这个老头是超级有钱的地产大亨后，萝莉梦魔就不再替我声援，自己投向对方的阵营。</p><p>老头子也不争气地露出了色眯眯的嘴脸。</p><p>「你想吃什么？我会让你尽情享用喜欢的菜色！」</p><p>「呀～～好高兴喔～～人家会好好享用的～～」</p><p>开始狂拍马屁了啊，喂！</p><p>双方都各怀鬼胎的这段对话，让我感到不寒而栗，但主要也是因为我现在只剩一条内裤了。</p><p>「我不服！我平常很少会输成这样，所以一定是你耍老千！」</p><p>「对啊对啊！这间赌场太奇怪了！私底下肯定在做些不法的勾当！你们想对我这位貌美如花的祭司设局，用『嘿嘿，付不出钱就知道该怎么做吧？』这种话威胁我，逼我做色色的事对吧！只要现在坦承罪状、表达忏悔、把赌金还我，并将今天的营业额全数捐献给阿克西斯教的话，我就饶你一命！」</p><p>有个人用比我的抗议声还大的音量，吼了一些莫名其妙的话。</p><p>我忍不住回头察看。映入我眼帘的，是一名身穿蓝色基调修道服的女性。</p><p>……最惨的是，我对这张脸有印象。之前去买那个御什么的人的魔剑时，和这个阿克西斯教的糟糕祭司有过牵扯。</p><p>我不知道她叫什么名字，也不想知道，但只要跟她扯上关系，肯定不会有什么好下场。</p><p>「喂，祭司大人怎么会在赌场里啊？」</p><p>「阿克西斯教并没有禁止赌博！我们的教义是『压抑自我认真地生活，或是不好好努力耍废过活，也无法得知明日会发生什么事。与其在意未知的明日，不如全力活在当下』！」</p><p>这家伙堂堂正正地说着脑子有病的教义。她好像不记得我是谁。</p><p>「整体来说，我也同意这种思维模式，但你们这样真的好吗……」</p><p>只要看那个宴会祭司，就能彻底明白阿克西斯教是多么糟糕。他们真的是一群卑劣的家伙。谣传连魔王军都不会对阿克西斯教出手。</p><p>「喂，喂！是谁把这么难搞的客人放进来的！」</p><p>「我不是再三叮咛，唯独不要跟阿克西斯教扯上关系吗！」</p><p>「非常抱歉！因为她一开始很安分……」</p><p>发现这个女人是阿克西斯教徒之后，荷官和赌场的经营者都吵嚷起来。</p><p>「别说这些了，你也是这间恶质赌场的可怜牺牲者吧！一起向巨大的邪恶势力宣战吧！将因为诈赌而失去的金钱讨回来！话说要是不把钱还我，我今天的住宿费就没着落了！」</p><p>「连住宿费都赔光了啊。喂喂，你收敛一点啦。」</p><p>「……你不觉得要先照照镜子再说吗？」</p><p>只剩一条内裤的我似乎没什么说服力。</p><p>「今天就先放你们一马，但我只想讨回我的赌金。否则我谎称要去寻找失联的杰斯塔大人，借此强行要来的旅费就化为乌有了！」</p><p>「你、你这家伙……」</p><p>虽然不知道杰斯塔是谁，但既然是来找人，为什么还要赌博啊？</p><p>「如果不还我钱，我也有我的考量。从明天开始，我会将这间赌场指定为阿克西斯教徒的集合地点！大家每天都可以延揽教徒、捡十掉在地上的钱币，过着乐趣无穷的生活！」</p><p>「太过分了！拜托别做这种事！」</p><p>祭司的威胁，让看似店长的男子深感焦虑。</p><p>我要不要趁势大闹一番呢？和阿克西斯教徒为敌虽然可怕，但和他们站在同一阵线，其他人也会为之恐惧。</p><p>……老实说，跟阿克西斯教徒结盟确实令我不安，但如果只是暂时合作，应该还行吧。</p><p>「就是说嘛。之后会聚集一大堆脑残的家伙喔！不想看到这种事发生，就把我输掉的钱统统还来！而且往后的每场赌局都要让我赢，听见没有！」</p><p>「对啊对啊。你说得真有道理。我可以特别赐予你加入阿克西斯教的权力喔！」</p><p>这家伙干嘛忽然用又羞又怒的口气讲话？</p><p>不要若无其事地把入教申请书跟笔递过来。</p><p>「奇怪？……听说处男很喜欢这种语气啊。」</p><p>「谁、谁是处男啊！我可是身经百战，在阿克塞尔夜夜笙歌，睡了无数个女人导致睡眠不足呢！」</p><p>「咦？达斯特先生就是没有对象，才会来我们店里消费吧？晚上也睡得很安稳吧？」</p><p>这个萝莉干嘛多嘴啊……</p><p>你专心取悦那个老头子就好了啦！</p>`,295),e(f,{src:`/images/E4/07.avif`,alt:`插图`,width:`850`,height:`1257`}),s[11]||=a(`<p>「对了，我们是不是在哪里见过面？这看似小混混又不太起眼的长相，我好像见过，又好像没见过……如果长得很帅，我就会马上想起来。」</p><p>「要你管。别说这些了，你们打算怎么做？要把钱还给我们，还是让这里变成阿克西斯教徒的集会场所？选一个喜欢的吧！」</p><p>「也可以顺便入教喔！」</p><p>看似店长的男子听到我们两个的恐吓，叹了口气并举起手来，接着用力挥下手臂，指着我们喊道：</p><p>「把这些人赶出去！」</p><p>我们被黑衣人团团包围后，不由分说地被塞进店外的垃圾桶里。</p><p>「又是垃圾桶！我都快习惯这个臭味了！」</p><p>「居然将我这个美若天仙的祭司塞进垃圾桶，你们会遭天谴！……被玷污的美女祭司感觉好色情喔。啊，这个便当都没有拆开嘛，真是暴殄天物。」</p><p>从垃圾桶里用力探出头的祭司，一脸愉悦地拿着剩饭……她该不会要吃吧！</p><p>这位祭司还在翻找垃圾桶，看能不能挖到其他东西。阿克西斯教实在太离谱了。</p><p>「闻起来没什么问题，应该还没坏。这位迷惘的小混混孤狼啊，如果你肚子饿了，我就将这个便当便宜卖给你吧。」</p><p>「开什么玩笑！谁要吃那种东西啊！你自己吃不就得了！」</p><p>「圣职者才不会做出这种事。难道你没有常识吗？」</p><p>「有常识的祭司哪会把剩饭卖给别人啊！所以我才讨厌跟阿克西斯教徒打交道！」</p><p>之前去阿克西斯教大本营时，我就得到了惨痛的教训。跟这些人扯上关系根本没好处。</p><p>明明知道这一点，还是不该一时冲动，跟她有所牵扯。</p><p>「对了，你明明一丝不挂，为何还带着那把剑？我记得你刚刚说自己没钱，既然如此，把剑卖掉不就好了？啊，我想到一个好主意。将那把剑借给我吧。我向阿库娅女神发誓，我一定会用好几倍的价格卖出，再把钱还给你。」</p><p>「当然不行啊！跟你家神明发誓根本不足为信。这是非常重要的人送给我的珍贵逸品。怎么可能交给你这种女人啊！」</p><p>我从试图抢夺的女祭司手中护着长剑。</p><p>「干嘛这么激动。看你充满爱意地抱着长剑……难道你连那种都OK吗？虽然阿克西斯教认同同性恋、近亲和异种族之爱，但恋物的门槛实在太高了。」</p><p>她好像搞错什么了，但我连纠正她都嫌麻烦。</p><p>「囊空如洗了。真伤脑筋，我该去寻觅阿克西斯教徒，还是去给艾莉丝教找麻烦呢？」</p><p>「别烦恼这种事。对了，你刚刚不是说，是为了找某个人才来埃尔罗得吗？」</p><p>虽然忘记名字了，但她刚才嚷嚷说是要来找某个人，还赔光了旅费。</p><p>听到我的疑问，这位当事人双手环胸歪过了头。过了一会儿，她才睁大双眼，双掌一击拍出声响。</p><p>「我当然记得。是的，我记得一清二楚。我是来寻找阿克西斯教团最高领导人——杰斯塔大人！」</p><p>「根本忘了吧……」</p><p>我用怀疑的眼神看向她，她立刻别开视线。</p><p>这家伙压根忘记这件事，彻底玩疯了吧。</p><p>「我听不懂你在说什么。我事前接获情报，杰斯塔大人似乎逮住了在赌场连吞败仗，心灵饱受摧残的客人，用花言巧语规劝他入教，我才会来赌场进行监视！」</p><p>「别用那种方式劝人入教好吗……」</p><p>「你在说什么傻话？透过一般的规劝方式，根本没几个人会加入阿克西斯教，所以要用尽各种手段才行啊。」</p><p>「喂，你们搞错努力的方向了吧？」</p><p>「什么意思？你这人说话还真奇怪。」</p><p>我能理解阿克西斯教的考量，只是一旦入教，感觉某种事物会就此终结。但似乎会打开其他路线就是了。</p><p>「那你别再赌了，赶快去找那个叫作杰斯塔的人，或是去传教啦。」</p><p>「老实说，就算杰斯塔大人不在，对教团而言也不会有任何困扰，教团营运反而能更加顺利呢。如果要传教的话，我想锁定多金的小帅哥，才会像这样天天往赌场跑！」</p><p>虽然我早就知道了，但这家伙真是个废物。</p><p>「我很忙，没时间跟穷人聊天了。得赶紧让有钱人入教，让他捐献赌金才行。」</p><p>自称美女的这位祭司浑身沾满垃圾，就这么消失在夜晚的大街上。</p><p>不处理一下身上的垃圾臭味要怎么传教啊？但我实在不想再跟她有所牵扯，还是别管她了。</p><p>「……回去吧。」</p><p>我已经精疲力尽，赌金也耗光了，于是乖乖地回到旅店。</p><h3 id="_7-1" tabindex="-1"><a class="header-anchor" href="#_7-1"><span>7</span></a></h3><p>「快点起床，和真他们有所行动了。」</p><p>「嗯啊～～现在才早上耶。」</p><p>「早上就该起床了吧。」</p><p>泰勒说了些我听不懂的话。</p><p>在床上坐起上半身后，我将头转向窗户，发现旭日光芒已经倾洒而下。</p><p>奇斯在窗边盯着外头看。</p><p>「一大早就这么严肃，还穿得正经八百的，他们是要去哪里啊？」</p><p>我也从奇斯身后往外看，但只看见一个小点。</p><p>到女生房间叫琳恩的时候，我发现萝莉梦魔睡眼惺忪。</p><p>啊，果然是这样。梦魔跟色老头两人独处，不变成这样才怪。</p><p>我用不会被周遭听闻的音量对萝莉梦魔低语，问她昨天离开赌场后发生了什么事。</p><p>「昨天好玩吗？」</p><p>「嗯，他是个很温柔的爷爷。他有个孙女跟我很像，但孙女对他很冷淡，因此没办法跟孙女共享天伦乐，于是他就把我宠上了天！我特别送他一个跟孙女共同玩耍的美梦。」</p><p>「真是太好了。」</p><p>跟我预想中的发展截然不同。原来没有发生色色的事喔？</p><p>「怎么？难道你在担心我吗？」</p><p>「哪有。不要一边窃笑还用手肘戳我的侧腹！」</p><p>我干嘛担心梦魔啊。因为我要负一点点责任，所以有点担心她会不会碰上麻烦就是了。</p><p>「好了好了，别再拌嘴了，走吧。」</p><p>有点起床气的琳恩拉着我们，离开了旅店。</p><p>和真一行人朝着王城直直前进。</p><p>他们在王城前似乎有些骚动，但很快就平息下来，接着又过了几分钟。</p><p>「虽说埃尔罗得应该不会赶走他们，但对方似乎不允许他们进城呢。」</p><p>泰勒双手环胸，并如此喃喃道。</p><p>太奇怪了。堂堂一国王女来访，应当先将她迎进城内才是常识。居然让王女在城门外等候，这种行为被评为侮辱也怨不得人。</p><p>难道是存心挑衅？埃尔罗得跟贝尔泽格的关系应该很和睦。做出这种事是会有什么好处，实在令人费解。</p><p>「一个红发小鬼带一大票人出来，双方好像起了争执。啊，他随便挑衅惠惠跟阿库娅，现在吓得要死。实在太蠢了，干嘛跟那两人为敌啊。」</p><p>用「千里眼」窥看的奇斯拍了拍手，觉得眼前的景象很有趣。</p><p>毕竟红魔族开不起玩笑嘛。尤其是那个爆裂女孩，不但很容易被激怒，爆发的威力还非比寻常。挑衅她简直是不要命的行为。</p><p>阿库娅是阿克西斯教的大祭司，所以她的脑袋有问题，还是别跟她扯上关系为妙。</p><p>「好像有个感觉是高官的男人解决了现场的纷争，让他们进去了。怎么办，我们没办法跟到城内监视吧。」</p><p>「蕾茵之前说，进城之后就不用多管了。接下来就是自由时间了吧？各位辛苦啦～～」</p><p>「怎么可能啊。」</p><p>我挥挥手准备离开现场时，琳恩便扯着我的衣领将我抓回去。</p><p>啧，我还以为可以趁这大好机会开熘呢。</p><p>「在和真他们出来之前，乖乖留在这里监视吧。」</p><p>我们遵从泰勒的指示，在城门附近打发时间时，和真他们就走出城外了。爱丽丝看起来灰心丧志的，旁边的人都在安慰她。</p><p>「大小姐是来见未婚夫吧？是不是跟在王城工作的未婚夫吵架了？」</p><p>「天晓得。我们只负责监视护卫，不论她的家务事跟婚约会怎样，都跟我们无关吧。」</p><p>我随口敷衍奇斯这个无关紧要的问题，结果伙伴们都眯起眼看着我。</p><p>要不要同情随便他们，但这不是我们能随意置喙的问题。虽然有点担心，但毕竟还有和真他们在，把公主殿下交给他们就行了吧。</p><p>「……虽然这么说有点冷漠，但达斯特说得确实没错。我们继续跟踪吧。」</p><p>琳恩他们不太情愿地接受泰勒的说词后，便追上了他的脚步。</p><p>结果今天一整天没发生什么怪事，平安顺利地度过了。</p><h3 id="_8-1" tabindex="-1"><a class="header-anchor" href="#_8-1"><span>8</span></a></h3><p>隔天只有和真和爱丽丝单独进城，其他三人个别行动。</p><p>萝莉梦魔今天也去陪那个有钱老头吃饭，和他在街上到处观光，所以现在不在这里。</p><p>「没时间了，快点决定吧！猜拳赢的人可以指定跟踪对象，没意见吧？」</p><p>我这么说完，大家都点点头。</p><p>于是，决定今日命运的猜拳之战就此展开。</p><p>「太棒了！我负责监视和真！」</p><p>首先赢得胜利的泰勒，勾起了一抹奸笑。</p><p>「可恶！最轻松的差事被抢走了。剩下那三个人啊……全都是下下签嘛。」</p><p>「达斯特，一样是下下签，也有分还过得去的跟更糟的吧。」</p><p>「下一轮没有赢的话，我只有不祥的预感。」</p><p>奇斯和琳恩都展现出我从未见过的严肃表情。</p><p>老实说，虽然三个人都有点微妙，但其中一个还算有点常识。</p><p>「猜拳吧！剪刀、石头……」</p><p>「「「布！」」」</p><p>我出布，一旁的奇斯也出布。琳恩出的……是剪刀。</p><p>「太好了、太好了！好，我要达克妮丝！」</p><p>「混帐啊啊啊啊啊！被琳恩摆了一道！她把脑残三人组相对正常的那一个抢走了！」</p><p>「喂喂，只剩爆裂女孩跟宴会祭司啊……怎么会有这种终极的二选一……」</p><p>琳恩乐得蹦跳起来，我跟奇斯则跌坐在地。</p><p>虽然达克妮丝的鲁莽举止和变态行为也大有问题，但除了战斗之外，感觉还满正经。只要没打开超级被虐狂的开关，就是相对正常的。</p><p>「是我的错觉吗？我觉得下一轮不管是赢是输都没差耶。」</p><p>「好巧喔，奇斯，我也有同感……还是有点差别啦。一个是会一口气扯出超大的问题，一个是会接连不断地疯狂闯祸。」</p><p>「就看是要吃上一发超勐攻击，受到濒死的重伤，还是要持续受到中毒的伤害啊……」</p><p>如果问我哪边比较好，我会回答两边都不想要。</p><p>和一脸沉痛的奇斯猜拳后的结果——</p><p>「是爆裂女孩啊……」</p><p>我要负责监视别人剩下不要的爆裂女孩。</p><p>顺带一提，猜拳赢的人虽然是奇斯，但他一点也开心不起来。</p><p>「不过，她是要去哪里啊？」</p><p>爆裂女孩似乎已经决定目的地了，只见她毫不犹豫地穿过赌场林立的闹区。</p><p>离开大街后，她又走了很长一段距离，四周逐渐变成不见民宅，充满自然气息的景象。</p><p>虽然有潺潺溪水，但我知道她不是会天真跑去戏水的那种人。</p><p>「和真也真是的，不要直接放生这个问题儿童，还不打算监视啊。」</p><p>「你真的不懂耶。萝莉就是要淘气点才可爱。那对弹性十足的翘臀，今天也神采奕奕地摇个不停呢。」</p><p>「唔喔喔喔！」</p><p>我被忽然传进耳里的声音吓了一大跳，回头一看，发现是前天那个女祭司。</p><p>这家伙为什么眼神淫猥地流着口水啊？</p><p>「你、你是从哪里蹦出来的？」</p><p>「惠惠在哪里，我就在哪里。早上发现她的行踪后，我就一直静候她身边的人离开，现在就逮到大好机会了！这里杳无人烟，我就借着打招呼之便，摸遍她的胴体。她应该会允许我这么做吧！」</p><p>「给我等一下。」</p><p>女祭司准备朝着惠惠走去，我勐然抓住她的手。</p><p>「咦？现在是要搭讪我吗？我是不讨厌霸王硬上弓，但现在没那个心情。而且我只对有钱人跟小帅哥有兴趣。」</p><p>「谁会做这种奇怪的事啊。我现在在跟踪，你走过去的话就曝光了。」</p><p>「咦？追在萝莉小女孩后面跑……你是变态吗！」</p><p>「你好意思说啊！听你的语气，你认识爆裂女孩吗？」</p><p>「我们是可以一起洗澡的亲密关系。我就像肉体与灵魂都与她紧紧相系的大姊姊！」</p><p>虽然她说得自信满满，但她的各种言行举止都很不真实。</p><p>再说，没人会真的相信阿克西斯教徒所说的话。</p><p>「姊姊什么的就算了，原来你们认识啊……你能不能稍待片刻再跟她重逢？」</p><p>「为什么？我现在就想马上抱紧处理，将萝莉香气吸满我的整个胸腔。」</p><p>我原本就知道她是个危险人物，没想到危险到这种程度。</p><p>我根本不在乎爆裂女孩会不会陷入危险的处境，但要是和真一行人发现我们可就糟了。</p><p>只好随便找个借口阻止她行动。</p><p>「既然你无论如何都要过去，我也不会阻止。可是你真的要这么做吗？想想她现在在什么地方吧。这里是河岸边，又只有她一个人……你懂我的意思吧？」</p><p>「难、难道她是要……上厕——」</p><p>「应该是洗澡吧。」</p><p>我开口打断这番变态发言。</p><p>「那就另当别论了。我知道了，我会含泪忍耐！」</p><p>虽然还不到咬牙握拳的程度，但她懂得收敛就好。</p><p>我们两人远远地观察着爆裂女孩，沿着河川继续往前进。</p><p>过了一会儿，视线前方出现了满是栅栏的景象。</p><p>「有招牌耶，上面写着……大葱鸭养殖场。这么说来，这里的观光景点除了赌场之外，好像还有大葱鸭养殖场啊。奇怪？她在跟职员吵架吗？」</p><p>「如果发生什么事，我就得马上冲过去才行！」</p><p>我一边警戒粗喘不已的女祭司，同时定睛察看。</p><p>爆裂女孩想走进养殖场，但看似职员的人们拼命地阻止她。</p><p>我们偷偷来到足以听见谈话内容的距离，就听见他们的喊叫声。</p><p>「她又来了！大家快压住她！」</p><p>「谁快拿绳子过来！还要塞住她的嘴！」</p><p>「这、这是在做什么！住、住手！」</p><p>职员们想齐力压制住爆裂女孩，没想到她却拼死抵抗，让众人陷入苦战。</p><p>「明明是个萝莉，力气却这么大！好痛！可恶，不要挣扎！」</p><p>「别把我当成小孩！把我当成渴求鲜血的野兽吧！」</p><p>少女被成年男子们从身后架住的画面，确实应该提供帮助才行……但考虑到她平常的所作所为，就觉得事出必有因。</p><p>「他们想对我的惠惠做什么！喂，放开我！」</p><p>女祭司一副随时要冲出去的样子，于是我抓住她的衣袖。</p>`,164),e(f,{src:`/images/E4/10.avif`,alt:`插图`,width:`850`,height:`1257`}),s[12]||=a(`<p>「又不是你的。既然要救，就等状况更危急时再现身吧，她应该会对你心存感激。」</p><p>「令人仰慕的美女大姊姊祭司，在紧急时刻飒爽现身！还不赖耶。你的提议真不错！」</p><p>这位祭司是不是被私人利欲蒙蔽了双眼？但毕竟她是阿克西斯教徒，我实在无法吐槽。</p><p>不过，爆裂女孩为何会被众人五花大绑呢？</p><p>早知如此，要是前天奇斯他们说那三人闯的祸时，我有问清楚一点就好了。就算想出手相助，我们也不能曝露行踪。</p><p>「再观察一下吧。」</p><p>我们又离他们更近一点，这次就能清楚听见他们在说些什么了。</p><p>「前天做了那种事，你今天竟然还好意思过来啊！居然将我们注入心血苦苦培育的大葱鸭炸死……」</p><p>「眼前出现一群大葱鸭，就该不由分说地用爆裂魔法攻击，这不是常识吗！」</p><p>「从来没听过这种常识啦！」</p><p>原来如此。前天爆裂女孩引发的骚动，就是在大葱鸭养殖场击发了爆裂魔法啊。</p><p>大葱鸭这种怪物的经验值丰富，肉质也很肥美。冒险者们都将其视为绝佳的饵食，所以都会去袭击人工养殖场……不，一般人不会做这种事。</p><p>「这里的大葱鸭，不就是为了被人打倒而养育的吗？那么，比起败在名不见经传的冒险者或贵族手下，能化为我这擅使爆裂魔法的大法师惠惠的食粮，它们应该感到高兴才是！」</p><p>「它们在黄泉之下泣不成声了啦！」</p><p>爆裂女孩抬头挺胸地掀起披风这么说着。明明被疯狂炮轰，她却不当一回事，依旧不改其粗神经的恶习。</p><p>我决定了，不出手救她也无妨！</p><p>不管怎么想，职员们都没有错，就别管她了。</p><p>「至于前天的赔偿金，那些人应该已经付清了。」</p><p>「是啊，年轻人一边哭一边缴清了……」</p><p>被这家伙炸飞的大葱鸭赔偿金，原来是由轻浮男支付了。</p><p>这样啊……那群人也辛苦了。真可怜。</p><p>「请回吧。我们不想再跟你扯上关系了。」</p><p>「哼，你确定？我跟达克妮丝拿了点零用钱，今天确实带着大葱鸭的费用过来了呢。」</p><p>「都已经炸掉那么多只了，你还不满意啊……算了，随便你吧。炸爽了就快磙，再也不要过来了。」</p><p>职员们一脸筋疲力尽的样子。脱离他们的掌控后，爆裂女孩兴高采烈地追逐着幸存的大葱鸭。</p><p>谁快把和真叫过来啊……</p><p>「惠惠小姐好像很开心呢。呵呵，我也加入她的行列吧。」</p><p>「情况会变得很复杂，拜托你打消念头吧。对了，你不是还在找人吗？」</p><p>「啊……可是，与其去搜索行踪不明的杰斯塔大人，你不觉得视奸惠惠小姐兴奋玩耍的身影比较重要吗？」</p><p>「不觉得。我会告诉你她住在哪间旅店，想见她的话，就等晚上再行动吧。跟你同样信奉阿克西斯教的蓝发祭司也在。」</p><p>要是让她们碰面，跟踪任务就会变得很棘手，于是我提出了这个建议。结果女祭司一脸惊愕地瞪大双眼。</p><p>「阿库娅大人也在吗？」</p><p>「哦，对啊。你们果然认识啊。毕竟阿克西斯教徒很少嘛。」</p><p>「这样就另当别论……我要去找杰斯塔大人了！」</p><p>她马上放弃爆裂女孩，不知道冲到哪里去了。</p><p>真搞不懂阿克西斯教徒的思维。</p><h3 id="_9" tabindex="-1"><a class="header-anchor" href="#_9"><span>9</span></a></h3><p>歼灭了大葱鸭，心满意足的爆裂女孩回到旅店后，和真他们也已经回来了。</p><p>听琳恩他们说，达克妮丝好像在街上打听什么情报，宴会祭司则在赌场输光了所有零用钱。</p><p>由于晚上没什么特别的动静，我们也决定休息。</p><p>接下来，和真跟爱丽丝每天都会进王城一趟，剩下的人就各自行动。自此之后的每一天，也没有引发什么大骚动。</p><p>……顶多偶尔会从王城那边传来尖叫、惨叫和爆炸声就是了。</p><p>我还以为可以继续过着愉快又充满观光乐趣的日子，结果从王城回来的和真看起来不太对劲。</p><p>「和真气到发狂了，还一直嘟哝着『我饶不了那个家伙！』之类的话。而且大小姐也很消沉，和真在跟她讲话时，她也心不在焉。」</p><p>今天负责监视和真的奇斯双手环胸，仰头看着天际。</p><p>「呐，他们真的只是去见未婚夫吗？是不是有点可疑啊？」</p><p>「委托人蕾茵都这么说了，我们也只能相信。就算真有内情，还是别知道太多比较好。别说这些了，之后要怎么办？」</p><p>我们的工作是监视和真一行人，以及保护爱丽丝。即使这件事攸关王国，我们也没理由继续深究。</p><p>因为这里没有冒险者出场的余地。夜晚陪公主殿下出去转换心情，就已经是极限了。</p><p>而且公主殿下似乎已经心有所属。兄弟，就拜托你照顾她了。</p><p>「毕竟和真偶尔也会做出惊人之举，老实说，我很担心。」</p><p>「虽然和真总是扮演监护人的角色，行动力却高得异常。」</p><p>也难怪泰勒跟琳恩会显得忧心忡忡。</p><p>和真一行人有过破坏阿克塞尔城墙，以及炸飞领主宅邸的前科。甚至还在结婚典礼上从阿尔达普手中抢走达克妮丝。</p><p>就算他们在埃尔罗得闯出什么大祸也不足为奇。应该说早就已经搞出好几件事了。</p><p>「要不要派谁潜入他们的旅店探勘情报？」</p><p>「可以把这个任务交给我吗？我想报答各位把我带来这里的恩情。虽然我的魔法在战斗中派不上用场，但这种时候应该能出一份心力！」</p><p>既然萝莉梦魔奋力举手毛遂自荐，我本来想将这件事全权交给她负责，但不知为何连我都得一起去。</p><p>「为什么我也得一起潜入不可？」</p><p>「因为你这几天都假借监视之名泡在赌场里吧？还擅自动用了回程的旅费。」</p><p>我在和真他们入住的高级旅店附近如此埋怨，一旁的萝莉梦魔显得一脸无奈。</p><p>「我能怎么办？谁教这里有赌场嘛！」</p><p>「你就没有自制力吗？」</p><p>「没有！想做的事就去做！不想做的事就打混摸鱼！这就是男人的生存之道！」</p><p>「给我跟全世界的男人道歉。」</p><p>我没把碎碎念的萝莉梦魔当一回事，并抬头看向眼前的建筑物。</p><p>整体外观比我们入住的旅店明显高了一个层级。</p><p>「就算要潜入，这种旅店也没办法让我们随意进出。现在要怎么做？我看先放把火烧了，趁工作人员逃出来的空档潜入吧。那就拜托你喽。」</p><p>「我才不要！」</p><p>我把这么重要的任务让给她，她居然挥拳抵抗。</p><p>「我已经有对策了，包在我身上。我们可以随意进入，请跟我来吧。」</p><p>她自信满满地站在旅店前，直接开门走了进去。</p><p>「喂﹑喂喂，会被赶出去啦！」</p><p>我担心地出声制止，结果看似旅店警卫的男子们早已站在我们眼前。</p><p>看吧，这下可好了！</p><p>「晚安～～」</p><p>萝莉梦魔完全不怕这群冷酷的男子，若无其事地开口打招呼。她在想什么啊？</p><p>「哦～～你来啦。今天也过来玩吗？」</p><p>只见那群男子分为两列，后头则是先前和我在赌场激烈对战过的那个老头子。</p><p>那家伙也住在这里啊？</p><p>「嗯嗯，今天我还带了好朋友达斯特先生一起来，不行吗？」</p><p>「哎呀～～当然可以啊！既然是萝莉莎的朋友，我也非常欢迎……嗯～～是之前在赌场见过的那个男人啊。爷爷不赞成你跟小混混来往喔。萝莉莎，朋友要慎选才行！」</p><p>不要一脸厌恶地用斜眼看我。</p><p>「好，我会铭记在心。爷爷最近睡得好吗？」</p><p>「啊啊，讬你的福。跟萝莉莎聊过天后，那天晚上就能作个好梦，每天都睡得很安稳呢。谢谢你为我担心。」</p><p>那副笑容满面，温柔倾诉的模样，就像是对孙子说话的和蔼老爷爷。</p><p>他们的感情不知不觉变得这么好啦。</p><p>「因为达斯特先生一直吵着要看这间大饭店里头是什么样子，我能带他进去参观吗？」</p><p>萝莉梦魔将手指抵在脸颊上，身体摇来晃去地发出撒娇的嗓音。</p><p>我虽然很想吐槽，但既然此举能奏效，我还是保持沉默好了。</p><p>「那当然。我会跟这里的老板知会一声，你们就自由参观吧。我还准备了零用钱给你喔。」</p><p>「谢谢，我最喜欢爷爷了！」</p><p>被萝莉梦魔抱住脖子的老头，脸上的笑容更是松懈不已。</p><p>就算再没用，她还是个梦魔啊。拢络男人的手腕真是高明，佩服佩服。</p><p>我和萝莉梦魔得到自由探索旅店的权利后，便前往事先调查过的和真等人所入住的房间，并在门前竖起耳朵偷听。</p><p>他们讲得很大声，因此隔着一扇门也能听得一清二楚。</p><p>『——事情就是这样。我想教训一下那个死小孩。』</p><p>『好，你说得对极了，和真。不过就是只会赚钱的埃尔罗得，哪能任他们瞧不起我贝尔泽格啊！居然将爱丽丝殿下看得那么扁，那个小鬼，我要宰了他！』</p><p>和真和达克妮丝都气到抓狂了。</p><p>偷听这段对话后，我就能理解大致的状况了。</p><p>爱丽丝跟埃尔罗得的第一王子雷维有婚约，但对方却取消了婚事，甚至还说要终止对贝尔泽格王国的防卫经费援助。不仅如此，还百般嘲弄爱丽丝，让和真大发雷霆。</p><p>埃尔罗得的宰相好像说了经费不足这个理由，但光看街道的模样，只觉得埃尔罗得的钱多到花不完，非常兴盛繁荣。</p><p>……总觉得有点内幕，但跟我们无关。</p><p>「请、请问，听他们这么说，感觉依丽丝小姐其实就是名为爱丽丝的王女殿下……这有可能吗？」</p><p>「没错，这是我们之间的秘密喔。」</p><p>「咦咦……！」</p><p>萝莉梦魔差点惊呼出声，我赶紧捂住她的嘴。</p><p>「这件事攸关国家问题，不能对外透露喔。一不小心就会赔上小命。」</p><p>被我捂着嘴的萝莉梦魔点了几下头，应该没问题了，我才松开手。</p><p>「达斯特先生也知情吗？……难道你不但知情，还借此要胁对方，如果想你守住秘密就给你钱？」</p><p>不要吓得往后退好吗？</p><p>「我又没有笨到会跟王国为敌，怎么可能做这种事啊。我是前阵子跟她扯上关系时偶然得知的，但一直装作没发现。奉劝你也保持沉默比较好。」</p><p>「是啊。真不想知道这种事。」</p><p>好了，该怎么办呢？</p><p>那群人虽然常常做蠢事，但总有和真负责阻止。这回却是和真冲在最前面，情况十分棘手。</p><p>「先回去伙伴们那边好了。」</p><p>我们偷偷离开旅店，和琳恩他们会合。</p><p>我向他们说明埃尔罗得那帮人的诡计，但将最关键的部分舍弃不谈。</p><p>「因为大小姐的未婚夫瞧不起她，所以和真他们就气到快抓狂了，对吗？虽然能理解他们的心情，但也闹得太夸张了吧。」</p><p>「半夜击发爆裂魔法引发骚动，趁城里的警备涣散时，和真就潜入王城，威胁在王城里工作的未婚夫？完全是犯罪行为嘛。」</p><p>「虽然应该出手制止，但要是我们的行踪曝光，就会违反契约。」</p><p>我看着伙伴们凑在一起讨论的画面，但从刚刚开始，我就觉得有点不对劲。</p><p>听了和真他们的作战计划，我虽然也一样担心，却觉得哪里怪怪的。</p><p>「如果这里是阿克塞尔，就算施放爆裂魔法，顶多只会被骂个几句就没事了吧。」</p><p>萝莉梦魔苦笑着这么说。闻言……我才恍然大悟。</p><p>「这样啊，你说得没错。这里是埃尔罗得，我想应该没问题。」</p><p>我这么说完，大家都不明所以地皱起了眉。</p><p>我们跟在和真一行人后头，发现他们避开门卫的视线，离开了这个城镇。</p><p>我们躲在城门附近，让奇斯用「千里眼」窥视，并告知目前的状况。</p><p>「他们往那座稍微高起来的小丘移动了。喂喂，真的要这样搞喔？惠惠开始咏唱魔法了喔！」</p><p>循着奇斯的视线方向望去，发现黑夜中浮现出一道奇妙的光芒。</p><p>那是爆裂魔法的光线！</p><p>「捂住耳朵！」</p><p>我们用双手捂住耳朵的同时，爆炸引发的巨响和强风顿时席卷而来。</p><p>「刚、刚才的光芒跟声响是怎么回事！」</p><p>城门附近的士兵们全都躁动起来，这时我佯装惊慌地冲了出去。</p><p>「救、救命啊！有一群脑残在那座山丘上施放了威力非同小可的魔法！」</p><p>「什么！在哪里，请你说清楚一点！」</p><p>将和真等人的所在位置告诉士兵后，我便目送他们远去。</p><p>我跟伙伴们一起偷偷跟在后面，发现宴会祭司跟和真他们不知为何被不死族追着跑，最后还被逮捕了。</p><p>伙伴们从头到尾都一脸愕然地看着这一切。</p><p>「我说过不用担心吧。」</p><p>我对他们这么说。</p><p>「这里可不是阿克塞尔。一般来说，闯出这种大祸自然会落得如此下场。至于为什么会被不死族包围……这一点就不得而知了。只要把他们关进牢房，他们就不会做出更愚蠢的行为了。回去睡觉吧。」</p><p>等到骚乱不安的夜晚告一段落，精神上已经筋疲力竭的伙伴们睡着后……我悄悄地离开了房间。</p><p>虽然手边没钱，让我安分了好几天，但今天至少可以去夜游一下吧。</p><p>时至深夜的阿克塞尔，街上的店面大部分都打烊了，但埃尔罗得不一样。</p><p>赌博王国是个不夜城。现在都已经三更半夜了，街上还是被灯光点缀得五彩斑斓。</p><p>「而且还拿到了赌金呢。」</p><p>我手上有一大笔钱。被萝莉梦魔迷得团团转的老头说「帮我拿给萝莉莎」，要我把这笔零用钱转交给她。</p><p>只要将这些钱当作赌金大赢一笔，翻个好几倍再还给萝莉梦魔，她应该就不会抱怨了。</p><p>「好啦，虽然对被关进牢里的和真他们不好意思，但我要玩个痛快！既然上次闹过场的那间店将我设为拒绝往来户，今天就去这一间吧。」</p><p>只要我屡战屡胜，把钱还给萝莉梦魔之后，就用剩下的钱，让伙伴们入住阶级更上一层的旅店吧。</p><p>底下是冰冷的石子地板。眼前是微微出现锈蚀的铁栏杆。</p><p>充满潮湿霉味的房里，只有铐住囚犯的锁链和肮脏的厕所。</p><p>我愣愣地看着挂在前方信道上的灯火，搔了搔脑袋。</p><p>「……这是怎样啊啊啊啊啊！」</p><p>现在的我，居然在监狱里。</p><h2 id="第三章-和那位首领一起逃狱" tabindex="-1"><a class="header-anchor" href="#第三章-和那位首领一起逃狱"><span>第三章 和那位首领一起逃狱</span></a></h2><h3 id="_1-2" tabindex="-1"><a class="header-anchor" href="#_1-2"><span>1</span></a></h3><p>这里比我在阿克塞尔住惯的牢房还要大。</p><p>可是天花板很低，又没有窗户，显得压迫感十足。</p><p>「我怎么会在牢房里啊？」</p><p>事到如今，我已经不会因为牢狱之灾而感到焦虑，但我却想不起身在此处的缘由。</p><p>「印象中，我在赌场里边喝边赌……一路输到底……因为荷官是个美女大姊姊，我一边对她性骚扰，一边怨声载道地疯狂闹场，接着警察到场对我说『这家伙有在警戒名单里！』就把我逮捕了。到这里为止我都还记得，但我为什么会在这里？」</p><p>「原因就出在这里啊。」</p><p>有人对我的自言自语吐了槽。</p><p>似乎是从信道另一侧的牢房传来的。</p><p>由于光线昏暗，看不太清楚，我定睛一看，发现那里有个人影。</p><p>「还有其他人在啊。你也在赌场大闹了一番吗？」</p><p>「不不不，我只不过是在赌场里对输钱的人宣扬人生的美好。『若有任何烦恼，就快乐地活在当下，让自己放逐至轻松的彼方吧。不要压抑自我，顺着你的本能前进吧。』我只是以这番教义，诱使人们更加沉沦赌海罢了。」</p><p>「……嗯？」</p><p>我好像在哪里听过这个台词。</p><p>「我只是在宣扬教义而已，却被听从布道的那些人的家属勐烈抨击。诸如『我的老公变成白痴了！』『赌输了还想找奇怪的借口！』『他索性摆烂变得好可恶！』等等无凭无据的批评蜂拥而至。」</p><p>「完全有凭有据好吗……」</p><p>「反正都要骂了，我希望他们痛骂我的时候，眼神能再轻蔑一点，对我吐口水也行。」</p><p>男人的开始粗喘起来。听到他的声音，我就确定了。</p><p>这家伙肯定是……</p><p>「你是阿克西斯教徒吧。」</p><p>「哎呀，你真内行。似乎很有看人的眼光呢。」</p><p>「大家都看得出来吧。你待在这里多久了？」</p><p>「这个嘛，大约两周左右吧。不过，幸好你来了。这里只有晚上才会放饭，其他时间我都是孤伶伶一个人，闲得要命呢。虽然放置玩法也别有一番风味，但我还是喜欢直接被痛骂一顿。而且狱守还走女教师路线，真让人兴奋难耐。」</p><p>我不想知道你的性癖。</p><p>这家伙被关两个星期了啊。真令人意外。</p><p>「我听街上的人说，这里穷凶恶极的罪犯不多，所谓的监狱只是形式上用来保护醉汉跟穷光蛋的温暖设施。所以我以为随便闹一闹也无所谓。可恶，我中计了！」</p><p>「我也听过这个说法，但这里似乎是特殊的监狱。不是用来拘留罪刑轻缓的罪犯，而是关捕为数不多的重刑犯。好像是这个国家的宰相秘密建造的。」</p><p>原来如此。有赔光钱财就无理取闹的蠢蛋，自然也会有锁定有钱人的强盗。看准治安良好故意下手的人渣到处都有。</p><p>「但他们是不是搞错了，怎么会把我当成罪大恶极的嫌犯呢？我只是喝了点酒，性骚扰外加闹场而已耶。如果是在阿克塞尔，只会让我在牢房里睡一晚，或念我几句就没事了。」</p><p>「说得没错，这个城镇实在太缺乏包容了，真令人不胜唏嘘。我必须广布阿克西斯教的教义，让居民都能大而化之、不拘小节，自由奔放地活下去才行。」</p><p>「打消这个念头吧。不要再制造出阿尔坎雷堤亚那种城镇了。」</p><p>我之前在阿克西斯教大本营——阿尔坎雷堤亚碰上一堆鸟事。</p><p>光是待在那座城镇里，感觉头脑就会越来越笨，简直恐怖到极点。就算给我钱，我也不想再去第二次。</p><p>「哎呀，你知道阿尔坎雷堤亚啊。其实我在那座城镇担任阿克西斯教的最高领导人，名为杰斯塔。往后还请多多指教。」</p><p>说着说着，那个男人便走到铁栏杆旁。他身上穿着阿克西斯教的法袍。</p><p>这家伙是那个怪胎集团的首领喔。</p><p>感觉只是个不起眼的大叔嘛。话虽如此……却有点不太对劲。到目前为止的言行举止，应该不可能全是捏造或演出来的，但是该怎么说……不，我想太多了。恐怕只是我的错觉。</p><p>「你就是杰斯塔啊。有个女祭司一直在找你喔。」</p><p>「是吗？来找我的应该是赛西莉吧，还是崔丝坦呢？无论如何，看来没有我在，教团里的大家都很担心呢。」</p><p>他似乎深受感动，双手合十向神祈祷。</p><p>还是别跟他说那个祭司压根放弃找人，彻底玩疯的事实好了。</p><p>「担心啊……只有一个晚上还无所谓，要是再多关几天，他们就会多嘴吧。唉，回去之后，泰勒跟琳恩一定会把我抓去训一顿。」</p><p>「教会的人们都在为我担心，我也厌倦这种监狱玩法了，正想离开呢。」</p><p>话虽如此，我现在根本没办法逃出牢房。虽然想确认牢房内的看守状况，但所见范围内，只有眼前那个身穿法袍的男人。</p><p>现状就是，尽管我很想付诸行动，却又无计可施。</p><p>我才这么想着，牢房里便响起一阵高跟鞋的喀喀声。</p><p>「你是半夜被送过来的吧？」</p><p>一名将红发束成马尾，眼神锐利的女子出现在我面前。</p><p>虽然她是个大美女，但整体装扮和散发而出的气势，都跟之前在阿克塞尔见过的检察官瑟娜雷同。</p><p>「原本要把你关在一般牢房，但昨天出现很多醉汉跟闯祸的捣蛋鬼，才破例把你送到这里。」</p><p>她指的是和真他们吧。</p><p>「什么嘛，原来是这样。我还吓了一跳，真是亏大了。可以马上放我出去吧？」</p><p>「是啊。前提是待会儿在侦讯中没有发现任何疑点。这是可以侦测谎言的魔道具。我会用这个进行讯问，请你老实回答。」</p><p>女子将那个小铃放上设置于信道尽头的老旧桌子上。</p><p>那不是关照过我好几次的魔道具吗？只要说谎就会响个不停，吵得要命。</p><p>要用这个魔道具进行侦讯啊，可见这位和瑟娜很像的女人也是检察官。</p><p>「能被美女讯问，根本就是奖励嘛……」</p><p>杰斯塔好像说了什么。</p><p>检察官不发一语，只往那边瞥了一眼。但她明显表现出侮蔑的神情。</p><p>「好啊，无所谓。反正我没做什么亏心事。」</p><p>叮——铃响了。</p><p>「……我还没开始侦讯呢。」</p><p>该死的魔道具，怎么忽然有反应啊？</p><p>检察官用意有所指的眼神紧盯着我不放，于是我别开了视线。</p><p>「咳咳！重新开始吧。你的名字是？」</p><p>「达斯特。」</p><p>叮……刚刚那一瞬间，铃差点要发出响声，却又立刻静下来了。</p><p>「嗯？这反应很奇怪呢。要响不响的，故障了吗？」</p><p>所以我才讨厌这个魔道具。</p><p>「问问其他问题，马上就会知道有没有故障了吧？」</p><p>「说得也是。那么，你昨天在赌场涉及性骚扰和暴力行为，没错吧？」</p><p>「喂喂，我只是稍微和大姊姊有点肌肤接触而已吧。喝醉时不是常常会顺势碰到别人的手或胸部吗？有时候也会不自觉地将手握紧啊。」</p><p>「不自觉？意思是你抓捏过好几次吗？」</p><p>「……只是碰巧吧？」</p><p>「可是根据被害人的指控，她的胸部和臀部都被你摸了好几下喔。」</p><p>「……我要保持缄默！」</p><p>居然把细节都抖出来了。检察官怎么一个个都这么缠人啊。</p><p>「而且我哪有行使暴力，太小题大作了吧。只是拳头很用力碰到他而已。如果是在阿克塞尔，根本不会叫警察过来，当场被人海扁一顿就没事了。」</p><p>女检察官看了看小铃，却毫无反应。</p><p>「阿尔坎雷堤亚也顶多只会被警察追一追，稍微念个几句而已。没什么大不了的。」</p><p>听杰斯塔这么说，女检察官又看了小铃一眼，结果还是没响。</p><p>「……你们住的地方是无法地带吗？刚刚来自阿克塞尔的那群人也说了一样的话。」</p><p>「别这么失礼好吗？我们还是会取缔犯罪啦。之前有冒险者破坏城墙，还爆破了领主的宅邸，都有确实将其逮捕。」</p><p>「冒、冒险者！……那是魔王军才会做的事吧？」</p><p>惊慌失措的检察官又看了几次小铃，但小铃却依旧沉默。</p><p>我说的是事实，铃当然不会响。</p><p>「阿克塞尔的冒险者到底……唔、嗯～～原本想侦讯其他问题，但这个魔道具好像坏了。算了。你叫达斯特是吧？由于你这次罪刑不重，就将你移送到一般牢房吧。」</p><p>「那当然。我实在想不透自己为什么会被逮捕！」</p><p>「太好了，达斯特先生。对了，请问我要在这里待到什么时候呢？我应该也是因为某些误会才会被带过来，想跟我道歉的话就趁现在。既然要承认自己的过失，能不能请你踩着我的脸，用傲娇的语气向我道歉呢？」</p><p>杰斯塔整个人趴在地面上，抬头看着检察官提出如此要求。</p><p>检察官连忙压紧裙摆往后退。</p><p>「是、是宰相拉格克莱夫大人命令我们不能释放你的！我不太清楚详细的情况，但你到底犯了什么罪啊？」</p><p>「这个嘛……」</p><p>「你无权过问。」</p><p>杰斯塔骄傲地挺起胸膛，正准备侃侃而谈时，一名匠气非凡的男子出声打断了他。</p><p>是在我们聊得正起劲时出现的吗？</p><p>「拉格克莱夫大人！」</p><p>检察官立刻挺直背嵴，退到铁栏杆边。</p><p>这家伙就是传说中的宰相啊。根据我在赌场听到的传言，这个国家的王子很蠢，宰相则是个行事犀利的人才。因此主导国政的人并非王子，而是宰相拉格克莱夫。</p><p>这么厉害的男人居然会出现在此，杰斯塔到底干了什么好事？</p><p>「我要跟他谈点事情，你可以退下了。」</p><p>「遵命！告辞！」</p><p>检察官迅速地敬完礼就回去了。</p><p>确认信道尽头的大门关上后，拉格克莱夫转而看向杰斯塔。</p><p>「我看了报告，你是阿克西斯教的最高领导大祭司吧？偏偏是阿克西斯教徒啊……唉。」</p><p>他打从心底感到厌烦地叹了口气。我完全能理解他的心情。</p><p>跟阿克西斯教扯上关系准没好事。</p><p>「我们在视察赌场时见过面，你还记得吧？」</p><p>「那当然。我像平常一样在传教时，你提出无理的要求，要我停止这种恼人行径嘛。」</p><p>「我只是说了『不要在赌场内传教』这个一般常识而已吧……也罢。当时你对我说了什么呢？可别说你忘了喔。」</p><p>他们完全无视我的存在，自顾自地继续说着。但我也很在意后续发展，还是先闭上嘴吧。</p><p>「哦，我说了什么让你不爽的话吗？我记得只是建议埃尔罗得把国教改成阿克西斯教。」</p><p>「就算天地逆转也不可能发生那种事。不过你真的不记得在那之后还说了些什么吗？你把我臭骂一顿呢。」</p><p>只因为被别人讲坏话，就怀恨在心吗？</p><p>哇——这些贵族怎么一个个心眼都这么小啊？虽说是贵族，但达克妮丝要另当别论。如果对她臭骂一顿，只能算是褒奖而已。</p><p>「啊～～那个啊。我逼问了『你把赌场赢来的钱上贡给魔王军，跟他们结党成派了』还有『其实你是魔王军的一员吧』这些问题吧。」</p><p>「你似乎想起来了。我本来想当成阿克西斯教徒的谵言当场带过，但就算再没用，你好歹也是阿克西斯教的领袖，我应该好好称赞你才是。你居然能发现我的真实身分。」</p><p>……他好像说了些奇怪的话。「我的真实身分」？</p><p>这位忽然现身的拉格克莱夫宰相，到底在说什么啊？</p><p>「真实身分？……我只是因为在赌场输钱很火大，才把责任归咎在魔王军身上而已。不过挺有趣的，我就顺势接话吧。」</p><p>这位破戒祭司刚刚说了些什么？</p><p>虽然拉格克莱夫没听见杰斯塔的低语，但我可是听得一清二楚。</p><p>「承蒙您的赞美。看来我等的教义并没有错。阿克西斯教中存在着一条崇高的教义——可以将所有霉运和不幸都转嫁在魔王身上。」</p><p>「就是你们这样乱搞，世上才会广传魔王陛下的各种流言蜚语！魔王陛下才不是那种人！」</p><p>拉格克莱夫说出了超级偏袒魔王的言论。</p><p>这样就等于承认自己跟魔王军有关系了吧。</p><p>我根据刚刚那番意味深长的发言深思了一会儿……难不成这个宰相——</p><p>等一下，我心中充满了不祥的预感。如果我猜得没错，要是听到后续的对话是不是不太妙啊！</p><p>「哎呀哎呀，宰相大人说出这种话没问题吗？简直就像你真的是魔王军的一员似的。」</p><p>到方才为止，杰斯塔还面带沉稳笑容，此刻他的眼里却毫无笑意。</p><p>「虽然有些误解，但阿克西斯教徒果然是个棘手的存在。好，我就把真相告诉你吧。反正你这辈子都离不开这座牢房了，我又何必隐瞒。我……」</p><p>喂，等等！不要继续说下去！</p><p>「……我就是魔王军谍报部队队长，幻形妖拉格克莱夫！」</p><p>我急忙捂住耳朵，但来不及了！</p><p>他居然爆出了这么惊人的内幕。可恶，我又不想知道！</p><p>「我的眼光果然没有失准！方才那些行为，只是要从你口中引出这句话的演技罢了！我早就嗅到你身上有些许魔族的味道！」</p><p>虽然用耍帅的姿势指着对方这么说，但这是天大的谎言！你的眼光完全失准了嘛！</p><p>看他对自己的言行举止一脸沉醉的样子，就能一目了然。他只是想讲这句台词而已。</p><p>「真有你的，阿克西斯教大祭司。你的聪明才智似乎为你带来了不幸。但我不会立刻对你处刑，因为我还有其他要事得办。在我解决那边的状况之前，我会继续让你苟活于世。」</p><p>拉格克莱夫这么说完，便转身背对杰斯塔。</p><p>他转身之后，我就在他的正前方了……我们当然会对到眼。</p><p>拉格克莱夫惊讶地瞪大双眼。我露出谄媚的笑容，并对他挥挥手。</p><p>「糟了，居然还有其他囚犯在……这样啊，你的运气真差。既然你听到刚刚那些话，就不能留你活路了。」</p><p>听到这句可想而知的发言，我的谄媚笑容变成了苦笑。</p><p>杰斯塔扬起优柔的笑容看着我。</p><p>「别在意。」</p><p>说了这句话。</p><p>「开什么玩笑！不要因为你一时大意就把我卷进来！这跟我没关系，放我出去！」</p><p>「……那个，就是……抱歉，让你发现了我的真面目……永别了！」</p><p>拉格克莱夫立刻转身离开现场。</p><p>「别想逃，喂！我不需要男版的冒失鬼！给我回来——！」</p><p>我的吼叫声被勐烈关上的铁门声压了过去。</p><p>真的假的。擅自说了一大堆我不想听的话题，还蛮不讲理地把我卷进去了。喂喂喂。</p><p>「没想到顺着他的话题走，能挖掘到这个秘密。这也是绝不容许恶魔和不死族的阿库娅大人的指引吧。」</p><p>「对我来说祂只是个瘟神！怎么办……这个国家的宰相居然是魔王军的一员。」</p><p>虽然我不想知道这件事，却还是知情了。这是无可颠覆的事实。</p><p>我勐烈地搔搔头。为了让自己冷静，我做了个深呼吸。</p><p>「吸～～～～吐～～～～就算慌张也无济于事。」</p><p>镇静下来后，最先浮现于我脑海中的念头，就是和真他们平安与否。</p><p>王女爱丽丝的未婚夫所治理的国家，掌权者宰相居然是魔王军的手下。这已经不是糟糕二字足以形容的了。</p><p>那家伙刚刚说的「别件要事」，肯定就是指王女爱丽丝吧。</p><p>我的情势虽然不妙，但和真他们也岌岌可危。我想做点什么，但该怎么做才好？</p><p>「你似乎为烦恼所困呢。跟我谈谈吧？我已经习惯听人忏悔和自白了。」</p><p>「是谁害我为烦恼所困啊！你才该去忏悔！」</p><p>杰斯塔在铁栏杆后头，用闪闪发亮的眼眸看着我。</p><p>他看起来有点开心，是我的错觉吗？</p><p>「虽然你一副事不关己的样子，但你知道自己的处境比我还糟糕吗？再这样下去，你一定会被杀掉。」</p><p>「我被杀掉的话，阿克西斯教的传教活动就会停滞不前了。我都还没玩够呢，得想想办法才行。我也不可能放过魔族。这样的话……我们只剩下一个手段了。没错，就是逃狱！」</p><p>「别说傻话……不，确实只剩这个方法了。如果把拉格克莱夫跟魔王军有关这件事爆出来，就算逃狱也不会被定罪。值得赌赌看。」</p><p>既然还有闲工夫烦恼，就应该赶紧采取行动。于是我们在各自的牢房里展开地毯式搜索。</p><p>牢房内没有窗户，只有厕所。铁栏杆虽然有些锈蚀，却十分牢固。</p><p>我抓着铁栏杆又推又拉，却还是纹风不动。</p><p>「这种时候，就该在铁栏杆淋上汗水、血液或尿液让它生锈。其实我比较希望由女性来做，但你比较喜欢汗水还是尿液？」</p><p>「不管哪一种都超浪费时间啦！而且不要偷偷在话题里参杂你的性癖！我们没有时间了。不早点通知和真他们的话，真的会闹出人命。」</p><p>「你刚刚说到和真大人他们？」</p><p>杰斯塔一脸严肃地压在铁栏杆上，紧盯着我看。</p><p>刚刚那副悠哉悠哉的表情消失无踪。</p><p>「哦，对啊。你认识我的麻吉和真吗？」</p><p>「只知道他的名字而已。更重要的是，和真大人现在和谁在一起？」</p><p>「依丽丝还有平常那群人吧。爆裂女孩、超级被虐狂十字骑士，还有宴会祭司。」</p><p>「原来……如此。既然这起事件和阿库娅大人有关，我也该拿出真本事了。」</p><p>杰斯塔露出不适合他的严肃神情，环起双臂低喃了几句。</p><p>我搞不懂他在想什么，还是别抱太大的期待好了。</p><p>我认真地四处敲墙壁，寻找是否有脆弱之处，但这个工作实在太无聊，我马上就腻了。我向趴在地面上不知道在干嘛的杰斯塔搭话，顺便打发时间。</p><p>「你为什么会来埃尔罗得？是来宣扬阿克西斯教吗？」</p><p>「那只是顺便而已。我们阿克西斯教徒会暗中秘密地看热闹……观察……保护某位大人。听说那位大人即将前往埃尔罗得，我得到情报后，心想可以巧立名目地在赌场玩个痛快，所以自愿接下这个差事。」</p><p>「这话由我来说不太适合，但你还真是忠于欲望耶……」</p><p>「这就是阿克西斯教。」</p><p>杰斯塔堂而皇之地说了这句话。看着他的身影，我好像稍微被阿克西斯教吸引了。</p><p>不过，受到阿克西斯教徒秘密保护的对象究竟是谁呢？居然能让史无前例的那帮人担心，我看不是超级怪咖，就是个令人遗憾无语的家伙吧。</p><p>随后，我们默默地调查墙壁和地板，却没找到任何能帮助逃狱的线索。</p><h3 id="_2-2" tabindex="-1"><a class="header-anchor" href="#_2-2"><span>2</span></a></h3><p>自然的光线完全照不进这间牢房，因此不知道具体时间。约莫过了几个小时后，有人送食物来了。</p><p>拿着食物的狱守是个面无表情，宛如人偶般的男子。</p><p>「我说你啊，能不能帮我逃出这里？你知道吗？那个宰相好像是魔王军的一员呢。追随那种人，你也会被当成魔王军的手下，受到刑罚喔。」</p><p>一般人听到我说的话，应该会有点动摇，但他却毫无反应。看也不看我一眼，只是默默地放下食物。不管我说什么，他都不当一回事，完全不理我。</p><p>「我知道了。你那严谨的行事态度真让人佩服。如果你听从我的要求，我就介绍一间店给你。店里的漂亮大姊姊会实现你所许下的极品美梦……喂，你要去哪里！听我说完啊！」</p><p>我大吼大叫地想留住狱守，他却头也不回地离开了。</p><p>「没用的，达斯特先生。那个人也是魔族之一。这座监狱可能已经布署了拉格克莱夫的手下。别说这些了，关于刚刚那个能实现极品美梦的话题，你能不能再说清楚一点！」</p><p>「你干嘛这么起劲啊！」</p><p>「世上居然有那种让男人美梦成真的店吗！至于我所期望的美梦，就是恶魔以外的各种女性将我团团包围，带着藐视的眼神痛骂我，用讨好的上扬视线跟我撒娇，或是缠着我请求原谅。这种后宫般的美梦也可以实现吗！」</p><p>杰斯塔抓着铁栏杆疯狂地摇个不停。他的口水甚至喷到我这里来了。</p><p>「不要这么兴奋！刚刚那件事——」</p><p>再怎么说，都不能把梦魔店的事情告诉祭司吧。</p><p>「当然是我在故弄玄虚啊。如果真有这种店，我也想请人帮忙介绍一下。」</p><p>「这样啊……说得……也是……」</p><p>他垂下双肩，心情完全跌入谷底。</p><p>「哎，干着急也没用。他似乎没有要饿死我们的意思，还是先吃饭吧。」</p><p>没想到送来的餐食还挺像样的，于是我准备开动。但将食物放入嘴里之前，我忽然打消了念头。</p><p>「应该不会下毒了吧？」</p><p>「就算食物有毒，我也有能力解毒。尽管放心吧。」</p><p>「啊，这样啊。祭司还真是方便。喂！你可不能在解毒之前拼命狂吃耶！如果你也倒了，谁来解毒啊！」</p><p>杰斯塔的脸颊膨得像松鼠似的。他似乎没想到这一点，还拍了拍手表示佩服。</p><p>「就叫你别吃了！」</p><p>「那可真是失礼了。但我的身体并无异状，应该没问题。对了，我从刚刚就一直很在意，达斯特先生跟我的餐食是否不太一样呢？总觉得你的菜色比较多。」</p><p>听他这么一说，我才终于发现这一点。我的餐食确实比杰斯塔的多了两道菜，甚至还附有甜点，数量和品质都好上许多。</p><p>「拉格克莱夫那家伙，因为一时大意就把我卷进这件事，所以想跟我赔罪是吧……」</p><p>「达斯特先生，其实我有个小秘密。我得了一种罕见疾病，只要没把肚子吃到撑就会死亡。还有，如果饭后没吃到甜点，身上就会冒出肿瘤。」</p><p>「这样啊，真是凄惨。哦，还满好吃的嘛。」</p><p>杰斯塔含着手指直盯着我看。我没理他，把食物一扫而空。</p><p>他那张羡慕不已的脸，却微微地泛起了红晕……我还是装作没看见吧。</p><p>吃完饭后，我便躺上肮脏的地板，望着上方的天花板。</p><p>「肚子也填饱了，明天再来想吧……」</p><p>现在最重要的是养精蓄锐。我对自己抛出这个借口后，就沉沉睡去了。</p><h3 id="_3-2" tabindex="-1"><a class="header-anchor" href="#_3-2"><span>3</span></a></h3><p>在那之后又过了好几天。</p><p>「我已经不想再数天花板上的污渍了……」</p><p>「是啊。自从那天以来就毫无变化。这里充斥着魔族的臭味，我的嗅觉都麻痹了。」</p><p>起初我还试着在牢房内四处调查，心想总会有办法，却连半点逃狱的头绪也没找到，真是呕死了。</p><p>现在的我只能干劲全无地在冰冷地板上磙来磙去，寻找哪个地方躺起来比较舒服。</p><p>「你是大祭司吧。随便轰一发魔法让我逃狱啊。」</p><p>「如果能使出这么方便的魔法，我就会更加大胆地肆意使用了。」</p><p>「咦？你这样……难道还算压抑吗？喂，不会吧……？」</p><p>我在牢房里就只能跟杰斯塔聊天，所以偶尔会跟他聊聊，但他常常讲出连我都吓得退避三舍的奇闻轶事。如果是不堪入耳的话题，中途我就会让大半的内容左耳进右耳出。</p><p>杰斯塔现在也活得十分自由奔放，但他居然还没发挥全力啊……</p><p>「这间牢房似乎被施以特殊魔法，所以我完全无法使用祭司的魔法。」</p><p>毕竟是魔族，自然会想办法对付祭司。</p><p>「那就没辙了……我本来想听听就算了，但是等等，你之前不是说就算食物有毒，还能用魔法解毒吗？」</p><p>「哈！哈！哈！幸好没有下毒呢。」</p><p>杰斯塔马上顾左右而言他。再也不能相信这个人了。</p><p>不能使用魔法的杰斯塔只是个废物。这样我就只能自食其力了。</p><p>「完全束手无策啊。如果这时候有人飒爽现身营救，我就会送上热情的感谢之吻。」</p><p>「我才不要。」</p><p>「不要用女生的声音讲话，很恶心耶。」</p><p>「我这么恶心真是不好意思。那我要直接回家了。」</p><p>刚刚那个声音……该不会！</p><p>我弹起身子循声回头望去，发现笑容满面的萝莉梦魔站在铁栏杆外。</p><p>「什么，你——」</p><p>「哦哦哦哦，这个地狱居然有女神降临！达斯特先生，如果你认识这位小萝莉，请务必跟我介绍一下！」</p><p>把脸凑近铁栏杆的杰斯塔，把萝莉梦魔吓死了。</p><p>那张异常亢奋的表情，任谁看了都不敢恭维。</p><p>「冷静点。」</p><p>「外表看似清纯，内在却隐藏了无与伦比的性感。我能清楚感受到这股气息！来吧，让我沉眠于你的性感温柔乡，对我吐露出你的所有欲望！我敢发誓，无论再怎么特殊的性癖，我都会欣然接受！」</p><p>「咦咦咦？达斯特先生，这个人是怎样！」</p><p>萝莉梦魔紧紧抓着我这间牢房的铁栏杆，亟欲跟疯狂摇晃铁栏杆的杰斯塔保持距离。</p><p>「别担心。他不是坏人，但也不是什么善类，只是个变态而已。」</p><p>「除了担心还是担心好吗！那个，不好意思，请问你到底是何方神圣？」</p><p>「抱歉，失礼了。信徒数量稳坐世界之冠，信奉受到万人拥戴的女神——我就是在全世界如此吹嘘的阿克西斯教大祭司，名为杰斯塔。美丽的小姐，往后请多多指教。」</p><p>虽然介绍词有点诡异，但他却面带微笑，回得彬彬有礼。如果不知道他的本性，他看起来就是个模范祭司。</p><p>听完他的自我介绍后，萝莉梦魔的脸色瞬间变得铁青。</p><p>「阿克西斯教的大祭司！」</p><p>「何须如此惊恐呢？对人对己都十分亲切的阿克西斯教徒，对同志来说人畜无害呢。」</p><p>对同志以外的人来说，只是棘手又扰民的存在而已。</p><p>血色尽失的萝莉梦魔蹲坐在地，并朝着我挥挥手，于是我凑近铁栏杆。</p><p>「达斯特先生，绝对不能公开我的真实身分喔！」</p><p>「为什么？」</p><p>「我之前不是说过了吗？阿克西斯教对恶魔和不死族绝不会手下留情！」</p><p>对喔，上次去阿尔坎雷堤亚的时候，她确实有说过。</p><p>我记得那里的阿克西斯教徒也嚷嚷着「打倒恶魔」之类的话。</p><p>「虽然整件事被杰斯塔搞得一团乱，不过萝莉梦……萝莉莎，你怎么会出现在这里？」</p><p>「我是来救你的。好好感谢我吧。」</p><p>「这其实算是令人动容的场面，但刚刚那段废到不行的对话害我没办法提起兴致……」</p><p>「说得也是……」</p><p>我们费了好大一番功夫，才双双露出苦笑。</p><p>但还是很感谢她来救我。</p><p>「不过你怎么潜进来的？而且你居然知道我在这里。」</p><p>这里似乎是极机密的牢房，要查出具体位置也是难如登天。</p><p>老实说，我不认为萝莉梦魔具备这种谍报能力。</p><p>「这要感谢巴尼尔大人。之前占卜时，他似乎看到达斯特先生未来会遭遇到这种事，便提前告诉我。所以我一直偷偷在观察达斯特先生。毕竟我是梦魔，夜视能力很强嘛。」</p><p>「真不愧是老大！只能跟他一辈子了！」</p><p>「这次巴尼尔老大会提供意见，似乎是想报答你，让他能将库存的魔道具卖给那个人类女子。」</p><p>是指上次我反过来恶整敲诈泰勒的那个新手冒险者吧。</p><p>巴尼尔老大明明是恶魔，却比那群人还要讲义气。</p><p>「你来救我，我是很高兴啦，但你身上有钥匙吗？」</p><p>「有啊，我有带。」</p><p>萝莉梦魔锵啷锵啷地拿出一串钥匙。</p><p>接着用钥匙打开了我的牢房门锁。</p><p>「嗯～～终于脱离牢狱生活，真是得救了。」</p><p>「这是巴尼尔大人的命令。达斯特先生，你可以帮那个阿克西斯教徒开锁吗？我不太想靠近他。」</p><p>她把那串钥匙交给我，于是我打开了杰斯塔的牢房门锁。</p><p>萝莉梦魔确实很害怕阿克西斯教徒，但她好像更不会应付杰斯塔这个人。要她相信那种举止猥琐的大叔，应该不可能吧。</p><p>「非常感谢你的帮助，但你是怎么进来这座监狱的？」</p><p>「那个，呃，达斯特先生的朋友帮了一点忙，告诉我通往监狱的捷径。因为只有身型娇小的人才能通过，所以就让我过来了。不过，两位的体型应该没办法使用那个捷径。」</p><p>萝莉梦魔说得语无伦次。</p><p>她说谎的功力还是一样差，但杰斯塔似乎没察觉异状。</p><p>「一直跟男人待在牢房里，就觉得女性的存在特别耀眼呢。怎么样，我们教团还有萝莉名额，要不要以教团招牌女教徒的身分入教呢？」</p><p>「呃，那个，我考虑一下……」</p><p>「你要考虑到何时呢？我们教团擅长察言观色，会将模棱两可的回答视为肯定。来，签下这份入教申请书吧！唔，入教申请书都被没收了，那就改签在我的内裤上吧。」</p><p>「咿咿咿咿！」</p><p>「你只是想露出内裤而已吧！她快吓死了，快点住手。」</p><p>要是梦魔加入阿克西斯教，那可真是前所未有的事迹。</p><p>萝莉梦魔非常惧怕杰斯塔，哀求我出手帮忙。于是我抓住她的肩膀，把她拉离杰斯塔身边。</p><p>「等逃狱之后再说吧。接下来才是问题所在。既然我们不能使用捷径，之后就只能用正攻法逃狱了。这座监狱应该布署了拉格克莱夫的魔族手下。」</p><p>「那个，我刚刚看了一下监狱出入口，那里有几十个看似士兵的人来来去去的喔。」</p><p>「唔，这样可能有点麻烦。」</p><p>杰斯塔虽然摆出双手环胸深思的姿势，他的眼神却一刻也没有离开过萝莉梦魔。</p><p>我将萝莉梦魔往身边拉近，和杰斯塔保持距离。</p><p>「对了，你是怎么潜进来的？抄捷径也是骗人的吧？」</p><p>「啊，你发现啦？其实我是用很简单的方式混进来的。你想想，我是梦魔对吧。我在士兵们面前现出真面目，说是接获拉格克莱夫大人的命令，过来让你们作春梦，他们就直接放我进来了。」</p><p>这样啊。同为魔族，就不必担心被怀疑了。</p><p>他们应该没想到萝莉梦魔是我们的伙伴吧。</p><p>「其实我原本想把达斯特先生的剑也带过来，但再怎么说也不能携带武器进来。」</p><p>「是吗？那也没办法。」</p><p>那个武器在不在身边，确实让我缺乏平时的安心感，但没被夺走就是万幸了。幸好没把那把剑带去赌场。</p><p>「那个，我之前一直很在意，达斯特先生很重视那把剑吧？你明明这么不修边幅，却唯独对那把剑细心呵护。」</p><p>「那是因为……战士可是将性命托付于武器之上，当然要好好重视。」</p><p>她好像不能接受我的说法，眯起眼直盯着我看。</p><p>我还以为这小鬼没什么想法，没想到观察还挺入微的。</p><p>「别说这些了，接下来到底该如何是好？只能先让你出去替我们把风，或是支开警卫的注意力，再趁隙逃出去了……」</p><p>「是啊。因为警卫的数量非常多，我觉得用正攻法击败敌人的逃狱方式不可行。」</p><p>「武器也放在旅店里。赤手空拳实在没办法有什么作为。」</p><p>正当我和萝莉梦魔陷入苦恼之际，从刚刚就一直有喀锵喀锵的声音从后头传来。我心想是不是杰斯塔在搞什么花样，于是转头一看，只见他打开信道尽头的铁门，擅自往前走去。</p><p>「等、等、等一下！我刚刚不是说有警卫吗！把我的话听进去好不好！」</p><p>「我知道，但这里的士兵都是恶魔吧。那就没问题了。」</p><p>「你在说什么？问题一大堆吧。对手是人类也就算了……小心后面！」</p><p>我们只顾着谈话，结果有个头上长角的恶魔发现了我们。他举起剑就从杰斯塔身后冲了过来。</p><p>杰斯塔回头一看，并将手高举——</p><p>「『Sacred Highness Exorcism』！」</p><p>他施放出魔法，被击中的走廊上便浮现出魔法阵，紧接着有道闪耀夺目的白色光柱直冲天花板。</p><p>「叽呀啊啊啊啊！」</p><p>被圣光包覆的恶魔一击就被消灭了。</p><p>原来杰斯塔不是只出一张嘴的变态啊……</p><p>萝莉梦魔在后面紧抓着我的衣服。看她吓得魂飞魄散的表情，就知道这个魔法的威力有多惊人了。</p><p>「阿克西斯教团中，没有等级比我更高的大祭司。既然能使用魔法，对手又是恶魔和不死族，那就万无一失了。」</p><p>杰斯塔挺起胸膛这么说道。打从见面以来，我第一次觉得他可靠。</p><p>杰斯塔将掉在地上的剑捡起来递给我。</p><p>「比起剑，你其实更擅长使用其他武器吧。先用这个将就一下。」</p><p>这家伙……明明没看过我战斗的样子，但光从举止和动作，就看出我擅使的武器了吗？</p><p>魔法的威力还这么强，这男人实在不好对付。</p><p>「既然有能力高强的祭司在，那就另当别论了。前面就交给你吧。萝莉莎，那边太危险了，你跟上来的时候离远一点，不要靠近喔。」</p><p>「是啊。光是有小萝莉替我加油，我就勇气百倍了。如果能叫我大哥哥、父亲大人，或是把拔的话，我的魔法威力会倍增喔。」</p><p>「咦？我不要。」</p><p>明明吓得半死，还能马上拒绝啊。</p><h3 id="_4-2" tabindex="-1"><a class="header-anchor" href="#_4-2"><span>4</span></a></h3><p>接下来就是杰斯塔一支独秀的时间。</p><p>这座监狱里只有恶魔和不死族，所以祭司的魔法成效立见，对方根本无以匹敌。</p><p>我负责将敌人引过来，再由杰斯塔施放魔法攻击。因为魔法只对恶魔和不死族有效，对我毫无影响，因此可以毫无顾忌地卷入战局疯狂攻击。</p><p>「魔法对达斯特先生无效啊。你的心灵那么污秽，我还担心你会被净化呢。」</p><p>「这不是废话吗！真要说的话，如果必须维持清心寡欲，那杰斯塔使出魔法的瞬间就会自我引爆了吧。」</p><p>「说得也是……他会被自己的力量净化吧。」</p><p>萝莉梦魔打从心底认同我的说词，并用冰冷的眼神，看着喜孜孜地追着女恶魔跑的杰斯塔。</p><p>「啊啊，我感受到冻入骨髓的藐视眼神了！」</p><p>杰斯塔非但不觉沮丧，还兴奋起来。</p><p>简直就像达克妮丝那副被虐狂的鬼样子，但杰斯塔可不只如此。他好像喜欢被痛骂一顿。</p><p>「你看看，不赶紧逃命的话，会被魔法击中喔！」</p><p>「为什么我的身体毫发无伤，却只有衣服被剥得这么干净啊！」</p>`,515),e(f,{src:`/images/E4/04.avif`,alt:`插图`,width:`850`,height:`1257`}),s[13]||=a(`<p>「这是我平时的锻鍊所赐！为了能精准消灭沾染恶魔精华的衣服，我可是下足了苦心啊。这份努力总算有了回报，才能造就此刻的光景！人类就是经过努力不断成长的生物。」</p><p>「别用精华这两个字！努力不懈的变态好恶心啊啊啊啊啊！」</p><p>语带哽咽，四处逃窜的女恶魔，身上的衣服变得残破不堪，呈现半裸状态。杰斯塔还追在她后面跑。</p><p>……如果在地表之上做出这种事，绝对会被警察好好关照一番。</p><p>「绝对不能曝光，绝对不能曝光，否则不知道会被折磨成什么样子……」</p><p>看到眼前的画面，萝莉梦魔吓得六神无主，不停地咕哝着同一句话。还是先把她护在我身后好了。</p><p>杰斯塔已经失控冲到我们前面去了，就别管他了。</p><p>结果他玩弄女恶魔玩过头，让她逃走了。取而代之出现一大堆骷髅。</p><p>骷髅手持各种武器，要是直接应战，会非常棘手。</p><p>「哼，身材毫无曲线，也不会出声，真是无聊透顶。看我一口气送你们上西天。『Turn Undead』！」</p><p>骷髅被杰斯塔的魔法全数弭平了。</p><p>「这下就轻松了。虽然你的个性很怪，但真希望队伍里也有一个祭司啊。」</p><p>「要不要我从阿克西斯教团派一位过来？」</p><p>「那就免了！我想要的是正常的祭司。到目前为止，我碰过的阿克西斯教徒都不是什么好东西！」</p><p>和真小队的宴会祭司，以及在这个城镇再次碰见的女祭司都很不正常。而且教团的领导人还是这副鬼样子。</p><p>「我还觉得达斯特先生跟阿克西斯教很合得来呢，真是遗憾。」</p><p>「怎么可能。」</p><p>「两位有很多共通点啊。或许就是因为太相似，才觉得很棘手吧。这就叫同类相斥。」</p><p>「别把我跟他混为一谈！」</p><p>萝莉梦魔居然语出惊人。</p><p>我是不会坚称自己是个严谨的老实人，但也没有像阿克西斯教徒这么离谱吧。</p><p>「如果你对阿克西斯教有兴趣，随时都可以找我洽询。我们的大门永远为你敞开……哎呀，这下麻烦了。」</p><p>嘴上说着麻烦，他的脸上却扬起了笑意。</p><p>我想说应该不是什么大事吧，于是循着杰斯塔的视线看去，结果看到一块诡异的岩石。</p><p>巨大的岩石连接着较小的石头。整体看来是个由巨石制成的扭曲人偶。</p><p>「哇啊，感觉又大又硬……」</p><p>「是魔像啊。」</p><p>「如果对方是恶魔或不死族，倒是不成问题，但祭司不太会应付魔像。这里能不能交给你处理呢？」</p><p>杰斯塔退到我身后。</p><p>没办法，看来轮到我出场了。</p><p>「好，你们就在后面好好欣赏我的英姿吧！」</p><p>魔像的身形虽然比我大三倍以上，动作却十分迟缓。</p><p>我打算以俐落的身手玩弄它一番，破坏它的关节。</p><p>「咕喔喔喔喔！」</p><p>魔像缓缓地举起手臂。</p><p>它的动作也很大，浑身都是破绽。只要避开这个攻击，冲进它的怀里，就能轻松解决。</p><p>我不慌不忙地躲开挥落而下的巨石之拳——</p><p>才刚听到风的呼啸声，魔像的手臂就以异常的速度伸了出去。只见巨石之拳急速逼近后方的萝莉梦魔眼前。</p><p>我立刻扑向萝莉梦魔。</p><p>「你、你要在这里对我毛手毛脚吗！」</p><p>「最好是啦！」</p><p>我抱着萝莉梦魔千钧一发地避开攻击，跌落在地。</p><p>「呀啊啊啊啊啊啊！」</p><p>「耳朵跟手臂好痛啊啊啊！该死，擦伤了。」</p><p>受到撕裂伤的上手臂鲜血直流。本来想躲避攻击，结果魔像的力量大得离谱，伤势也比预想中还要严重。</p><p>「是、是为了保护我……你没事吧！」</p><p>「只是擦伤而已，没什么好担心的！」</p><p>萝莉梦魔发出凄惨的叫声，我将没受伤的那只手举起来，表示没有问题。</p><p>虽然如此逞强，但伤势有点严重。出血量也不小，会对行动造成阻碍。</p><p>「『Heal』！感觉怎么样？」</p><p>我的手臂在温暖光芒的包覆之下，伤口瞬间愈合了。</p><p>「哦，杰斯塔，真有你的！」</p><p>居然能轻易治愈这道伤口。光论能力，他果然十分优秀。</p><p>如果有杰斯塔在后方待命，那我受一点小伤也无所谓。就强行拉近双方的距离吧。</p><p>我避开连续击来的拳头，来到剑可及的范围内后扑向魔像，并往它的足关节撞去。</p><p>「唔喔！太硬了吧！连关节都硬梆梆的。身手还这么俐落，看来这个魔像经过特殊强化了。」</p><p>如果是一般的魔像，刚刚那一击就能破坏它的关节，让它因为自身重量而崩毁。</p><p>「达斯特先生，要打倒魔像，似乎只要削去头部的文字就好了！」</p><p>「我知道啊，但我构不到嘛！」</p><p>根本用不着萝莉梦魔提醒，我也知道魔像的弱点在哪里。</p><p>魔像头上刻有魔法咒文。只要削去部分文字，就能将其破坏，而这也是最基本的攻击方式。但是魔像也会动，要削去头上的文字太麻烦了，所以大部分的冒险者都会用蛮力破坏。</p><p>这家伙的块头那么大，我用这把剑再怎么挥，都碰不到它的头部。</p><p>「达斯特先生，请用这个吧！」</p><p>我听到杰斯塔的呼唤后转头一看，眼前就出现一支闪闪发光的枪尖。</p><p>「唔喔喔喔喔！好、好危险。差点就要刺到我的脸了！转成反方向再丢过来啦！」</p><p>「抱歉，我丢得太用力了。但你用那个武器就能打倒魔像了吧？」</p><p>我在千钧一发之际抓住的是一把长枪。是刚刚那些骷髅手持的武器之一。</p><p>杰斯塔果然看出我擅长的武器了。</p><p>虽然不想让别人看见我使枪的样子，但在变态祭司和梦魔面前应该不成问题……如果被那位大人发现，我应该会被骂得很惨吧。</p><p>「达、达斯特先生，小心后面！」</p><p>用不着听萝莉梦魔的叫唤。</p><p>我将长枪尾端抵上地面，以长枪为轴心高高飞向空中。</p><p>我看着从脚底划过的岩石之拳，在空中调整姿势，和魔像面对面。此时视线前方就是刻在魔像头部的那串文字。</p><p>我用枪尖削去其中一个字后，魔像就立刻崩毁了。</p><p>「达斯特先生，你的表现太精彩了。」</p><p>「彼此彼此。」</p><p>我无意跟男人打成一片，但可以稍稍认同杰斯塔这个人了。</p><h3 id="_5-2" tabindex="-1"><a class="header-anchor" href="#_5-2"><span>5</span></a></h3><p>敌军似乎被我们击溃，再也没有出现了。</p><p>这座监狱应该建于地底，走道尽头有座长长的螺旋梯。我们花了很长一段时间走上去后，终于抵达地面。</p><p>「哦，已经入夜了。」</p><p>打开厚重的铁门后，外面是被高墙包围的街景。抬头一看，天空闪耀着无数星辰。</p><p>这种看似小巷弄的地方，居然隐藏了监狱的入口啊。还真是大胆。</p><p>监狱入口处有两个假扮成人类的恶魔，但杰斯塔不由分说地对他们击发魔法，因此没有危险性。</p><p>「呐，如果对方是人类怎么办？」</p><p>「唔，也有这种可能性。但是别担心，这个魔法对人类无害，只对恶魔有影响而已。」</p><p>杰斯塔这么说，并对萝莉梦魔露出了微笑。</p><p>萝莉梦魔拼命地点头称是。</p><p>……难道杰斯塔已经看出她的真实身分了吗？在知情的情况下，还以对方恐惧的模样为乐……感觉很有可能。算了，我也不知道真相如何，还是别刻意提起好了。</p><p>「嗯～～苦窑外的空气太新鲜了。」</p><p>「达斯特先生，你好适合说这句台词喔。」</p><p>「要你管。对了，你知道和真他们的状况吗？」</p><p>虽然到现在才想起这件事有点过分，但我当时实在没那个闲工夫。</p><p>既然没有来处分我和杰斯塔，就代表和真他们平安无事吧。</p><p>「和真先生他们吗？已经离开埃尔罗得，回去阿克塞尔了。」</p><p>「……咦？喂喂，真的假的。呐，琳恩他们该不会也丢下我不管，跟着回去了吧？」</p><p>我逼问胆怯不已的萝莉梦魔后，她就别开视线，用手指搔了搔脸颊。</p><p>「喂喂喂，不会吧……他们不会这么无情，抛下伙伴直接回家吧？」</p><p>「这、这个嘛……」</p><p>正当萝莉梦魔有些歉疚地准备开口时——</p><p>「刚刚的光就是这里发出来的吗！这里是拉格克莱夫秘密建造的监狱……难道是他的手下吗？不准动！」</p><p>手持武器的埃尔罗得士兵们闯了进来。</p><p>他们好像看见了杰斯塔施放魔法发出的光芒。</p><p>「是不是哪里搞错了？我们只是被关在这里而已。」</p><p>「我们？这里不是只有你一个人吗！」</p><p>「喂喂，这是什么话？你们也说句话啊。」</p><p>说完，我转头看向身后，却没看见杰斯塔和萝莉梦魔的身影。</p><p>只见杰斯塔逃往后方的小巷弄，萝莉梦魔则展翅飞向夜空。两人的背影变得越来越小。</p><p>「他们居然敢丢下我！」</p><p>「抓住他——！」</p><p>「我又要被逮捕了喔！」</p><h2 id="终章-为那位淫魔孤注一掷" tabindex="-1"><a class="header-anchor" href="#终章-为那位淫魔孤注一掷"><span>终章 为那位淫魔孤注一掷</span></a></h2><h3 id="_1-3" tabindex="-1"><a class="header-anchor" href="#_1-3"><span>1</span></a></h3><p>「我已经腻了……」</p><p>还以为逃狱成功了，结果又被关进其他牢房里。</p><p>不过这次跟拉格克莱夫无关，他们应该会好好听我解释。</p><p>对了，来到这里我才听说，拉格克莱夫好像被爱丽丝亲手消灭了。</p><p>似乎是和真做了什么好事，把拉格克莱夫逼得走投无路，正想强制引发骚动时，却反遭讨伐。</p><p>虽然事件草草收场，但也因此知道他们平安无事，还是老实地感到庆幸吧。</p><p>「这里住起来比那间牢房还要舒适，悠哉一点好了。」</p><p>既然和真他们没事，宰相也消失了，就无须担心生命安危。我就轻轻松松地待到被释放为止吧。</p><p>这里的地板躺起来比之前被关进的那间牢房还要舒服。我躺在地上耍废时，看似士兵的一群男子来到牢房前，打开了门锁。</p><p>「终于要放我出去啦？总算是还我清白了……喂，干嘛蒙住我的眼睛？还绑住我的身体！好痛好痛，不要拉我啊！这是什么玩法吗 ！」</p><p>士兵们不顾我的怒吼，推着我的背，准备把我带到某处。</p><p>虽然我试图抵抗，但在看不见前方，行动也受制的状况下，我无计可施。</p><p>被迫走了很长一段距离后，这次他们抓住我的肩膀，逼我坐下来。</p><p>捆绑身体的绳索和蒙住眼睛的布被松开后，令人眩目的强光便窜进我的双眼。</p><p>「唔喔，好刺眼！啥？为什么把我带来赌场啊？」</p><p>还以为可以出狱了，却忽然直冲赌场。简直莫名其妙。</p><p>「你是阿克塞尔的冒险者达斯特，没错吧？」</p><p>有个语气嚣张的小鬼，趾高气昂地坐在椅子上看着我。</p><p>这小鬼身穿要价不斐的服装，态度嚣张到极点。他身边还有几个武装士兵跟惹人厌的随扈。</p><p>「问别人的名字之前，要先报上自己的名字吧。没人教你吗，小少爷？」</p><p>「混帐！竟敢用这种语气对雷维王子说话！」</p><p>此时开口怒吼的人不是小鬼，而是其中一名随扈。</p><p>哦～～这小鬼是埃尔罗得的王子，也就是爱丽丝的前未婚夫啊。</p><p>是因为跟拉格克莱夫有过瓜葛，或是我跟和真和爱丽丝之间的关系曝光，他才会直接找上我吧。无论如何，我心中只有不祥的预感。</p><p>「你这位王子殿下，找本大爷有何贵干？」</p><p>「又用那种不敬的口气！」</p><p>「无妨，你退下吧。我直接跟他说。」</p><p>雷维王子瞪了一眼，随扈就退到后面去了。</p><p>「拉格克莱夫似乎给你添麻烦了，关于这点我先致上歉意。你虽然犯了罪，却没有严重到需要受牢狱之灾，这点已经获得证实了。我答应你，只要在这里跟我谈完，我就会释放你，也会将行李一并归还。」</p><p>哦，真是出乎意料的发展。</p><p>被蒙住双眼带到这里来之后，眼前居然出现了这个国家的王子。</p><p>我刚刚虽然有点虚张声势，但我领悟到此刻的处境十分危急。</p><p>我往士兵递过来的袋子里确认了一番，发现所有行李都在里面……我的剑也完好无伤。</p><p>「你很明事理嘛。那就这样吧。」</p><p>我起身准备离开现场，身后的士兵却又抓住我的肩膀，强迫我坐下来。</p><p>「话还没说完呢。除了把你关进大牢之外，还有另一个问题。我们抓到了一个女恶魔，你认识她吗？」</p><p>雷维王子这么说完，并打了个响指。被后方的士兵带到现场的，竟是萝莉梦魔。</p><p>「呃！你怎么会在这里啊？不是抛下我逃走了吗？」</p><p>「对不起～～～～！但我别无选择嘛～～～」</p><p>被士兵押着走的萝莉梦魔，泪眼汪汪地走了过来。</p>`,153),e(f,{src:`/images/E4/06.avif`,alt:`插图`,width:`850`,height:`1257`}),s[14]||=a(`<p>「而且你……为什么穿成这样？」</p><p>「不要一直盯着我看，我觉得好丢脸。」</p><p>她满脸通红地扭动着身体，真的很害羞的样子。</p><p>看着萝莉梦魔羞怯的模样，我实在想不透。</p><p>平常还光明正大地穿着近乎全裸的服装，有必要这么害羞吗？</p><p>现在这件衣服的裸露程度不高，尺寸也小了一圈，非常合身，甚至能清楚看见身形的轮廓。</p><p>「喂，那身装扮哪里丢脸？那是阿克西斯教祭司穿的衣服吧？」</p><p>「呜呜呜呜，是啊，穿上这件衣服让我觉得不舒服又丢人现眼，完全使不上力。居然让我蒙受这样的耻辱！」</p><p>虽然她用手捂住脸大喊「拜托别看我这副模样！」，但我根本不能理解她在害羞什么。</p><p>仔细观察后，发现这件衣服的尺寸合身到足以透出内裤的痕迹，有种莫名的妖艳感。但这样总比平常跟内衣没两样的打扮好多了吧。</p><p>「我可是被迫穿上恶魔天敌的祭司服装啊！换个方向思考看看吧。如果让祭司穿上梦魔的服装，也会觉得丢人现眼吧！」</p><p>「感觉有点像歪理耶？」</p><p>虽然我无法接受她的说词，但对萝莉梦魔而言，这身打扮似乎让她十分屈辱。就先装出已经理解的样子好了。</p><p>「你们果然认识啊。你知道拉格克莱夫是魔王军的一员吧。在这种情况下，自然不能将女恶魔放着不管。我在考虑要叫她去强制劳动，还是把她丢给阿克西斯教徒处理。」</p><p>「丢丢丢丢丢丢、丢给阿克西斯教徒处理！」</p><p>原本就已经泪眼汪汪的萝莉梦魔，此刻更是脸色苍白地浑身发颤。</p><p>难怪她会怕成这样。阿克西斯教徒是出了名地讨厌恶魔。跟杰斯塔聊过之后，就能深切体会到这个传言并不夸张。</p><p>「还是先等一等吧。把这家伙交给阿克西斯教徒的话，不知道她会受到何种待遇喔。」</p><p>听到我指出这一点，萝莉梦魔疯狂地不停点头，速度快到整张脸都要煳掉了。</p><p>「我知道，所以才要把她交出去，借此转移目标。你知道阿克西斯教徒正在这个国家做什么好事吗？」</p><p>雷维王子用手压着眉头，大大地叹了一口气。</p><p>「呃，不知道，我一直被关在牢房里。」</p><p>「唉～～～～那些家伙……自称阿克西斯教最高干部的杰斯塔和女祭司打头阵，带着一帮阿克西斯教徒在王城前和赌场内展开抗议行动！嚷嚷着『请对非法囚禁一事进行谢罪和赔偿！只要将国教改为阿克西斯教，我们就会撤退！』『如果看不到你们的诚意，我每天都会和大家跑去赌场搭讪女客人和女荷官！』『小萝莉跟小帅哥也是我们的狩猎目标！』每天都闹得不可开交！」</p><p>「哇啊——」</p><p>长期被关在那间牢房里，积怨已久的杰斯塔彻底失控了。</p><p>至于阿克西斯教徒的动机，应该是半是刁难，半是寻开心吧。</p><p>「为了转移目标，安抚群众，我打算把她当成祭品。」</p><p>「怎、怎、怎、怎么这样！被丢进那种地方之后，他们会对我做出什么事啊！我还没坐上店里的红牌宝座耶！啊，如果信奉阿克西斯教，就能得救了吗？可、可是，变成阿克西斯教徒的话，会被巴尼尔大人讨厌啊！」</p><p>萝莉梦魔似乎因为恐惧而乱了阵脚。明明是个恶魔，却口出惊人之语。</p><p>「他们好像还有小萝莉的空缺，恳求杰斯塔的话，应该有机会获救吧？但感觉代价是会落得比死还不如的下场……」</p><p>杰斯塔一定会乐不可支地玩弄萝莉梦魔。那家伙绝对会这么做。</p><p>「他们肯定会每天都把杂事推给我做，用餐时间会在我的杯子里倒入圣水，像个小姑似的说着『哎呀，不想喝我帮你倒的水吗？』对我百般刁难！或是将圣水混进温热的洗澡水中，对我施以水刑……！」</p><p>萝莉梦魔似乎如实想像了被阿克西斯教徒玩弄于股掌间的画面，精神濒临崩溃边缘的她，开始大翻白眼并浑身发颤。</p><p>要是置之不理，我真的会良心不安。</p><p>「不能想想办法吗？这家伙虽然是恶魔，但跟魔王军一点关系也没有。她反而是对人类有益的梦魔。你可以用那种测谎魔道具来判定真伪。」</p><p>「都说到这个份上了，应该是真的吧。不过，就算你没说谎，现在这种情势之下，我也不能轻易释放恶魔。你应该能理解吧……对了，希望我放过这个女恶魔的话，有个条件。」</p><p>条件？</p><p>刚才雷维王子的脸上瞬间闪过一抹笑意。</p><p>虽然有股不祥的预感，但我别无选择了。</p><p>「要谈条件啊。虽然很可疑，但我还是姑且听听吧。平常也算是受了你的关照，我不会丢下你不管。」</p><p>「达斯特先生……」</p><p>从昏厥状态复活的萝莉梦魔，用湿润的眼眸盯着我看。</p><p>「根据我的调查，你跟爱丽丝公主视为兄长仰慕的和真先生，关系似乎很密切。」</p><p>「对啊，他是我的麻吉。」</p><p>「那你可以将和真先生的弱点和情报全部告诉我吗？他过着什么样的生活，又做了些什么，往后也希望你能定期向我回报。尤其是跟爱丽丝公主的关系，请务必详细描述！」</p><p>「……和真的情报？」</p><p>我完全没料到会发生这种事，忍不住如此问道。</p><p>「和真先生识破拉格克莱夫的真面目，拯救了这个国家，对我有恩。但也因为他的关系……害我失去了爱丽丝公主！」</p><p>雷维王子握紧拳头大吼着。看他这副模样，我将刚刚浮现脑海的那句话脱口而出。</p><p>「难道你被爱丽丝甩了吗？明明有婚约在身耶？」</p><p>「哈呜！」</p><p>雷维王子捂着胸口双膝跪地。</p><p>「大胆刁民！竟敢对伤心欲绝的王子如此无礼！本来想主动取消婚事，才对爱丽丝公主冷言冷语，却在不知不觉中对她倾心，结果马上就被对方给甩了！请你体会一下王子的痛苦好吗！」</p><p>「王子可是从喜欢的女性口中，听到『我们要一直保持朋友关系喔』这种毫无希望的话语啊！你这混帐东西能理解王子的煎熬吗！」</p><p>随扈们对我群起围剿，但听到他们的护航后，雷维王子却瘫倒在地了。他受到的伤害比我还惨耶。</p><p>「别、别说了。再说下去我会受不了……」</p><p>雷维王子压着胸口，好不容易才站起身子。</p><p>「你没事吧？」</p><p>「不、不必担心我。呼……让我听听你的回答吧。」</p><p>这个提议还不错。只要将和真的情报告诉他，就能让萝莉梦魔获救。</p><p>可是我——</p><p>「我不会出卖我的兄弟。对方是王公贵族的话，就更不用说了。」</p><p>我可没落魄到要出卖挚友的地步。</p><p>「那你要抛弃这个女恶魔吗？」</p><p>听到王子这么说，萝莉梦魔吓得全身一震。</p><p>多凄惨的表情啊。</p><p>「怎么可能放弃。我没兴趣抢别人的东西，但很讨厌别人抢我的东西。」</p><p>我搔搔头，对王子如此放话。</p><p>「居、居然说出如此大胆的告白。可是我已经心属巴尼尔大人了。如果从朋友做起，我倒是可以考虑……」</p><p>萝莉梦魔似乎会错意了，整张脸变得红通通的。</p><p>她不停地玩弄手指，嘴里还嘟哝着什么话，但太小声了，我听不清楚。</p><p>「所以这样如何？就用符合赌博大国埃尔罗得的方式，在赌场一较高下吧。」</p><p>「哦哦，竟然说出跟和真先生相同的提案，看来你们真的是挚友呢……好，我答应你。如果你赢了，我就释放那个女恶魔。但你的赌注是什么？如果双方的赌注价值不对等，就没有意义了。」</p><p>雷维王子坏心地一笑。似乎压根不觉得自己会输。</p><p>听到我提议要一决胜负后，他的表情就变了。因为是以博弈致富的家族后裔，他才会热血沸腾吗？</p><p>「赌注啊。可以让你释放萝莉梦魔的东西……」</p><p>在我的行李中，价值足以匹敌的物品——就只有一个。</p><p>「这把剑如何？」</p><p>将爱剑放上桌面后，我清楚看见雷维王子的脸上瞬时闪过一丝惊愕。</p><p>「你知道这把剑实际上值多少钱吗？」</p><p>「听你的口气，好像已经鉴定过了嘛。我当然知道。」</p><p>我比任何人都明白这把剑的价值。正因如此，我现在才会拿出来赌。</p><p>先前他们怀疑我跟拉格克莱夫是一伙的，我就猜他们会彻底搜查我的行李。我想得果然没错。</p><p>「原来如此，这把剑确实无可挑剔。我就接下你的挑战吧。」</p><p>这把宝贵的剑是那位大人赐给我的。正因为他是王族，我就想他应该明白剑的价值。看来我猜中了。</p><p>「等、等一下！达斯特先生，你的赌技不是很差吗！明明从来没赢过，到底是哪来的自信啊！」</p><p>「都一路输到底了，下次搞不好会赢啊。」</p><p>「那是被赌博害得倾家荡产的人才会有的想法！而、而且那把剑应该很珍贵吧。不管再怎么缺钱，你也不肯放手不是吗？怎么能为了我这个恶魔……」</p><p>萝莉梦魔浑身震颤地低下头去。我将手放在她的头上说道：</p><p>「以后你还会继续让我作春梦吧？」</p><p>「达斯特先生……我超傻眼。你真的完全不懂少女心耶。这种时候请说点更加怦然心动的台词吧。我再给你一次机会，重来一遍！」</p><p>「少啰嗦。本大爷愿意出手帮忙，你就闭上嘴好好感谢我。记得把我大显身手的事迹好好说给店里的梦魔她们听喔。」</p><p>萝莉梦魔口出怨言，我像是要搔乱头发般摸摸她的头。</p><p>「达斯特先生，你还记得吗？女性喜欢被摸头这件事，只是处男的妄想喔。」</p><p>「哦，我知道啊。你之前教过我嘛。」</p><p>萝莉梦魔过去也跟我说过同样的话，我是在知情的情况下才做的。</p><p>她跟嘴上说的不一样，好像很高兴的样子，是我的错觉吗？</p><p>「行了吧？在比赛开始前，增加一些观众吧。否则周围充斥着我的声援，实在让人提不起劲。」</p><p>雷维王子一弹指，身后的门便应声打开，琳恩、泰勒和奇斯也跟着现身。</p><p>「这群人怎么在这里啊！」</p><p>「因为你失踪了，他们几个来王城和警察局问过好几次。要是他们发现你被逮捕，进而跟阿克西斯教徒结伙的话就麻烦了，所以我把他们软禁在旅店里。我不想再增加无谓的乱象了。」</p><p>所以我提到伙伴们的问题时，萝莉梦魔才会支支吾吾的啊。</p><p>我以为他们早就跟着和真一行人先回去了，根本没想到会被关在旅店里。</p><p>「喂，达斯特，这是怎么回事！那个小孩子是谁，这些士兵又是怎样啊！」</p><p>「因为你忽然失去踪影，我们到处找你，却被软禁在旅店内，最后还被带来这种地方！给我解释清楚！」</p><p>「呐，你这次又干了什么好事？而且萝莉莎怎么穿着祭司服？我要生气喽，你给我从实招来。」</p><p>伙伴们冲到我身后叽叽喳喳地念个不停，吵死了。</p><p>我随便找个理由带过萝莉梦魔的事情。至于被关进大牢的经过，我用「因为赌输闹场而被逮捕。那个小孩是名门贵族，也是依丽丝的未婚夫」这个理由简单说明之后，他们似乎接受了我的说法。</p><p>「这全都是你的错吧？一个人默默跑去赌场也是，闹场而被逮捕全是你的责任吧？为什么我们会被软禁？太奇怪了！」</p><p>「伙伴就是要互相帮忙啊。同甘共苦真是一句好话。我在牢房里，你们在旅店里。虽然场所各异，我们的心却永远相系。」</p><p>我向伙伴们露出爽朗的笑容，他们却对我拳脚相向。</p><p>「喂，住手！好痛！下手轻一点啊！」</p><p>我被众人围殴，趴倒在桌上。</p><p>这些人居然来真的……</p><p>唯一没有出手的萝莉梦魔，也只是基于立场，不知道该如何是好才犹豫不决而已。</p><p>「虽然不知道依丽丝的未婚夫为什么会在这里……呐，这家伙的死活跟我们无关，放了我们吧。」</p><p>「达斯特，你害我们无法顺利完成委托，这次我实在不能再袒护你了。看是要把这家伙拿去煮还是拿去烤，都随各位处置。」</p><p>「害我这么担心，结果却是这种下场。干脆让他坐牢一年算了。」</p><p>都没有人担心我的安危吗？</p><p>被逮捕的责任确实在我，闹场的也是我，逃狱的也是我……奇怪？难道萝莉梦魔的问题也是出在我身上吗？</p><p>「顺带一提，我之所以会出现在这里……是因为那个男人害我们家族经营的赌场蒙受损失。」</p><p>雷维王子或许是判断曝露身分并无好事，于是也顺着我的设定走。</p><p>「哎，你们别搞错了。我和这小子是以释放萝莉莎为条件才要一决胜负。你们单纯只是观众而已，跟我的输赢无关。对吧，小少爷？」</p><p>「是啊。刚刚没说清楚，如果他输了这场比赛，无法获释的只有……萝莉莎那个女孩而已。」</p><p>雷维王子观察现场气氛后，说出了萝莉梦魔的假名。</p><p>「咦？等一下。这我可没听说。怎么回事啊？请再说详细一点。」</p><p>「达斯特会怎样都无所谓，但事关萝莉莎就另当别论了。」</p><p>「对啊。达斯特根本不重要。」</p><p>「你、你们这些人……！」</p><p>这个差别待遇是怎么回事？</p><p>伙伴们完全不管我的死活，忧心忡忡地围在萝莉莎身边。</p><p>「你的人品真是差到可悲的地步……」</p><p>「别用那种眼神看我，我会害羞。」</p><p>雷维王子，别对我抛出看着可怜人的眼神嘛。</p><p>「那、那个，其实……」</p><p>萝莉梦魔不停地朝我投来求救的眼神。她的抗压性还是这么低。</p><p>我只能随便编个谎言，说服这群家伙了。</p><p>「哎，没办法，我来说明真正的理由吧，你们过来一下。小少爷，不好意思，请你稍等一下。」</p><p>我带着萝莉梦魔和伙伴们，来到房间的角落。</p><p>我压低声音，以免被周遭听见，接着将刚刚在脑中编出来的剧情脱口而出﹕</p><p>「其实有个贵族对萝莉莎一见倾心。那家伙为了将萝莉莎占为己有，说谎骗了她，还藉赌博之名强迫借钱给她。正当他想骚扰还不出借款的萝莉莎时，我偶然现身，就顺势揍了他一顿，才直接被关进牢房。」</p><p>「……你刚刚不是说，是赌输钱大闹现场才被抓的吗？」</p><p>「那是因为，萝莉莎说不出自己在赌博时跟别人借钱的事啊，对吧？」</p><p>「咦？啊，是的。我不想让大家知道这么丢脸的事，才拜托达斯特先生替我保密。」</p><p>她察觉到我的意图，跟着我一起说谎。虽然事出突然，但她的演技很优秀嘛。</p><p>「可是，与其说揍了一顿……我只不过是轻轻撞了他一下而已。至于那个贵族……就是那个小鬼。」</p><p>「「「「咦？」」」」</p><p>连萝莉梦魔都跟伙伴们一样惊呆了。你不要跟着惊慌啦。</p><p>「这件事我只说给你们听。那个小鬼是依丽丝的前未婚夫，他被依丽丝甩了。为了迁怒，他才盯上娇小又脆弱的萝莉莎。那小鬼打算强迫萝莉莎背负债务，把她当成依丽丝的替代品玩弄一番。对吧，萝莉莎？」</p><p>「就、就是啊。『你就是依丽丝的替代品！给我趴跪在地，一边舔我的鞋底，一边说「我依丽丝的未婚夫大人最棒了」。』正当他如此逼迫我时，达斯特先生出手拯救了我！」</p><p>哦！这家伙好像也玩起来了。</p><p>她非常完美地配合我的谎言造假。</p><p>「太变态了！居然看萝莉莎弱小就强逼她做那种事，同样身为女人，我绝饶不了他！」</p><p>「这个臭小鬼。我也很想试试这种玩法耶！」</p><p>「竟然逼迫女性做出这种行为，就算对方是小孩也不能原谅！」</p><p>同仇敌忾的伙伴们，狠狠瞪向趾高气昂地坐在椅子上的雷维王子。</p><p>……虽然把火气煽动得有点夸张，但幸好伙伴们的心思很单纯。</p><p>解释完毕后，我带着伙伴们和萝莉梦魔回到座位上。伙伴们都用狠毒的眼神紧盯着雷维王子看。</p><p>「呐，为什么后面那些家伙一直瞪着我？」</p><p>「好像是今天的早餐很难吃，让他们心情不太好。」</p><p>「……算了。差不多该开始赌了吧。」</p><p>「可以啊。最后再让我确认一次。只要我赢，你就要放了萝莉莎。如果我输了，萝莉莎就要沦为你的性奴隶。没问题吧？」</p><p>「喂，你在说什……」</p><p>「「「大有问题！」」」</p><p>伙伴们在我耳边怒喝一声，盖过了雷维王子惊讶的声音。</p><p>干嘛喊那么大声，害我有点头晕脑胀。</p><p>「叫什么叫啊。这里交给我，你们负责在旁边看就行了。给我闭上嘴乖乖看。」</p><p>「「「不要。」」」</p><p>只有这种时候才这么有默契。</p><p>「你的赌技很差吧！从来没看你赢过！我才不管达斯特会落得什么下场，但萝莉莎现在的处境很危险啊！」</p><p>听到琳恩这么说，其他两人也用力地点点头。</p><p>「只要有心，我也可以大有作为。就当作上了一艘安稳大船，冷静一点吧。」</p><p>「你应该是泥船吧！」</p><p>「是满目疮痍的破船吧！」</p><p>「自己游泳还比较安全！」</p><p>伙伴们把我贬得一文不值，虽然我试图说服，但没有人愿意听我解释。这要我怎么一决胜负啊？</p><p>「虽然增加了未知的条件，但是无妨。既然他们说让赌技奇差的你上阵令人不安……不如这样吧。你跟伙伴们轮流和我对局，只要其中一位获胜，我就放了那个女孩。我会给赢家一笔钱，当作赔罪的补贴费用。」</p><p>或许是不忍再看我们争吵了，雷维王子说出了非常惊人的提案。</p><p>「喂喂，你认真吗？我们有四个人耶。如果没有四连胜，你就输了喔。」</p><p>「我知道。我不觉得自己会赌输。不管用什么方法，我都不会再输了！」</p><p>雷维王子挺起胸膛如此断言。</p><p>自信满满的对手，通常都会疏忽大意，但我在他身上感受不到这样的气息。明明是个屁孩，双眸中却盈满了决心。是我的错觉吗？</p><p>我正思考着这件事，萝莉梦魔忽然来到我身边，对我耳语道：</p><p>「我在赌场里听别人说过，雷维王子跟和真先生对赌时，好像输得一塌煳涂。在那之后，他就频繁地出入赌场，在每场游戏中屡战屡胜呢。」</p><p>原来如此。我明白那家伙自信满满的理由了。</p><p>连续败给和真之后，他痛定思痛，不停地磨练自己的赌博技术。</p><p>「如何？你的伙伴无须提供这场胜负的赌注……因为你赌上的那把剑，已经具备充分的价值了。」</p><p>他用只有我听得见的声音，说出最后那句话。</p><p>原来如此，难怪他会那么爽快地开出对我们有利的条件。</p><p>事情进展得太过顺利，伙伴们反而提高了警戒，聚在一起讨论起来。</p><p>「我都已经要让步了，还需要烦恼吗？……真受不了，之前还听说冒险者很勇敢呢，原来只是虚有其名啊。连这种程度的冒险都要犹豫不决，真是胆小。」</p><p>雷维王子双手环胸地睥睨着我们。</p><p>他很懂得怎么挑衅嘛。</p><p>「哦～～就算对方是高高在上的贵族，都被说成这样了，可不能打退堂鼓呢。」</p><p>「平常我会嘱咐自己不要碰赌，但今天就先解禁吧。」</p><p>「嘿，我跟达斯特不一样，胜率可不低喔。我会让嚣张的小屁孩哭得泪眼汪汪。」</p><p>被这种小鬼开口嘲讽，他们才不会默不吭声。</p><p>于是所有伙伴们都决定接受这场赌局。既然能提升我方的胜率，我当然举双手欢迎。</p><h3 id="_2-3" tabindex="-1"><a class="header-anchor" href="#_2-3"><span>2</span></a></h3><p>「喂。」</p><p>我怒气冲冲地吼了一声。</p><p>奇斯和泰勒只穿一条内裤，低着头跪坐在我面前。</p><p>意气风发地接下挑战就算了，这两个居然马上就被迎头痛击，浑身被扒个精光。</p><p>「真是奇怪～～你们刚才不是帅气地喊出『哼！根本轮不到达斯特上场』还有什么『就由我来为一切做个了断』这些话吗？为什么现在只剩一条内裤呢？」</p><p>「哪、哪会知道连一局也没赢啊……」</p><p>「我很少赌博，所以不太擅长……」</p><p>两人都输得很彻底，一场也没赢。</p><p>他们的技术确实不强，但雷维王子这名赌徒的技巧更胜一筹。</p><p>……不对，不只是如此而已。</p><p>是雷维王子压倒性胜利。玩卡牌游戏时，总是能拿到最强王牌。玩轮盘游戏时，也能百发百中地猜中球会落在哪一格。</p><p>做得也太明显了吧。</p><p>这家伙在耍老千。可以确定他跟荷官联手，但肯定也在卡牌上动了手脚。</p><p>我猜大概是透过卡牌背面的细部花纹，或是其他手段，让他不必翻牌就能知道卡牌数字吧。</p><p>为了赢过和真，我也曾经想买过这种诈欺用的道具，所以非常清楚。</p><p>接下来没办法识破他的手段。卡牌也已经全数回收了。</p><p>如果我猜得没错，雷维王子应该会如愿赢得比赛。</p><p>……跟本大爷比赛，竟然敢耍老千，胆子还真不小！</p><p>「你们在这里好好反省……之后就交给我吧。」</p><p>「「达斯特……」」</p><p>可能是深受我这句十足可靠的台词感动，两人盯着我缓缓开口：</p><p>「世界上没有比达斯特更无法信任的人了！你的赌技是最差的吧！」</p><p>「如果要拜托达斯特，还不如加入阿克西斯教向神祈祷！」</p><p>「全身被扒光的丧家犬不要乱吠！」</p><p>「你说什么！」</p><p>奇斯准备一拳揍过来，我连忙摆出防备架式。泰勒则是一步步缓缓拉近距离。</p><p>「喂，你们几个！不要把我晾在一边！比赛还没结束！」</p><p>雷维王子看到我们无视他开始打起来，便朝着我们喊了几句。</p><p>这么说来，剩下我还没上场，现在是琳恩正在对局。</p><p>我们暂时停手看向赌桌，却没看见琳恩和萝莉梦魔的身影。</p><p>「喂，她们去哪了？」</p><p>「一下子就败北，到休息室去了。」</p><p>「休息室？喂，琳恩跟你赌了什么？」</p><p>我有种不好的预感。雷维王子没回答我，只是低下头躁动起来。</p><p>泰勒跟奇斯赌输后只剩一条内裤。也就是说……</p><p>「你想让她脱成全裸来侍奉你吗！你这色小鬼！」</p><p>「真的假的！呐，达斯特、泰勒，我可以倒戈吗？」</p><p>「别再胡闹了。」</p><p>奇斯一脸严肃地胡说八道，而泰勒一拳挥向他的脑门。</p><p>只见奇斯顿时满地打磙，感觉痛得要命。</p><p>好险，刚刚我的脑中也瞬间闪过同样的想法。</p><p>「不要乱说！那、那种行为对我来说还太早了……而且我早就心有所属……」</p><p>没想到这小鬼这么纯情。</p><p>「等、等一下，你在开玩笑吧？」</p><p>「没问题，重要部位都遮住了。」</p><p>「都快走光了耶！萝莉莎为什么还能若无其事啊！」</p><p>「我习惯了。」</p><p>门后传来琳恩惊慌失措的嗓音，以及萝莉梦魔莫名冷静的声音。</p><p>接着门用力打开后，萝莉梦魔抬头挺胸地走了出来，琳恩则试图躲在她的身后。</p><p>只见两人穿着勉强遮住重要部位，宛如内衣的服装。继那套祭司服之后，萝莉梦魔又被迫换装了啊。</p><p>「唔喔喔喔喔喔喔喔！」</p><p>奇斯和王子的几名随扈们发出了欢呼声。</p><p>雷维王子和泰勒同时别开视线，努力让自己别往她们身上看。我跟奇斯当然是死命地盯着看。</p><p>「我觉得萝莉莎看起来没什么新鲜感。」</p><p>「女孩子都穿上这么羞耻的服装了，至少开心一点吧。」</p><p>虽然萝莉梦魔摆出害羞的动作，但这套衣服跟她平常在店里穿的几乎没两样，当然没什么感觉。</p><p>「琳恩，你也学学萝莉莎，站到前面来啊。」</p><p>「不、不要！我现在觉得丢脸死了！」</p><p>琳恩满脸通红地从萝莉梦魔身后探出头来。</p><p>大方裸露是不错啦，但这种害羞忸怩的模样也不赖。</p><p>「我也觉得有点丢脸。跟平常的打扮不一样。」</p><p>萝莉梦魔虽然这么说，但她似乎很高兴能换下那身祭司服。</p><p>「这样我就三连胜了。只剩你一个。」</p><p>「我都等得不耐烦了。冠军候补即将登场。」</p><p>我一入座，琳恩和萝莉梦魔就站在我身后。</p><p>琳恩是想把我当成掩护，借此在对方的视线中隐藏自己的身影吗？</p><p>我正想回头察看时，她就用双手夹住我的头，强迫我转向前方。</p><p>「咕喔喔！脖子！很痛耶！有什么关系，又不会少块肉！」</p><p>「才不要！要是你又想转过来看，我就把你的眼球挖出来！」</p><p>「超可怕的。想掩饰害羞应该还有其他方法吧……不过，你们为什么要穿这种跟内衣没两样的服装啊？」</p><p>「那是因为琳恩小姐事前放话说『输的人就要换上丢脸的服装，如何！』。我只是被牵连而已……」</p><p>「琳恩，你……」</p><p>「有什么办法嘛！因为对方想逼萝莉莎做出那种可怕的事，我才想让他也尝尝丢人现眼的滋味啊！」</p><p>真是的，平常还要我行事不要太冲动，说些很跩的话。结果看看她自己干了什么好事。</p><p>不但输给小孩子，还被迫换上羞耻的服装，琳恩已经丢脸到快要昏过去了。</p><p>琳恩穿得这么暴露，让我看是无所谓，但让其他人继续看下去，我就觉得很火大。还是赶快结束比赛，让她换回原本的衣服吧。</p><p>我脱下自己的外套披在琳恩身上后，重新面向雷维王子。</p><p>「抱歉，让你久等了。决战开始吧。」</p><p>「前几局都一下子就分出胜负，实在太无聊了。你可以让我尝点乐子吧？」</p><p>连胜三场的雷维王子完全得意忘形了。也对，毕竟他耍老千，当然会赢。</p><p>这场比赛跟以往的赌局不同，绝对不能输。我想用对我有利的游戏项目来决胜负。</p><p>「如果这时候巴尼尔大人在场，肯定就能靠透视未来的双眼夺得胜利了。」</p><p>我也同意萝莉梦魔轻声低喃的这句话。</p><p>如果能请老大帮我占卜获胜的方法，就算我运气再差，也能百发百中地抽到必胜牌。</p><p>「可是，如果为了私欲动用老大的力量，似乎不会有什么好下场。我之前也跟老大提议过，靠他的能力在赌局中赚钱应该比较快，他才告诉我这件事。」</p><p>如果可以洞悉未来，绝对能赢得胜利。但这个世界没这么简单。</p><p>不过，我也觉得这种时候有老大的力量就好了……老大的力量？</p><p>「对了，老大在占卜时说了什么啊？我记得是非常重要的话……」</p><p>「还没决定吗？」</p><p>雷维王子不耐烦地催促道。</p><p>跟萝莉梦魔讨论时花了一点时间。</p><p>「……比赛方式，用卡牌来决胜负如何？」</p><p>「我就听听你的说明吧。」</p><p>「规则非常简单。将标注为一到十三的卡牌放在牌桌上，双方各抽一张，由数字大的那一方获胜。但是最强的十三号，唯独会输给最弱的一号。怎么样，连白痴都听得懂吧？」</p><p>我拿起手边的卡牌洗了一会儿，将十三张牌放在桌面上。</p><p>我的说明结束后，雷维王子双手环胸，紧盯着牌面看。</p><p>「要比几场？」</p><p>「像个男子汉，一局定胜负吧。」</p><p>「好。抽一张就行了吧？」</p><p>他稍稍烦恼了一会儿，但很爽快地选了一张牌。</p><p>接下来轮到我了。</p><p>我偷偷朝身后的萝莉梦魔瞥了一眼。</p><p>只见她闭上眼双手合十，正在拼命祈祷。恶魔会向谁祈祷啊？让我有点在意。</p><p>如果能让我获胜，我当然可以向阿克西斯教徒崇敬的阿库娅女神祈祷，但肯定会徒劳无功吧。再说，要祈求幸运的话，应该向艾莉丝女神祈祷比较有用。</p><p>「都见过本人了，向祂祈祷说不定有效……但还是算了。」</p><p>我的运气奇差无比。</p><p>虽然很不甘心，但是赌技也很差。</p><p>这样的我要向女神祈祷，也已经太迟了。所以……</p><p>「我选这张！」</p><p>我将手放在选择的卡牌上。</p><p>只能凭实力夺取胜利了！</p><p>「就由我先翻牌吧。行吗？」</p><p>「你先请。」</p><p>雷维王子翻过来的牌面数字是——十三。</p><p>看到这张牌后，雷维王子胜券在握地露出坏心又游刃有余的笑容。</p><p>这样就能确定雷维王子耍老千了。我就算指出这一点，他也只会佯装不知情吧。</p><p>「喂喂，达斯特！这下惨了！」</p><p>「奇斯，不要惊慌。学学泰勒乖乖待在一边。」</p><p>泰勒在地板上盘腿而坐，默默地观看着情势发展。</p><p>「可、可是，对方抽到最强的十三耶！你只能从剩下的十二张里面抽到一才能赢！你知道概率是多少吗？是十二分之一耶，喂！」</p><p>「你的运气本来就很差了，还以为能赢吗？」</p><p>奇斯和琳恩一左一右地包夹我，口沫横飞地吠个不停。</p><p>至于剩下的两个人在做什么呢？泰勒不发一语地向神祈祷，萝莉梦魔则紧闭双眼，朝天花板仰起头。</p><p>这些家伙……根本不信任我嘛。</p><p>我将伙伴们叽叽喳喳的杂音抛诸脑后，将双手环在胸前紧盯桌面，幻想着后续的发展。</p><p>只有真正的赌徒，才会在走投无路的状态下打出逆转胜。</p><p>我做了个大大的深呼吸，镇定心神后并扬起视线，就跟那个因为胜券在握笑得一脸狂妄，完全不可爱的小鬼四目相交。</p><p>真想看看那张跩到极点的脸哭泣的模样。</p><p>「怎么，你怕啦？如果当场下跪接受我的要求，我也可以重新考虑喔。」</p><p>「喂喂，谁会做那种没出息的……」</p><p>「好了，下跪吧！快点将额头抵上地板，向他献殷勤！这样一来萝莉莎就能得救，真是太划算了！」</p><p>「哎呀，这笨蛋给您添麻烦了。快点下跪，用舌头把小少爷的鞋子舔得亮晶晶！」</p><p>「混帐王八蛋，不要妨碍我！」</p><p>琳恩和奇斯抓着我的后脑勺，想强迫我低下头去。</p><p>想尽办法甩开他们后，其中一名看似王子护卫的人抓住试图妨碍比赛的奇斯，将他拉到泰勒身边。</p><p>「喂，干嘛！给我放开……啊，不是，我反对暴力。」</p><p>奇斯本来想抵抗，但被凶神恶煞的护卫狠狠一瞪，就变得百依百顺。</p><p>最关键的萝莉梦魔泪眼汪汪地跑了过来。</p><p>「对方抽到最强的牌了耶！不就摆明要输了吗？已经没有胜算了！」</p><p>她抓着我的脖子用力地摇晃。</p><p>「你想杀了我啊！还不一定会输吧。」</p><p>「可是、可是，十三是最强的牌啊。怎么可能赢呢！」</p><p>「你刚刚有听规则吗？十三确实是最强的牌，但有唯一一张牌可以赢过它。」</p><p>听我这么一说，她似乎回想起来了。那张哭哭啼啼的脸变得有些呆滞。</p><p>「这我知道呀。能赢过最强牌面的，就是最弱的一……啊，最弱！」</p><p>萝莉梦魔好像想起那个占卜内容了，她用瞪大到极限的双眼凝视着我。</p><p>「我没有受到幸运女神的眷顾。但是相对地……有个大恶魔在为我撑腰啊！」</p><p>我信心满满地翻开的那张牌——正是最弱的一。</p>`,347),e(f,{src:`/images/E4/01.avif`,alt:`插图`,width:`850`,height:`1257`}),s[15]||=a(`<p>「什、什么！居然抽到一！」</p><p>原本笃定自己会赢的雷维王子从椅子上站起身，指了指那张牌，又无力地瘫坐下来。</p><p>当雷维王子抽到十三时，我就确定自己会赢了。毕竟比赛结果早在一开始就确定了。</p><p>胜利的关键，就是巴尼尔老大的占卜。</p><p>『汝似乎注定会在关键胜负中抽到最弱的手牌！』</p><p>回想起这句话的瞬间，我就想到要用这种方式定胜负。</p><p>也就是说，我早就注定会抽到最弱的卡牌了。根据前面几场比赛，我猜雷维王子一定会耍老千抽取最强卡牌，准备把我打得体无完肤。</p><p>这样一来，我只要订下可以靠最弱卡牌取胜的规则就好了。</p><p>谢谢你，巴尼尔老大！</p><p>「太好啦！」</p><p>我将拳头高举向天，回过头去……伙伴们都笑容满面朝我冲了过来。</p><p>「这家伙真的成功了！」</p><p>「居然在最后的最后帅气取胜！」</p><p>「太棒了，干得好，达斯特！」</p><p>「呀啊啊啊啊！好厉害，达斯特先生太厉害了！」</p><p>萝莉梦魔感动万分地伸手环住我的脖子，紧紧抱住我。</p><p>虽然她的身材毫无起伏，但因为服装近乎全裸，柔软的触感依旧透过衣服传递而来。</p><p>「如果再有料一点，我就会乐翻天呢。」</p><p>「你说什么？」</p><p>「呃，没事。」</p><p>她笑得好恐怖，我还是假装不知道好了。</p><p>「我又输了啊。本来不惜耍老千也想取胜，结果还是赢不了和真先生的朋友……干脆禁止国内的赌博风气好了。」</p><p>完全丧失自信心的雷维王子，趴在桌面上一动也不动。</p><p>「这样让我觉得好像在霸凌小孩子一样，罪孽深重耶。赌博这种事本来就要凭运气啦。别这么沮丧。」</p><p>雷维王子的模样实在太悲惨了，我忍不住开口安慰他。</p><p>这么说来，他跟和真对赌时，好像也输得一塌煳涂。</p><p>我觉得他好可怜，于是将手放上萝莉梦魔的肩膀，将她拉离伙伴身边。</p><p>「喂，安慰他一下吧。我教你一句魔法咒语，可以让灰心丧志的男人瞬间变得神采飞扬。」</p><p>我把那个方法告诉萝莉梦魔后，她刚刚对我赞许有加的态度顿时一扫而空。</p><p>她用无话可说的表情直盯着我看。</p><p>「我好歹也是个梦魔，这点程度对我来说不成问题。真拿你没办法，就让你见识见识我的功力吧。」</p><p>只见她态度骤变，带着自信满满的笑容走到王子身边。</p><p>「小少爷，小少爷。」</p><p>「干嘛？我已经赦免了你的罪，你想去哪就去哪吧。不论结果是赢是输，我本来都打算要释放你的，但在这种状况下说这些话……只像是不服输的表现罢了。」</p><p>雷维王子一脸茫然地抬起头。萝莉梦魔向他露出一抹微笑，做出手臂紧紧夹胸的姿势。</p><p>「你还好吗？请打起精神。要不要揉我的胸部？」</p><p>灰心丧志的时候，只能靠胸部抚慰了！</p><p>对付这种正值思春期的小鬼头，这种诱惑应该会有出奇之效。</p><p>「……那种大小根本不值得揉。」</p><p>「……唔！」</p><p>「喂﹑喂，你这混帐，那可是禁语啊。」</p><p>这句话实在残酷至极，导致萝莉梦魔再度眼角噙泪，准备一拳揍向雷维王子。于是我连忙从她身后架住她。</p><p>「快住手！要是揍了这家伙，事情会一发不可收十啊！」</p><p>「连小孩子都不把我当一回事！连小孩子都不把我放在眼里！呜哇啊啊啊啊啊啊！」</p><p>我连忙将哭着拼命抵抗的萝莉梦魔拉离现场。</p><h2 id="尾声" tabindex="-1"><a class="header-anchor" href="#尾声"><span>尾声</span></a></h2><p>「但没想到居然能逆转胜。到现在还不知道为什么会赢耶！算了啦，呀哈哈哈哈哈！」</p><p>兴高采烈的奇斯举起注满酒的啤酒杯。</p><p>「「「干杯！」」」</p><p>我们也举起啤酒杯庆祝胜利。</p><p>这里是埃尔罗得的酒吧。我们正在举办庆功宴。</p><p>比赛结束后，我们拿到一大笔赔偿金，足以补偿委托失败没拿到的费用。</p><p>多亏有这笔钱，我才能和伙伴们好好享受埃尔罗得的最后一晚。</p><p>「不过，你的运气这么差，真亏你能赢耶。」</p><p>「我看只有狗屎运很强吧！」</p><p>其实都是拜巴尼尔老大的占卜所赐，但没必要说出口。</p><p>「所以是靠我天才般的头脑才会赢！」</p><p>「好啦好啦，就算是偶然，只要赢了就好。」</p><p>「这次就称赞你一下吧。以达斯特来说，表现已经算不错了！」</p><p>「是啊，赢得漂亮。」</p><p>伙伴们全都不肯坦率地称赞我，但今天就原谅他们吧。因为我的心情超好的嘛！</p><p>随后，我们一路喝到半夜，伙伴们都直接醉倒了。</p><p>我走出旅店，想要顺便醒酒。</p><p>「哦，今天是满月啊。」</p><p>又大又圆的月亮高挂在空中。</p><p>夜晚的风拂过因为酒醉而热烫的身体，感觉好舒服。</p><p>「月亮很漂亮吧。」</p><p>「你在干嘛？」</p><p>我回头往上看，发现萝莉梦魔坐在旅店的屋顶上，低头看着我。</p><p>她穿着平常在店里常见的梦魔装扮，露出娇艳欲滴的笑容。性感的模样简直判若两人，让我看得有点入迷。</p><p>「达斯特先生，你知道吗？每逢月圆之夜，梦魔的兴致就会无比高昂，兴奋难耐呢。」</p><p>她从屋顶上轻飘飘地飞落在我眼前。</p><p>接着依偎在我的胸膛，并将手指攀上我的脸颊。</p><p>「你为什么不惜赌上那把重要的剑，也要一较高下呢？比起剑，难道你更重视我……」</p><p>萝莉梦魔用水润的双眸盯着我，那双眼中倒映出一轮满月。</p><p>我轻轻抓着萝莉梦魔的肩膀，将她的身体往横一倒。</p><p>「呕呕呕呕呕呕呕呕呕呕呕。」</p><p>大概是醉到极点了，萝莉梦魔口中涌出大量的呕吐物。</p><p>「耍酒疯耍得太离谱了吧。喝了那么多酒，又做出这种反胃的行为，一定会吐啊。」</p><p>「对噗起……」</p><p>我轻抚她的背，让她把所有呕吐物都吐出来后，本来想直接将她扛起来，却忽然打消了念头。</p><p>我将手穿过她的后背与膝盖后方，温柔地将她抱了起来。</p><p>「咦？达斯特先生？」</p><p>虽然没能完成守护公主殿下的委托，但唯独此时此刻，我就把你当公主殿下对待吧。</p><h2 id="后记" tabindex="-1"><a class="header-anchor" href="#后记"><span>后记</span></a></h2><p>真的万万没想到能写到第四集。</p><p>我越写越觉得达斯特这个角色充满了令人爱不释手的魅力，添加一点渣男的言行举止也不成问题。身为一名写手，我觉得很有意思，每次都能肆无忌惮地大写特写。</p><p>虽然第三集的内容都围绕在爱丽丝身上，但第四集是以「爱丽丝与和真一行人前往埃尔罗得时，如果达斯特他们在暗中监视会发生什么事？」这个构想来发展，应该可以从第三者的视角，再次确认他们的行为有多离谱。</p><p>除此之外，明明是达斯特的伙伴，却没什么存在感的泰勒和奇斯，我这次也为他们增加了戏份。敬请期待两位的活跃（？）表现。</p><p>说到戏份，据说在《美好世界》中堪称首屈一指的那位变态这次也会登场。原本预计在第二集就要让他上场，但阿克西斯教徒就已经够疯狂了，再加上他的话，达斯特他们的存在感就会被完全吞噬，我才有所收敛。</p><p>因此他在第四集中大闹了一场。我非常喜欢这个角色，总是很希望能找机会让他登场，所以这次真的很开心。</p><p>对了，第四集也不能忘记萝莉莎，也就是萝莉梦魔喔。她在各方面都很努力。这个角色跟达斯特搭档时比较容易发挥，因此我也很喜欢她。</p><p>关于第四集的内容就此搁笔吧。我想跟各位分享一件事。那就是我有幸参与了广播剧CD的录音事宜！</p><p>哎呀～～我对配音员的现场演技感到万分钦佩，从头到尾都深受震撼呢。</p><p>真是的，达斯特根本就是达斯特，琳恩跟琳恩像到惊人的程度，萝莉梦魔就是可爱的萝莉梦魔，泰勒是木头人泰勒，奇斯就是个嚣张的奇斯！（欠缺语汇能力）</p><p>我因为太过紧张，完全不记得自己说了些什么，但确实得到了宝贵的经验。</p><p>暁なつめ老师每次都让我自由发挥，真的万分感谢。执笔途中我忽然想到一件事。拉格克莱夫消失后，埃尔罗得的国运应该会衰退吧……雷维王子加油！</p><p>三嶋くろね老师，《美好世界》第十四集的悠悠插图真是太美了！和真等主要角色当然也很棒，但能见到在《笨蛋》中经常登场的悠悠，我觉得好开心。</p><p>忧姫はぐれ老师笔下性感又可爱的插图，每次都让我十分满足！虽然巨乳也不错，但此时此刻的我，觉得像萝莉梦魔那种朴实无华的胸部也很棒。</p><p>拜见三嶋くろね老师在新刊中绘制的插图，让我忍不住窃笑起来。现在居然还有幸看到忧姫はぐれ老师为本书绘制的插图，简直幸福得无与伦比。</p><p>スニーカー编辑部的各位，本次作品难产时帮了我许多忙的M责编，经手本作的相关人士，以及为广播剧CD注入生命力的所有人，真的非常谢谢大家。</p><p>最后，为读完第四集的每位读者献上由衷感谢！</p><div style="text-align:right;"><p>昼熊</p></div>`,103),e(f,{src:`/images/E4/14.avif`,alt:`后记插图`,width:`850`,height:`1257`})])}var u=o(c,[[`render`,l]]);export{s as _pageData,u as default};